const t=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"معدات الوقاية الشخصية (PPE)",subtitle:"Personal Protective Equipment",summary:"التعرّف على معدات الوقاية الشخصية واستخدامها الصحيح",blocks:[{body:"معدات الوقاية الشخصية (PPE) هي خط الدفاع الأخير ضد الإصابات: فقبل اللجوء إليها يجب إزالة الخطر أو تقليله بالضوابط الهندسية وإجراءات العمل (تسلسل الضوابط Hierarchy of Controls). واستخدام معدات الوقاية الشخصية في المصانع ليس اختياريًا، بل إلزامي."},{heading:"1. الأنواع الرئيسية لمعدات الوقاية الشخصية",body:"لكل جزء من الجسم معدات خاصة به:",points:["الرأس: خوذة الحماية (Hard Hat) — للحماية من سقوط الأجسام والصدمات.","العينان: نظارات السلامة (Safety Glasses) — للحماية من الغبار والمواد الكيميائية والشرر والرذاذ المتطاير.","الأذنان: واقيات السمع (Earmuffs / Earplugs) — للحماية من الضجيج العالي للآلات (85 dB(A) فأكثر).","اليدان: القفازات — للحماية من الجروح القطعية والحرارة والمواد الكيميائية.","القدمان: أحذية السلامة ذات المقدمة الفولاذية (Steel Toe) — للحماية من السحق وسقوط الأجسام الثقيلة.","الجسم: ملابس عالية الوضوح (Hi-Vis) بألوان زاهية — ليراك السائقون والعمال الآخرون."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"معدات الوقاية الشخصية (PPE)",description:"الطريقة الصحيحة لارتدائها"}],quiz:[{question:"وفقًا للمعايير الأوروبية، متى يصبح استخدام واقيات السمع إلزاميًا؟",options:[{text:"50 dB",correct:!1},{text:"70 dB(A) فأكثر (متوسط 8 ساعات عمل)",correct:!1},{text:"85 dB(A) فأكثر (متوسط 8 ساعات عمل)",correct:!0},{text:"120 dB(A) فأكثر (متوسط 8 ساعات عمل)",correct:!1}],explanation:"وفقًا للتوجيه الأوروبي 2003/10/EC، عندما يبلغ متوسط مستوى الضجيج خلال 8 ساعات عمل 85 dB(A)، يجب استخدام واقيات السمع. كما تشترط OSHA عند 85 dBA تطبيق برنامج للمحافظة على السمع."},{question:"معدات الوقاية الشخصية (PPE) هي خط الدفاع الأخير ضد الإصابات. ما الذي يجب أن يأتي قبلها؟",options:[{text:"شراء معدات وقاية أغلى ثمنًا",correct:!1},{text:"إزالة الخطر أو تقليله",correct:!0},{text:"مطالبة العمال بالعمل أسرع لتقليل مدة التعرض للخطر",correct:!1},{text:"الانتظار حتى تكشف إصابةٌ مكانَ الخطر",correct:!1}],explanation:"قبل اللجوء إلى معدات الوقاية الشخصية يجب إزالة الخطر أو تقليله بالضوابط الهندسية وإجراءات العمل (تسلسل الضوابط Hierarchy of Controls)؛ فهي خط الدفاع الأخير، واستخدامها في المصانع يبقى إلزاميًا."},{question:"لماذا يرتدي العمال ملابس عالية الوضوح (Hi-Vis) بألوان زاهية؟",options:[{text:"لحماية الجلد من المواد الكيميائية والحرارة",correct:!1},{text:"لتمييز القسم الذي ينتمي إليه كل عامل",correct:!1},{text:"للحفاظ على دفء الجسم في الورش الباردة",correct:!1},{text:"ليراهم السائقون والعمال الآخرون",correct:!0}],explanation:"الملابس عالية الوضوح بألوان زاهية تجعل العامل ظاهرًا ليراه السائقون والعمال الآخرون؛ أما الحماية من المواد الكيميائية والحرارة فتوفّرها معدات أخرى مثل القفازات."}]},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"سلامة الآلات",subtitle:"Machine Safety & Guarding",summary:"حماية العمال من الأجزاء المتحركة في الآلات",blocks:[{body:"الآلات الصناعية ذات قوة كبيرة، ويمكنها في ثانية واحدة أن تسبب إصابات بالغة أو فقدان أحد أعضاء الجسم."},{heading:"1. حواجز حماية الآلات (Machine Guards)",body:"يجب توفر وسائل الحماية هذه على جميع الآلات الخطرة:",points:["الحواجز الثابتة: لتغطية السيور والتروس المتحركة.","زر إيقاف الطوارئ (E-Stop): يجب أن يكون قريبًا من يد العامل، وباللون الأحمر على خلفية صفراء.","حساسات الإيقاف: تتوقف الآلة إذا اقتربت اليد أو الجسم من المنطقة الخطرة."]},{heading:"2. القواعد الذهبية",body:"قبل العمل وفي أثنائه:",points:["لا تُزِل أبدًا حاجز الحماية عن الآلة وهي تعمل.","لا ترتدِ الملابس الفضفاضة أو السلاسل أو الخواتم، واربط الشعر الطويل، كي لا تعلق في الآلة.","إذا تعطّلت الآلة، فأوقفها فورًا بزر E-Stop، ولا تُدخل يدك في الآلة دون تطبيق إجراء عزل الطاقة وإقفالها (LOTO)."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"حواجز حماية الآلات",description:"مثال على حاجز حماية صحيح"}],quiz:[{question:"هل يجوز إزالة حاجز حماية الآلة وهي تعمل؟",options:[{text:"نعم، إذا دعت الحاجة",correct:!1},{text:"لا، لا يجوز ذلك بأي حال من الأحوال",correct:!0},{text:"فقط من أجل التنظيف",correct:!1},{text:"فقط إذا أذن المسؤول المباشر بذلك",correct:!1}],explanation:"إزالة حاجز حماية الآلة وهي تعمل من أخطر السلوكيات. ولا يُجرى التنظيف والإصلاح إلا بعد إيقاف الآلة وعزل طاقتها وإقفالها (LOTO)."},{question:"إذا تعطّلت الآلة في أثناء عملك عليها، فماذا تفعل؟",options:[{text:"أُوقفها فورًا بزر E-Stop",correct:!0},{text:"أُدخل يدي بسرعة وأزيل العائق بيدي",correct:!1},{text:"أتركها تعمل وأبلغ المسؤول لاحقًا",correct:!1},{text:"أُزيل حاجز الحماية لأرى سبب العطل",correct:!1}],explanation:"إذا تعطّلت الآلة، فأوقفها فورًا بزر E-Stop، ولا تُدخل يدك في الآلة دون تطبيق إجراء عزل الطاقة وإقفالها (LOTO)."},{question:"لماذا يجب ألّا ترتدي الملابس الفضفاضة أو السلاسل أو الخواتم قرب الآلات؟",options:[{text:"لأنها تجعل قراءة أزرار التحكم أصعب",correct:!1},{text:"لأنها تخالف قواعد لباس المصنع فقط",correct:!1},{text:"لأنها قد تعلق في الآلة",correct:!0},{text:"لأنها قد تُتلف حواجز حماية الآلة",correct:!1}],explanation:"قد تعلق الملابس الفضفاضة والسلاسل والخواتم والشعر الطويل في الآلة، والآلة يمكن أن تسبب إصابة بالغة في ثانية واحدة؛ لذلك اربط الشعر الطويل أيضًا."}]},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"السلامة الكهربائية",subtitle:"Industrial Electrical Safety (LOTO)",summary:"مخاطر الكهرباء ونظام الإقفال والوسم (LOTO)",blocks:[{body:"تعمل الكهرباء في المصانع بجهد عالٍ؛ ويمكن أن يؤدي الصعق الكهربائي إلى الوفاة أو إلى حروق بالغة."},{heading:"1. نظام الإقفال والوسم (Lockout/Tagout — LOTO)",body:"هذا أهم إجراء قبل إصلاح الآلات أو تنظيفها:",points:["الإقفال (Lockout): افصل مصدر الكهرباء الرئيسي وضع عليه قفلك الشخصي.","الوسم (Tagout): علّق عليه بطاقة مكتوبًا عليها: «يجري العمل عليه — لا تشغّل»، مع اسمك والتاريخ.","يجب أن يبقى المفتاح بيد الشخص الذي يجري الإصلاح فقط؛ وقبل البدء تأكّد من أن الآلة خالية فعلًا من الطاقة (Verify)."]},{heading:"2. فحص الكابلات",body:"افحص دائمًا:",points:["لا تستخدم الكابلات المقطوعة أو التي تظهر أسلاكها.","الكهرباء والماء عدوّان؛ لا تستخدم الأجهزة الكهربائية في الأماكن المبتلة."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"الإقفال والوسم (LOTO)",description:"كيف نستخدم القفل؟"}],quiz:[{question:"ما المقصود بـ LOTO؟",options:[{text:"التنظيف",correct:!1},{text:"فصل الطاقة وإقفالها قبل الإصلاح",correct:!0},{text:"زيادة سرعة الآلة",correct:!1},{text:"إقفال باب الورشة في نهاية الدوام",correct:!1}],explanation:"يُستخدم نظام LOTO كي لا يعيد أحدٌ توصيل الكهرباء بينما يعمل العامل على الآلة (OSHA 29 CFR 1910.147)."},{question:"وضعت قفلك الشخصي وعلّقت البطاقة. ماذا يجب أن تفعل قبل البدء بالإصلاح؟",options:[{text:"أعطي المفتاح لزميل ليحتفظ به",correct:!1},{text:"أشغّل الآلة لحظة لأختبر القفل",correct:!1},{text:"أتأكد من أن الآلة خالية فعلًا من الطاقة",correct:!0},{text:"أبدأ فورًا، فالقفل وحده يكفي للسلامة",correct:!1}],explanation:"قبل البدء تأكّد من أن الآلة خالية فعلًا من الطاقة (Verify)؛ ويبقى المفتاح بيد الشخص الذي يجري الإصلاح فقط، كي لا يعيد أحدٌ توصيل الكهرباء."},{question:"إذا وجدت كابلًا مقطوعًا تظهر أسلاكه، فماذا تفعل؟",options:[{text:"أستخدمه في الأماكن الجافة فقط",correct:!1},{text:"لا أستخدمه",correct:!0},{text:"ألفّه بشريط لاصق وأواصل استخدامه",correct:!1},{text:"أستخدمه للأدوات الخفيفة فقط",correct:!1}],explanation:"لا تستخدم الكابلات المقطوعة أو التي تظهر أسلاكها؛ فالصعق الكهربائي يمكن أن يؤدي إلى الوفاة أو إلى حروق بالغة."}]},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"مطفأة الحريق — تدريب شامل",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"التعرّف على أنواع المطافئ وفئات الحريق، وشرح مفصّل لإجراء PASS",blocks:[{body:"مطفأة الحريق (Fire Extinguisher) أداة أساسية لإخماد الحرائق الصغيرة في مرحلتها الأولى. وفي المصانع يجب على كل موظف أن يعرف كيف يستخدم المطفأة بسرعة وبطريقة صحيحة. إن معرفة أنواع المطافئ وفئات الحريق ستحمي حياتك وحياة زملائك. المطفأة اليدوية لا تعمل إلا بضع ثوانٍ، لذا يجب توجيهها بشكل صحيح. وإذا كبرت النار أو كثر الدخان، فاترك المطفأة واخرج واتصل بالرقم 115."},{heading:"1. فئات الحريق وفق NFPA (Fire Classes)",body:"وفقًا للنظام الأمريكي (NFPA) تُقسم الحرائق إلى 5 فئات، وتحتاج كل فئة إلى مطفأة مناسبة. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.",points:["الفئة A (المواد الصلبة): الخشب، الورق، القماش، البلاستيك. المطفأة: الماء، الرغوة، مسحوق ABC.","الفئة B (السوائل والغازات القابلة للاشتعال): البنزين، النفط الأبيض (الكيروسين)، الزيوت، الكحول، الغاز. السوائل: CO₂ أو مسحوق ABC أو الرغوة؛ وللكحول والمذيبات القطبية الأخرى: CO₂ أو المسحوق الجاف أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها. الغاز: أوقف الغاز أولًا إذا كان ذلك آمنًا، ولا تُطفئ أبدًا لهب غاز لا تستطيع إيقافه. (لا تستخدم الماء أبدًا!)","الفئة C (المعدات الكهربائية الموصولة بالتيار): المفاتيح الكهربائية، المحوّلات، اللوحات الكهربائية، المولّدات. المطفأة: CO₂، مسحوق ABC، العامل النظيف (Clean Agent). (لا تستخدم الماء أو الرغوة إلا إذا أظهر الملصق تصنيف الفئة C أو علامة الاختبار الكهربائي، كما في بعض مطافئ رذاذ الماء (water mist)!)","الفئة D (المعادن): المعادن القابلة للاشتعال — المغنيسيوم، التيتانيوم، الصوديوم، ومسحوق الألمنيوم. المطفأة: فقط مطفأة من الفئة D أو مادة يذكر ملصقها هذا المعدن؛ فالمادة تختلف من معدن لآخر. (قد يسبب الماء انفجارًا!)","الفئة K (المطابخ): زيوت الطهي والدهون. المطفأة: المادة الكيميائية الرطبة (Wet Chemical). (الماء ينثر الزيت الساخن!) — وهي الفئة F في EN 2."]},{heading:"2. أنواع المطافئ في المصانع",body:"اللون ليس فئة الحريق. وفق BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة. وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا. والفئات أدناه بأحرف NFPA:",points:["مطفأة الماء (Water): أحمر بالكامل، بلا شريط — للفئة A فقط (الخشب، الورق). لا تستخدمها أبدًا للكهرباء أو الزيت!","مطفأة CO₂: شريط أسود في بريطانيا — للفئة B وللمعدات الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). يخرج منها غاز شديد البرودة ويصبح البوق (Horn) شديد البرودة؛ أمسك المقبض فقط ولا تمسك البوق أبدًا، فقد تُصاب يدك بحروق البرد! مدى CO₂ قصير ولا تصلح لحرائق الخشب والورق العميقة: ابدأ من المسافة المحددة على ملصقها ولا تقترب إلا كلما صغرت النار. وفي الغرف الصغيرة اخرج بعد الاستخدام وهوِّ المكان، لأن CO₂ يقلّل الأكسجين.","مطفأة مسحوق ABC (Dry Powder): شريط أزرق في بريطانيا — للفئات A وB وC (وليس D وK). وهي النوع الأكثر انتشارًا. يخرج منها مسحوق أبيض؛ ومن عيوبها أنها تحجب الرؤية وتلوّث المعدات.","مطفأة الرغوة (Foam/AFFF): شريط كريمي في بريطانيا — للفئتين A وB. تنتشر الرغوة على سطح السائل وتعزله عن الأكسجين. لا تستخدمها للكهرباء!","مطفأة العامل النظيف (Clean Agent): يختلف تصنيفها حسب الطراز، فاقرأ الملصق (غالبًا B وC بأحرف NFPA، وبعض الطرازات للفئة A أيضًا) — للمعدات الحساسة وغرف الخوادم. لا تترك بقايا ولا تُلحق ضررًا بالأجهزة الإلكترونية.","المطفأة الخاصة (Class D): للمعادن القابلة للاشتعال في المصانع — ويجب أن يذكر ملصقها المعدن المستخدم في المكان. لا ترشّ الماء أبدًا على معدن مشتعل!"]},{heading:"3. إجراء PASS — بالتفصيل",body:"قبل استخدام المطفأة، يجب أن تكون كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب. وPASS هي الطريقة العامة لمعظم المطافئ اليدوية؛ أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعامل النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة:",points:["P = Pull (اسحب): اسحب مسمار الأمان (Safety Pin). يمنع هذا المسمار تشغيل المطفأة عن طريق الخطأ.","A = Aim (صوّب): وجّه فوهة المطفأة نحو قاعدة النار — لا نحو رأس اللهب! فوقود النار في القاعدة.","S = Squeeze (اضغط): اضغط على مقبضي المطفأة بقوة لتخرج مادة الإطفاء.","S = Sweep (حرّك): حرّك الفوهة يمينًا ويسارًا فوق قاعدة النار حتى تنطفئ تمامًا؛ ثم راقب المكان كي لا تشتعل النار من جديد."]},{heading:"4. الفحص الشهري للمطافئ",body:"الفحص البصري مرة كل شهر، يجريه الشخص المسؤول (NFPA 10):",points:["ضغط المطفأة (Pressure Gauge)، إن وُجد مؤشر: يجب أن يكون المؤشر ضمن المنطقة الخضراء. مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة.","مسمار الأمان وختمه: يجب أن يكونا في مكانهما وغير مكسورين.","الفوهة (Nozzle): يجب ألّا تكون مكسورة أو مسدودة.","جسم المطفأة: يجب ألّا يكون صدئًا أو مشقوقًا أو متضررًا.","بطاقة الفحص والملصق: يجب أن يُدوَّن على البطاقة تاريخ آخر فحص؛ وأن يكون الملصق مقروءًا ومتّجهًا إلى الخارج؛ وأن تكون المطفأة في مكانها، ظاهرة وسهلة الوصول.","ملاحظة: افصل بين هذه الأمور. الفحص والصيانة السنوية على يد فنّي مؤهَّل؛ وإعادة التعبئة (Recharge) بعد أي استخدام، ولو كان قصيرًا؛ وصيانة السنوات الست: تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار هيدروستاتيكي كل 12 سنة ويُفحص داخلها كل 6 سنوات؛ والاختبار الهيدروستاتيكي (Hydrostatic Test، اختبار ضغط جسم المطفأة) كل 5 سنوات لمطافئ الماء والرغوة (AFFF) وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ، وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم. وموعد الاختبار ليس موعدًا للاستبدال. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك."]},{heading:"5. مخاطر خاصة في المصانع",body:"المصنع مكان حساس للأسباب الآتية:",points:["المواد الكيميائية: المذيبات، الكحول، الثنر — كلها من الفئة B.","الكهرباء ذات الجهد العالي: اللوحات الكهربائية والمحوّلات — الفئة C (NFPA).","غبار الخشب والطحين: قد يسبب انفجار الغبار (Dust Explosion) في بعض المصانع.","اللحام والقطع: يمكن أن يسبب شرر اللحام حرائق من الفئتين A وB.","مخزن الوقود: يجب أن يكون في غرفة خاصة أو خارج المبنى، وأن تكون المطفأة المناسبة (رغوة أو مسحوق) قريبة منه.","أماكن التثبيت: ضع المطافئ قرب الأبواب والممرات؛ ويجب ألّا تزيد مسافة الوصول إلى مطفأة الفئة A على 23 مترًا (75 قدمًا)، وللسوائل 9-15 مترًا (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"مطفأة الحريق في المصانع",description:"إجراء PASS وأنواع المطافئ بالفيديو"}],quiz:[{question:"بأحرف NFPA، لأيّ فئات الحريق تصلح مطفأة CO₂؟",options:[{text:"A وD",correct:!1},{text:"B وC",correct:!0},{text:"A وK",correct:!1},{text:"D وK",correct:!1}],explanation:"تصلح مطفأة CO₂ للسوائل القابلة للاشتعال (B) والمعدات الكهربائية (C)، لأنها لا تترك بقايا ولا توصل الكهرباء. وفي EN 2 تعني C حرائق الغاز، ولا تُصنَّف مطفأة CO₂ لها."},{question:"في إجراء PASS، إلى أين يجب توجيه فوهة المطفأة؟",options:[{text:"رأس اللهب",correct:!1},{text:"قاعدة النار",correct:!0},{text:"بعيدًا عن النار",correct:!1},{text:"الدخان قرب سقف الغرفة",correct:!1}],explanation:"وجّه الفوهة دائمًا نحو قاعدة النار، لأن وقود النار موجود هناك."},{question:"لماذا لا يُسكب الماء على حريق الزيت (الفئة K)؟",options:[{text:"لا يُحدث أيّ تأثير",correct:!1},{text:"الماء ينثر الزيت المشتعل ويُحدث لهبًا كبيرًا",correct:!0},{text:"الزيت يمتص الماء فيحترق ببطء أكثر فقط",correct:!1},{text:"الماء نفسه يحترق",correct:!1}],explanation:"يغلي الماء فورًا عند ملامسته الزيت الساخن ويقذف الزيت المشتعل في الهواء، فتتكوّن كرة لهب كبيرة (Fireball). استخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical) أو غطاءً، واقطع مصدر الحرارة."}]},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"First Aid & CPR — Complete Training",summary:"تدريب شامل على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR) والتصرّف في حالات الطوارئ في المصانع",blocks:[{body:"الإسعافات الأولية (First Aid) هي المساعدة الأولية التي تُقدَّم للشخص المصاب أو المريض قبل وصول الفرق الطبية. وخطر الإصابة في المصانع مرتفع جدًا — بدءًا من الجروح والحروق وصولًا إلى الصدمات الكهربائية والسقوط من أماكن مرتفعة. لذا يجب على كل موظف أن يعرف كيف يتصل بالإسعاف (122)، وكيف يُجري الإنعاش القلبي الرئوي (CPR)، ويوقف النزيف، ويحمي المصاب حتى وصول سيارة الإسعاف. وقد أُعدّ هذا الدرس وفق إرشادات AHA 2025 وبرنامج Stop the Bleed."},{heading:"1. الضغطات الصدرية والتنفس (CPR) — بالتفصيل",body:"الإنعاش القلبي الرئوي (CPR) إجراء لإنقاذ الحياة عندما يتوقف قلب الإنسان ويتوقف تنفّسه الطبيعي. اتبع الخطوات الآتية:",points:["1. سلامة المكان: قبل أي شيء تأكّد من أن المكان آمن (لا كهرباء ولا نار ولا غاز)، كي لا تصبح أنت الضحية الثانية.","2. الاستجابة: اهزز كتفي المصاب بقوة واسأله بصوت عالٍ: «هل أنت بخير؟ هل تسمعني؟».","3. طلب المساعدة: إذا لم يستجب وكان لا يتنفس، أو يتنفس تنفسًا غير طبيعي فقط (شهقات)، فاتصل فورًا بالرقم 122 (أو كلّف شخصًا آخر بالاتصال) واطلب إحضار جهاز إزالة الرجفان الخارجي الآلي (AED).","4. الضغطات الصدرية (Compressions): ضع كعب إحدى يديك في منتصف الصدر (النصف السفلي من عظم القص) وضع اليد الأخرى فوقها. اضغط 30 ضغطة قوية وسريعة: بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة، واترك الصدر يرتدّ كاملًا.","5. التنفس: أمِل الرأس إلى الخلف وارفع الذقن، وأغلق الأنف وأعطِ نفَسين (مدة كل منهما نحو ثانية واحدة، حتى يرتفع الصدر). وإذا لم تستطع أو لم ترغب في إعطاء الأنفاس، فاستمر في الضغطات الصدرية فقط.","6. الاستمرار (30:2): استمر في 30 ضغطة ونفَسين حتى تصل سيارة الإسعاف، أو يصبح جهاز AED جاهزًا، أو يبدأ المصاب بالتنفس الطبيعي.","7. استخدام جهاز AED: فور وصوله شغّله، وألصق الأقطاب اللاصقة (Pads) على الصدر العاري، واتبع الأوامر الصوتية للجهاز؛ ولا تلمس المصاب في أثناء إعطاء الصدمة."]},{heading:"2. السيطرة على النزيف (Stop the Bleed)",body:"النزيف الشديد قد يقتل الإنسان في وقت قصير، لذا اتصل بالرقم 122 ونفّذ الخطوات الآتية بسرعة:",points:["الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة بكلتا يديك. وإذا تشبّع القماش بالدم فلا تُزِله؛ بل ضع قطعة أخرى فوقه واستمر في الضغط.","حشو الجرح (Wound Packing): إذا كان الجرح عميقًا (كما في الفخذ أو الإبط أو الرقبة)، فاحشُ الجرح من الداخل بقماش نظيف أو بشاش مرقئ (موقف للنزيف) واضغط بقوة. لا ترفع الطرف المصاب ولا تبحث عن نقاط الضغط (Pressure Points).","العاصبة (Tourniquet): إذا كان نزيف الذراع أو الساق مهددًا للحياة، فاربط العاصبة مبكرًا وبإحكام على بعد 5-7 سم فوق الجرح (باتجاه الجسم)، وسجّل الوقت، ولا تُرخِها أبدًا.","الجسم المنغرس: إذا انغرس جسم حديدي أو زجاجي في الجرح، فلا تُخرجه أبدًا! فذلك سيزيد النزيف. اضغط حوله وثبّته."]},{heading:"3. علاج الحروق",body:"الحروق في المصانع خطيرة؛ تعامل معها على النحو الآتي، واتصل بالرقم 122 في حالة الحروق الكبيرة أو حروق الوجه واليدين:",points:["الحروق الحرارية: صبّ فورًا ماءً جاريًا باردًا (وليس ماءً مثلّجًا) على الحرق لمدة 20 دقيقة. وانزع الخواتم والساعة بسرعة قبل أن يتورّم الطرف المصاب.","الحروق الكيميائية: انزع الملابس الملوّثة واغسل الجلد بكمية كبيرة من الماء الجاري لمدة 20 دقيقة أو أكثر، وراجع صحيفة بيانات السلامة (SDS) الخاصة بالمادة.","الحروق الكهربائية: أول ما تفعله هو قطع الكهرباء! ثم برّد الحرق كما تبرّد الحرق الحراري واتصل بالرقم 122، لأن الكهرباء قد تُلحق الضرر بالقلب وبالأعضاء الداخلية.","تنبيه: لا تفقأ فقاعات الحروق، ولا تستخدم الثلج أو الزبدة والدهون أو معجون الأسنان أو المراهم دون إرشاد طبي."]},{heading:"4. الكسور وإصابات العمود الفقري",body:"عند السقوط من أماكن مرتفعة أو الاشتباه بوجود كسر:",points:["التجبير (Splinting): إذا اشتبهت بوجود كسر، فلا تحرّك الطرف المصاب. ثبّته على الوضع الذي هو عليه بقطعة خشب أو كرتون لتخفيف الألم.","حماية الظهر والرقبة: إذا سقط شخص من مكان مرتفع، فلا تحرّكه إلا إذا كان المكان خطرًا (كوجود حريق)، لأن التحريك قد يسبب الشلل. ثبّت الرأس واتصل بالرقم 122.","التبريد: لتخفيف التورّم (Swelling)، لُفّ الثلج بقطعة قماش وضعه على موضع الألم لمدة 20 دقيقة؛ ولا تضع الثلج مباشرة على الجلد."]},{heading:"5. الصعق الكهربائي والإنقاذ",body:"يمكن للكهرباء أن توقف القلب؛ نفّذ الإجراءات الآتية:",points:["اقطع الكهرباء فورًا: لا تلمس المصاب حتى تُقطع الكهرباء، لأن الكهرباء ستصعقك أنت أيضًا.","الإبعاد الآمن: إذا لم تتمكن من قطع الكهرباء وكان الجهد منخفضًا، فأبعد السلك عن المصاب بعصا خشبية جافة أو بأداة بلاستيكية، وقف على سطح جاف. ولا تقترب من خطوط الجهد العالي، واتصل بالرقم 115.","الفحص الطبي: يجب على كل من تعرّض للصعق الكهربائي، حتى لو شعر بأنه بخير، أن يذهب إلى المستشفى لفحص القلب؛ اتصل بالرقم 122."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"الإنعاش القلبي الرئوي (CPR) والإسعافات الأولية",description:"التدريب على CPR ومساعدة المصابين في المصانع"}],quiz:[{question:"في الإنعاش القلبي الرئوي (CPR)، كم يجب أن يكون معدل الضغطات الصدرية في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"140-160",correct:!1}],explanation:"وفقًا لإرشادات AHA 2025، يبلغ معدل الضغطات 100-120 ضغطة في الدقيقة، بعمق 5-6 سم للبالغين، كي يصل الدم إلى الدماغ."},{question:"إذا انغرس جسم حادّ في الجرح، فماذا تفعل؟",options:[{text:"أُخرجه",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"أُبعد يدي عنه ولا أفعل شيئًا",correct:!1},{text:"أغسله بالماء",correct:!1}],explanation:"إخراج الجسم سيزيد النزيف. يجب أن يبقى في مكانه وأن يُثبَّت حتى يُخرجه الطبيب في المستشفى."},{question:"إذا تعرّض شخص للصعق الكهربائي، فما أول ما تفعله؟",options:[{text:"أمسك يده",correct:!1},{text:"أُجري له CPR",correct:!1},{text:"أقطع الكهرباء",correct:!0},{text:"أصبّ عليه الماء",correct:!1}],explanation:"يجب أولًا قطع مصدر الكهرباء كي لا تصعقك الكهرباء أنت أيضًا؛ ثم اتصل بالرقم 122 وابدأ CPR إذا لزم الأمر."}]},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"المواد الكيميائية (SDS)",subtitle:"Chemical Safety & Labelling",summary:"التعامل مع المواد الكيميائية والتعرّف على مخاطرها",blocks:[{body:"يمكن أن تسبب المواد الكيميائية في المصانع حروقًا جلدية أو تسممًا أو حرائق أو انفجارات."},{heading:"1. ما صحيفة بيانات السلامة (SDS)؟",body:"تقدّم صحيفة بيانات السلامة (Safety Data Sheet — SDS) معلومات كل مادة في 16 قسمًا، منها:",points:["تركيب المادة ومخاطرها.","معدات الوقاية الشخصية (PPE) المطلوبة (قناع التنفس، القفازات، النظارات).","الإسعافات الأولية في حال ملامسة المادة للجسم، وطرق إطفاء الحريق."]},{heading:"2. رموز GHS",body:"بعض العلامات الموجودة على العبوات والعلب:",points:["اللهب (Flame): مادة قابلة للاشتعال.","الجمجمة والعظمتان المتقاطعتان (Skull and Crossbones): مادة سامة قاتلة.","التآكل (Corrosion): مادة حمضية أو قلوية تُتلف الجلد والمعادن."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"صحيفة بيانات السلامة (SDS)",description:"علامات الخطر وفق GHS"}],quiz:[{question:"أين يمكننا أن نعرف نوع قناع التنفس المطلوب لمادة كيميائية؟",options:[{text:"من العلامات الموجودة على الجدار",correct:!1},{text:"في صحيفة SDS",correct:!0},{text:"أسأل زميلي",correct:!1},{text:"لا حاجة إلى قناع",correct:!1}],explanation:"تقدّم صحيفة SDS جميع معلومات الحماية الخاصة بتلك المادة، ومنها نوع معدات الوقاية الشخصية المطلوبة (القسم 8)."},{question:"ماذا يعني رمز الجمجمة والعظمتين المتقاطعتين (Skull and Crossbones) على العبوة؟",options:[{text:"مادة قابلة للاشتعال تشتعل بسهولة",correct:!1},{text:"مادة سامة قاتلة",correct:!0},{text:"مادة حمضية أو قلوية تُتلف الجلد والمعادن",correct:!1},{text:"مادة تضر بالبيئة فقط",correct:!1}],explanation:"الجمجمة والعظمتان المتقاطعتان علامة المادة السامة القاتلة؛ أما اللهب (Flame) فهو علامة المادة القابلة للاشتعال، والتآكل (Corrosion) علامة المادة الحمضية أو القلوية."},{question:"إلى جانب المخاطر ومعدات الوقاية الشخصية المطلوبة، ما الذي تقدّمه صحيفة SDS أيضًا؟",options:[{text:"سعر المادة واسم المورّد",correct:!1},{text:"مواعيد تنظيف مخزن المواد الكيميائية",correct:!1},{text:"أسماء العمال المسموح لهم باستخدامها",correct:!1},{text:"الإسعافات الأولية وطرق إطفاء الحريق",correct:!0}],explanation:"تقدّم صحيفة SDS معلومات كل مادة في 16 قسمًا، منها: المخاطر، ومعدات الوقاية الشخصية المطلوبة، والإسعافات الأولية في حال ملامسة المادة للجسم، وطرق إطفاء الحريق."}]},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"العمل في الأماكن المرتفعة",subtitle:"Fall Protection & Ladders",summary:"الوقاية من السقوط من السقالات والأسطح والسلالم",blocks:[{body:"السقوط من الأماكن المرتفعة أحد الأسباب الرئيسية للوفاة في المصانع ومواقع البناء."},{heading:"1. الحماية من السقوط",body:"يتطلب كل عمل على ارتفاع (وفق OSHA: من 1.2 متر في أماكن العمل الصناعية، ومن 1.8 متر في أعمال البناء) ما يأتي:",points:["حزام الأمان الكامل للجسم (Full Body Harness): يُرتدى بشكل صحيح ومُحكم.","حبل الأمان (Lanyard): يجب أن يكون مثبّتًا بنقطة تثبيت متينة (Anchor Point).","حواجز الحماية (Guardrails): حول السقالات والأسطح والحواف المكشوفة."]},{heading:"2. سلامة السلالم (Ladders)",body:"قاعدة نقاط التماس الثلاث:",points:["يجب أن تكون 3 من أطراف الجسم (قدمان ويد، أو يدان وقدم) على السلّم دائمًا.","يجب أن تكون زاوية وضع السلّم بنسبة 4:1 (لكل 4 أمتار من الارتفاع، تكون قاعدة السلّم على بُعد متر واحد من الجدار)."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"العمل على ارتفاع",description:"استخدام حزام الأمان الكامل للجسم"}],quiz:[{question:"ما معنى قاعدة النقاط الثلاث على السلّم؟",options:[{text:"ألا يقف على السلّم أكثر من 3 أشخاص في الوقت نفسه",correct:!1},{text:"أن تبقى عليه 3 دقائق",correct:!1},{text:"أن تكون 3 من أطراف الجسم متصلة بالسلّم دائمًا",correct:!0},{text:"أن تربط السلّم بـ 3 حبال",correct:!1}],explanation:"تهدف قاعدة النقاط الثلاث إلى ألّا يفقد العامل توازنه فيسقط."},{question:"يصل سلّم إلى ارتفاع 4 أمتار على الجدار. على أي بُعد من الجدار يجب أن تكون قاعدته؟",options:[{text:"نصف متر",correct:!1},{text:"متر واحد",correct:!0},{text:"متران",correct:!1},{text:"4 أمتار",correct:!1}],explanation:"يجب أن تكون زاوية وضع السلّم بنسبة 4:1: لكل 4 أمتار من الارتفاع، تكون قاعدة السلّم على بُعد متر واحد من الجدار."},{question:"بماذا يجب تثبيت حبل الأمان (Lanyard) الخاص بحزام الأمان الكامل للجسم؟",options:[{text:"بحزام أدوات العامل نفسه",correct:!1},{text:"بالسلّم الذي يقف عليه العامل",correct:!1},{text:"بنقطة تثبيت متينة (Anchor Point)",correct:!0},{text:"بأي أنبوب أو كابل قريب",correct:!1}],explanation:"يجب أن يكون حبل الأمان مثبّتًا بنقطة تثبيت متينة (Anchor Point)، وأن يُرتدى حزام الأمان الكامل للجسم بشكل صحيح ومُحكم."}]},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"الأماكن الضيقة والمحصورة",subtitle:"Confined Space Safety",summary:"العمل داخل الخزانات والأنابيب وغرف التفتيش",blocks:[{body:"الأماكن المحصورة خطرة لأن الهواء لا يتجدّد فيها، وقد ينخفض فيها الأكسجين، وتتجمّع فيها الغازات القاتلة."},{heading:"1. المخاطر الرئيسية",body:"قبل أن تدخل، اعلم ما يأتي:",points:["نقص الأكسجين (أقل من 19.5%): يؤدي إلى الاختناق.","الغازات السامة مثل CO (عديم الرائحة) وH₂S (الذي يُعطّل حاسة الشم عند التراكيز العالية).","خطر الحريق والانفجار إذا وُجدت غازات أو أبخرة قابلة للاشتعال."]},{heading:"2. إجراءات الدخول",body:"يجب توفّر الشروط الآتية:",points:["فحص الهواء بجهاز قياس الغازات (Gas Monitor) قبل الدخول وفي أثناء العمل.","وجود مراقب (Attendant) يبقى في الخارج، ويُبقي عينه على العامل في الداخل، ولا يدخل بأي حال من الأحوال.","يجب أن يكون تصريح العمل (Permit) ووسائل الاتصال وخطة الإنقاذ جاهزة."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"الأماكن المحصورة",description:"فحص الهواء"}],quiz:[{question:"هل يجوز للمراقب في الخارج أن يدخل دون معدات لإنقاذ زميله؟",options:[{text:"نعم، بدافع الإنسانية",correct:!1},{text:"لا، لأنه هو أيضًا سيختنق",correct:!0},{text:"نعم، إذا حبس أنفاسه",correct:!1},{text:"نعم، إذا كان الزميل قريبًا جدًا من المدخل",correct:!1}],explanation:"وفقًا لدراسات NIOSH، فإن جزءًا كبيرًا من الوفيات في الأماكن المحصورة هم أشخاص دخلوا للإنقاذ دون معدات أو تدريب. ويجب على المراقب أن يستدعي فريق الإنقاذ ويتصل بالرقم 115."},{question:"متى يجب فحص الهواء في المكان المحصور بجهاز قياس الغازات (Gas Monitor)؟",options:[{text:"مرة واحدة فقط في اليوم الأول من العمل",correct:!1},{text:"فقط إذا شمّ أحدٌ رائحة غير عادية",correct:!1},{text:"بعد انتهاء العمل",correct:!1},{text:"قبل الدخول وفي أثناء العمل",correct:!0}],explanation:"يُفحص الهواء قبل الدخول وفي أثناء العمل، لأن الأكسجين قد ينخفض والغازات القاتلة قد تتجمّع؛ وCO عديم الرائحة، فالشمّ ليس فحصًا."},{question:"داخل خزان، لم يعد أحد العمال يشمّ رائحة H₂S فجأة. ماذا قد يعني ذلك؟",options:[{text:"أن الغاز زال وأصبح الهواء آمنًا للتنفس",correct:!1},{text:"أن الغاز عطّل حاسة الشم",correct:!0},{text:"أن مروحة التهوية بدأت تعمل بشكل صحيح",correct:!1},{text:"أن الغاز تحوّل إلى بخار ماء غير ضار",correct:!1}],explanation:"يُعطّل H₂S حاسة الشم عند التراكيز العالية، لذا فإن اختفاء الرائحة لا يعني زوال الغاز؛ ولا يبيّن سلامة الهواء إلا جهاز قياس الغازات (Gas Monitor)."}]},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"الضجيج وحماية السمع",subtitle:"Hearing Conservation",summary:"الحماية من ضجيج الآلات الكبيرة",blocks:[{body:"يحدث الصمم أو ضعف السمع الناتج عن ضجيج المصانع تدريجيًا، ولا يمكن علاجه."},{heading:"1. مستويات الضجيج",body:"متى يصبح الضجيج خطرًا؟",points:["85 dB(A): حدّ بداية الخطر لمدة 8 ساعات عمل.","100 dB(A): دون حماية يكون آمنًا لمدة 15 دقيقة فقط في اليوم (NIOSH).","علامة: إذا شعرت بطنين (Tinnitus) في أذنيك بعد العمل، فهذا يعني أن الضجيج كان عاليًا جدًا."]},{heading:"2. معدات الحماية",body:"معدات حماية السمع (Hearing Protection Devices — HPD):",points:["سدادات الأذن (Earplugs): توفّر حماية جيدة إذا وُضعت بشكل صحيح.","أغطية الأذن (Earmuffs): سهلة الارتداء ومناسبة للضجيج العالي.","استخدام النوعين معًا في الأماكن شديدة الضجيج."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"الضجيج",description:"كيف تستخدم واقيات السمع؟"}],quiz:[{question:"إذا بلغ الضجيج 100 dB(A)، فكم من الوقت يمكنك البقاء دون واقيات سمع وفقًا لـ NIOSH؟",options:[{text:"45 دقيقة",correct:!1},{text:"15 دقيقة",correct:!0},{text:"4 ساعات",correct:!1},{text:"وردية كاملة من 8 ساعات",correct:!1}],explanation:"وفقًا لـ NIOSH، كل زيادة بمقدار 3 dB تخفض الوقت الآمن إلى النصف: 85 dB(A) لمدة 8 ساعات، و100 dB(A) لمدة 15 دقيقة فقط."},{question:"بعد انتهاء العمل، شعرت بطنين (Tinnitus) في أذنيك. ماذا يعني ذلك؟",options:[{text:"أن أذنيك بدأتا تعتادان الضجيج",correct:!1},{text:"أن الضجيج كان عاليًا جدًا",correct:!0},{text:"أن سدادات الأذن كانت ضيقة جدًا",correct:!1},{text:"أنه أمر طبيعي ولا يعني شيئًا",correct:!1}],explanation:"الطنين في الأذنين بعد العمل علامة على أن الضجيج كان عاليًا جدًا؛ وضعف السمع الناتج عن الضجيج يحدث تدريجيًا ولا يمكن علاجه، لذا استخدم واقيات السمع."},{question:"في الأماكن شديدة الضجيج، كيف يجب أن تكون حماية السمع؟",options:[{text:"القطن بدلًا من سدادات الأذن",correct:!1},{text:"دون حماية، ولكن مع فترات راحة قصيرة",correct:!1},{text:"سدادات الأذن وأغطية الأذن معًا",correct:!0},{text:"وضع اليدين على الأذنين عند ارتفاع الصوت",correct:!1}],explanation:"في الأماكن شديدة الضجيج استخدم النوعين معًا: سدادات الأذن توفّر حماية جيدة إذا وُضعت بشكل صحيح، وأغطية الأذن سهلة الارتداء ومناسبة للضجيج العالي."}]},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"رفع الأحمال (Ergonomics)",subtitle:"Safe Lifting Techniques",summary:"الوقاية من آلام الظهر والعضلات",blocks:[{body:"إصابات الظهر من أكثر الإصابات انتشارًا في المصانع، وسببها الرفع الخاطئ للأحمال."},{heading:"1. الطريقة الصحيحة للرفع",body:"تطبيق الخطوات الآتية يحمي ظهرك:",points:["اثنِ ركبتيك: استخدم قوة ساقيك، لا قوة ظهرك.","قرّب الحمل من جسمك: كلما ابتعد الحمل عنك زاد الضغط على ظهرك.","حافظ على استقامة ظهرك: لا تحنِ ظهرك عندما ترفع شيئًا ثقيلًا.","لا تلوِ جسمك: إذا أردت نقل الحمل إلى أحد الجانبين، فاستدر بجسمك كله مستخدمًا قدميك."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"رفع الحمل",description:"الأسلوب الصحيح"}],quiz:[{question:"عند رفع شيء ثقيل، على ماذا يجب أن يقع الجهد؟",options:[{text:"عضلات أسفل الظهر",correct:!1},{text:"عضلات الساقين",correct:!0},{text:"عضلات الكتفين",correct:!1},{text:"اليدان فقط",correct:!1}],explanation:"عضلات الساقين أقوى، وهي تحمي الظهر من الإصابة."},{question:"عند رفع حمل ثقيل، أين يجب أن يكون الحمل؟",options:[{text:"على امتداد ذراعيك بعيدًا عن جسمك",correct:!1},{text:"فوق رأسك",correct:!1},{text:"على أحد جانبي جسمك",correct:!1},{text:"قريبًا من جسمك",correct:!0}],explanation:"قرّب الحمل من جسمك: كلما ابتعد الحمل عنك زاد الضغط على ظهرك."},{question:"تحتاج إلى نقل حمل إلى أحد الجانبين. كيف تستدير؟",options:[{text:"ألوي جسمي وأُبقي قدميّ في مكانهما",correct:!1},{text:"أستدير بجسمي كله مستخدمًا قدميّ",correct:!0},{text:"أحني ظهري جانبًا نحو المكان الجديد",correct:!1},{text:"أرمي الحمل بسرعة إلى الجهة الأخرى لأوفّر الجهد",correct:!1}],explanation:"لا تلوِ جسمك: إذا أردت نقل الحمل إلى أحد الجانبين، فاستدر بجسمك كله مستخدمًا قدميك، وحافظ على استقامة ظهرك."}]},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"الغازات والتهوية",subtitle:"Ventilation & Toxic Gases",summary:"التحكم في جودة الهواء والغازات السامة",blocks:[{body:"التهوية الصحيحة في المصنع مهمة لمنع تراكم الغبار والغازات التي تسبب أمراض الجهاز التنفسي."},{heading:"1. أول أكسيد الكربون (CO)",body:"الغاز القاتل الصامت:",points:["عديم اللون والرائحة.","ينتج عن احتراق الوقود وعن محركات البنزين والديزل (مثل المولّدات والرافعات الشوكية).","الأعراض: الصداع، والدوار، والغثيان، وفقدان الوعي. إذا شعرت بهذه الأعراض، فاخرج فورًا إلى الهواء الطلق واتصل بالرقم 122."]},{heading:"2. أنواع التهوية",body:"كيف يتجدّد الهواء؟",points:["التهوية الطبيعية: الأبواب والنوافذ المفتوحة.","التهوية الاصطناعية: المراوح وأنظمة الشفط الموضعي للهواء (Local Exhaust).","الوقاية الشخصية: أقنعة التنفس ذات المرشّحات وفق صحيفة SDS؛ لكن أقنعة المرشّحات لا تحمي من CO ولا من نقص الأكسجين."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"الغازات",description:"غاز أول أكسيد الكربون (CO)"}],quiz:[{question:"لماذا يُعدّ غاز CO خطرًا؟",options:[{text:"لأن رائحته كريهة",correct:!1},{text:"لأنه لا يُرى ولا يُشمّ",correct:!0},{text:"لأن لونه أحمر",correct:!1},{text:"لأنه لا يتكوّن إلا في الليل",correct:!1}],explanation:"لأنه لا يمكن الإحساس به، يتسمّم العمال دون أن يدركوا ذلك. ضع أجهزة كشف CO (CO Detector) في الأماكن التي تعمل فيها المحركات."},{question:"في أثناء العمل قرب مولّد يعمل، أصابك صداع ودوار وغثيان. ماذا تفعل؟",options:[{text:"أتناول مسكّنًا وأواصل العمل",correct:!1},{text:"أجلس قرب المولّد لأستريح",correct:!1},{text:"أرتدي قناع تنفس بمرشّح وأبقى في مكاني",correct:!1},{text:"أخرج فورًا إلى الهواء الطلق وأتصل بالرقم 122",correct:!0}],explanation:"الصداع والدوار والغثيان قد تكون أعراض التسمم بغاز CO؛ فاخرج فورًا إلى الهواء الطلق واتصل بالرقم 122، لأن CO لا يُرى ولا يُشمّ."},{question:"هل يحمي قناع التنفس ذو المرشّح العاملَ من غاز CO؟",options:[{text:"لا، لا يحمي من CO",correct:!0},{text:"نعم، أي قناع بمرشّح يوقف CO",correct:!1},{text:"نعم، إذا ارتُدي أقل من ساعة",correct:!1},{text:"فقط إذا تغيّر المرشّح كل يوم",correct:!1}],explanation:"تُختار أقنعة التنفس ذات المرشّحات وفق صحيفة SDS، لكنها لا تحمي من CO ولا من نقص الأكسجين؛ وفي الأماكن التي تعمل فيها المحركات تلزم التهوية وأجهزة كشف CO."}]},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"الإخلاء الطارئ (Evacuation)",subtitle:"Emergency Assembly Points",summary:"خطة الخروج في أثناء الحريق أو الكارثة",blocks:[{body:"معرفة طريق الخروج قد تصنع الفرق بين الحياة والموت."},{heading:"1. قواعد الإخلاء",body:"عندما يدقّ جرس الإنذار:",points:["امشِ بهدوء وبسرعة، ولا تركض، ولا تستخدم المصعد.","أغلق الأبواب خلفك كي لا تنتشر النار والدخان، لكن لا تقفلها بالمفتاح.","توجّه إلى نقطة التجمع (Assembly Point) ليُجرى عدّ الموظفين.","لا تعد إلى الداخل بأي حال من الأحوال حتى يسمح لك مسؤول السلامة أو فرق الدفاع المدني (115)."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"تمرين الإخلاء",description:"التدريب على الإخلاء"}],quiz:[{question:"عندما يدقّ جرس الإنذار، ماذا تفعل؟",options:[{text:"جمع أغراضي ثم الخروج",correct:!1},{text:"التوجّه بهدوء نحو المخرج",correct:!0},{text:"الاختباء تحت الطاولة حتى يتوقف الإنذار",correct:!1},{text:"الصراخ",correct:!1}],explanation:"الخروج بهدوء وبسرعة هو أفضل طريقة لحماية الأرواح."},{question:"ماذا تفعل بالأبواب في أثناء خروجك عند الإخلاء؟",options:[{text:"أقفلها كي لا يعود أحد إلى الداخل",correct:!1},{text:"أتركها مفتوحة تمامًا ليخرج الدخان",correct:!1},{text:"أغلقها خلفي، لكن لا أقفلها بالمفتاح",correct:!0},{text:"أُبقيها مفتوحة بشيء ما للفرق التي تصل لاحقًا",correct:!1}],explanation:"أغلق الأبواب خلفك كي لا تنتشر النار والدخان، لكن لا تقفلها بالمفتاح."},{question:"أنت في نقطة التجمع. متى يمكنك العودة إلى الداخل؟",options:[{text:"بمجرد أن يتوقف جرس الإنذار في المبنى",correct:!1},{text:"عندما يسمح مسؤول السلامة أو فرق الدفاع المدني (115)",correct:!0},{text:"عندما لا يخرج دخان من النوافذ",correct:!1},{text:"بعد 10 دقائق إذا لم تظهر أي نار",correct:!1}],explanation:"لا تعد إلى الداخل بأي حال من الأحوال حتى يسمح لك مسؤول السلامة أو فرق الدفاع المدني (115)؛ وفي نقطة التجمع يُجرى عدّ الموظفين أيضًا."}]},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"سلامة اللحام",subtitle:"Welding & Cutting Hazards",summary:"الحماية من إشعاع اللحام وحرارته ودخانه",blocks:[{body:"ينطوي اللحام على خطر الأشعة فوق البنفسجية (UV)، والحروق البالغة، والغازات والأدخنة السامة."},{heading:"1. حماية العينين والجلد",body:"متطلبات عمال اللحام:",points:["خوذة اللحام (Welding Helmet) بمرشّح مناسب: لحماية العينين من الأشعة فوق البنفسجية ومن الضوء الشديد لقوس اللحام (Arc).","قفازات جلدية طويلة: للحماية من الحرارة والشرر.","مريلة جلدية (Apron): لحماية الجسم."]},{heading:"2. خطر الحريق (Hot Work)",body:"قبل البدء احصل على تصريح العمل الساخن (Hot Work Permit)، ثم:",points:["أخلِ محيط مكان العمل من المواد القابلة للاشتعال (NFPA 51B: ضمن مسافة 11 مترًا / 35 قدمًا)، أو غطّها بستائر واقية.","جهّز مطفأة مناسبة بالقرب منك.","مراقب الحريق (Fire Watch): يبقى في المكان في أثناء العمل ولمدة ساعة واحدة على الأقل بعد انتهائه؛ ثم يُراقَب المكان مدة تصل إلى 3 ساعات إضافية، بحسب قرار المسؤول عن التصريح (NFPA 51B)."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"اللحام",description:"الارتداء الصحيح لمعدات الوقاية"}],quiz:[{question:"لماذا يبقى مراقب الحريق في المكان ساعة واحدة على الأقل بعد اللحام؟",options:[{text:"لتنظيف بقايا قطع الحديد",correct:!1},{text:"كي لا ينشأ حريق كامن",correct:!0},{text:"لانتظار أن يبرد الحديد الملحوم",correct:!1},{text:"لا حاجة إلى ذلك",correct:!1}],explanation:"كثيرًا ما يسقط الشرر في الشقوق وبين المواد، ويُحدث حريقًا بعد مدة. ووفقًا لـ NFPA 51B (إصدار 2019 وما بعده)، تستمر المراقبة ساعة واحدة على الأقل بعد العمل."},{question:"قبل بدء العمل الساخن (Hot Work)، ماذا يجب أن يُفعل بالمواد القابلة للاشتعال حول مكان العمل؟",options:[{text:"تُترك في مكانها، لأن مراقب الحريق سيكون موجودًا",correct:!1},{text:"تُزال أو تُغطّى بستائر واقية",correct:!0},{text:"تُرشّ بالماء مرة واحدة ثم يبدأ اللحام فورًا",correct:!1},{text:"تُنقل إلى خلف عامل اللحام بعيدًا عن الشرر المباشر",correct:!1}],explanation:"قبل البدء احصل على تصريح العمل الساخن (Hot Work Permit)، وأخلِ محيط مكان العمل من المواد القابلة للاشتعال (NFPA 51B: ضمن مسافة 11 مترًا / 35 قدمًا)، أو غطّها بستائر واقية."},{question:"ما الذي يحمي عيني عامل اللحام من الأشعة فوق البنفسجية والضوء الشديد لقوس اللحام؟",options:[{text:"نظارات السلامة العادية الشفافة، كالتي تُستخدم للغبار",correct:!1},{text:"نظارات شمسية داكنة تحت خوذة الحماية",correct:!1},{text:"خوذة اللحام بمرشّح مناسب",correct:!0},{text:"النظر إلى القوس بضع ثوانٍ فقط",correct:!1}],explanation:"تحمي خوذة اللحام (Welding Helmet) بمرشّح مناسب العينين من الأشعة فوق البنفسجية ومن الضوء الشديد لقوس اللحام؛ أما القفازات الجلدية الطويلة والمريلة الجلدية فتحمي اليدين والجسم."}]},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"معدات النقل",subtitle:"Forklift & Vehicle Safety",summary:"سلامة الرافعة الشوكية والقيادة داخل المصنع",blocks:[{body:"الرافعة الشوكية آلة ثقيلة، وتنطوي على خطر السحق والانقلاب إذا لم تُقَد بشكل صحيح."},{heading:"1. قواعد القيادة",body:"لسائقي الرافعات الشوكية:",points:["لا يقود الرافعة الشوكية إلا الأشخاص المدرَّبون والمرخَّصون (OSHA 1910.178).","لا تحمل أبدًا أي شخص على شوكتي الرافعة (Forks) أو بجانبك.","لا تحمّل الرافعة أكثر من سعتها كي لا تنقلب، واربط حزام الأمان.","خفّف السرعة عند كل زاوية أو باب، واستخدم البوق (Horn)."]},{heading:"2. سلامة المشاة",body:"إذا كنت تمشي بالقرب من رافعة شوكية:",points:["احرص على التواصل البصري مع السائق (Eye Contact) وحافظ على مسافة آمنة.","امشِ في الممرات المخصّصة للمشاة والمحدّدة بعلامات."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"الرافعة الشوكية",description:"التعرّف على النقاط العمياء (Blind Spots)"}],quiz:[{question:"إذا كان سائق الرافعة الشوكية يحمل حمولة عالية تحجب رؤيته للأمام، فماذا يفعل؟",options:[{text:"يقود بسرعة",correct:!1},{text:"يقود إلى الخلف (Reverse)",correct:!0},{text:"يستخدم البوق ويُغمض عينيه",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"عندما يحجب الحمل رؤية السائق، يجب أن يقود إلى الخلف ليرى طريقه (OSHA 1910.178)."},{question:"يطلب منك زميل أن يركب على شوكتي (Forks) رافعتك الشوكية. ماذا تفعل؟",options:[{text:"أسمح له بالركوب إذا قدتُ ببطء",correct:!1},{text:"أسمح له بالوقوف على الشوكتين والتمسك بالرافعة",correct:!1},{text:"أسمح له بالجلوس بجانبي بدلًا من الشوكتين",correct:!1},{text:"أرفض، فلا يجوز أن يركب أحد على الشوكتين",correct:!0}],explanation:"لا تحمل أبدًا أي شخص على شوكتي الرافعة أو بجانبك؛ فالرافعة الشوكية آلة ثقيلة، وتنطوي على خطر السحق والانقلاب."},{question:"تمشي بالقرب من رافعة شوكية تتحرك. ماذا يجب أن تفعل؟",options:[{text:"أتواصل بصريًا مع السائق وأحافظ على مسافة آمنة",correct:!0},{text:"أمشي قريبًا منها ليراني السائق بشكل أفضل",correct:!1},{text:"أعبر من أمامها بسرعة قبل أن تصل إليّ",correct:!1},{text:"ألوّح بيدي وأواصل السير، فعلى السائق أن يتوقف",correct:!1}],explanation:"بالقرب من الرافعة الشوكية، احرص على التواصل البصري مع السائق (Eye Contact)، وحافظ على مسافة آمنة، وامشِ في الممرات المخصّصة للمشاة؛ فقد لا يراك السائق في النقاط العمياء (Blind Spots)."}]},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"علامات السلامة",subtitle:"Safety Signs & Symbols",summary:"التعرّف على ألوان السلامة ورموزها (ISO 7010)",blocks:[{body:"تنبّهنا علامات السلامة إلى المخاطر بلغة عالمية."},{heading:"1. دلالة الألوان (ISO 7010)",body:"يحمل كل لون رسالة خاصة:",points:["الأحمر: المنع أو معدات مكافحة الحريق (مثال: التدخين ممنوع).","الأصفر: التحذير والخطر (مثال: خطر الكهرباء).","الأزرق: الإلزام (مثال: يجب ارتداء خوذة الحماية).","الأخضر: السلامة والإخلاء (مثال: باب الخروج)."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"علامات السلامة",description:"الرموز القياسية"}],quiz:[{question:"ما معنى العلامة ذات اللون الأصفر؟",options:[{text:"منع القيام بعمل ما",correct:!1},{text:"التحذير والخطر",correct:!0},{text:"مكان آمن وطريق للهروب",correct:!1},{text:"استخدام الماء",correct:!1}],explanation:"اللون الأصفر يعني دائمًا «انتبه» أو «يوجد خطر»."},{question:"علامة زرقاء عند باب الورشة تُظهر خوذة حماية. ماذا تعني؟",options:[{text:"خوذة الحماية ممنوعة هنا",correct:!1},{text:"تحذير: قد تسقط أجسام هنا",correct:!1},{text:"يجب ارتداء خوذة الحماية هنا",correct:!0},{text:"تُحفظ خوذ الحماية خلف هذا الباب",correct:!1}],explanation:"اللون الأزرق يعني الإلزام، مثل: يجب ارتداء خوذة الحماية؛ أما الأحمر فللمنع أو معدات مكافحة الحريق، والأصفر للتحذير، والأخضر للسلامة والإخلاء."},{question:"أي لون يُستخدم للسلامة والإخلاء، مثل باب الخروج؟",options:[{text:"الأحمر",correct:!1},{text:"الأصفر",correct:!1},{text:"الأزرق",correct:!1},{text:"الأخضر",correct:!0}],explanation:"يدلّ اللون الأخضر على السلامة والإخلاء، مثل باب الخروج؛ أما الأحمر فللمنع أو معدات مكافحة الحريق."}]},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"النظافة والترتيب (Housekeeping)",subtitle:"Order & Maintenance",summary:"تنظيم مكان العمل لتقليل المخاطر",blocks:[{body:"مكان العمل النظيف مكان آمن. وتقع حوادث كثيرة بسبب الانزلاق أو التعثّر بالأدوات والمواد المبعثرة."},{heading:"1. القواعد العامة",body:"لجميع العمال:",points:["تنظيف الزيت أو الماء المسكوب في أسرع وقت.","جمع النفايات في حاويات خاصة.","إبقاء الممرات والمخارج مفتوحة وخالية من العوائق.","إعادة كل أداة إلى مكانها بعد انتهاء العمل."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"النظافة والترتيب",description:"مثال على مكان عمل نظيف"}],quiz:[{question:"إذا رأيت زيتًا مسكوبًا على الأرض، فماذا تفعل؟",options:[{text:"أتركه كما هو حتى يأتي عامل النظافة في المناوبة التالية",correct:!1},{text:"أنظّفه أو أضع عليه علامة تحذير وأُبلغ عنه",correct:!0},{text:"أقفز فوقه",correct:!1},{text:"لا أهتم به",correct:!1}],explanation:"كل عامل مسؤول عن نظافة مكان عمله وسلامته، كي لا يسقط أحد."},{question:"كيف يجب أن تبقى الممرات والمخارج؟",options:[{text:"مفتوحة وخالية من العوائق",correct:!0},{text:"مكانًا لوضع الصناديق عند امتلاء المخزن",correct:!1},{text:"مغلقة لفترات قصيرة في أثناء العمل",correct:!1},{text:"خالية فقط قبل زيارة التفتيش",correct:!1}],explanation:"أبقِ الممرات والمخارج مفتوحة وخالية من العوائق؛ فحوادث كثيرة تقع بسبب الانزلاق أو التعثّر بالأدوات والمواد المبعثرة."},{question:"أنهيت عملك. ماذا تفعل بالأدوات التي استخدمتها؟",options:[{text:"أتركها على الأرض للنوبة التالية",correct:!1},{text:"أعيد كل أداة إلى مكانها",correct:!0},{text:"أضعها في حاوية النفايات مع البقايا",correct:!1},{text:"أجمعها في الممر قرب المخرج",correct:!1}],explanation:"أعِد كل أداة إلى مكانها بعد انتهاء العمل، واجمع النفايات في حاويات خاصة؛ فالأدوات والمواد المبعثرة تسبّب الانزلاق والتعثّر."}]},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"الزلزال في المصانع",subtitle:"Earthquake Safety in Factories",summary:"سلامة العمال في أثناء الزلزال وبعده",blocks:[{body:"يُشكّل الزلزال في المصانع خطرًا مضاعفًا: الاهتزاز نفسه من جهة، ومن جهة أخرى سقوط الآلات الثقيلة، وانسكاب المواد الكيميائية، وتكسّر الأنابيب، وتسرّب الغاز. لذا يجب أن تكون لكل مصنع خطة للزلازل."},{heading:"1. انخفض، احتمِ، تمسّك (Drop, Cover, Hold On)",body:"في أثناء الزلزال:",points:["انخفض إلى الأرض (Drop) وادخل تحت طاولة أو طاولة عمل (Workbench) متينة — بعيدًا عن الآلات الثقيلة والرفوف والزجاج.","إذا لم تكن هناك طاولة، فاجثُ على ركبتيك بجانب جدار داخلي وغطِّ رأسك ورقبتك بيديك (Cover).","تمسّك بالطاولة (Hold On) حتى يتوقف الاهتزاز تمامًا.","لا تركض، ولا تحتمِ تحت الآلات أو بجانب الرفوف! فالآلات الثقيلة والرفوف قد تتحرك أو تسقط عليك."]},{heading:"2. بعد الزلزال",body:"بعد توقف الاهتزاز:",points:["افحص الآلات بحثًا عن أضرار، ولا تشغّل الآلات المتضررة حتى تُفحص.","تحقّق مما إذا كانت المواد الكيميائية قد انسكبت، وابتعد عنها.","إذا شممت رائحة غاز — فاخرج بسرعة، وأخلِ المصنع، واتصل بالرقم 115 من الخارج.","لا يقطع الغازَ إلا الموظفون المدرَّبون والمكلَّفون، وفقط إذا شُمّت رائحته أو سُمع صوت تسرّب وأمكن الوصول إلى صمام الغاز بأمان، دون دخول المكان الذي تجمّع فيه الغاز ودون إحداث أيّ شرارة؛ واقطع الكهرباء إذا تضررت الأسلاك أو اللوحات الكهربائية.","قبل العودة إلى الداخل، يجب أن يفحص مهندسٌ مبنى المصنع بحثًا عن تشققات."]},{heading:"3. الاستعداد",body:"الخطة المسبقة:",points:["أعدّ خطة للزلازل لكل قسم.","ثبّت الآلات الثقيلة بالسلاسل أو البراغي.","ضع البراميل وعبوات المواد الكيميائية على رفوف منخفضة وثابتة.","أبقِ ممرات الإخلاء مفتوحة دائمًا.","أجرِ تمرينًا مرة كل 6 أشهر."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"الزلزال",description:"الزلزال في المصنع"}],quiz:[{question:"في أثناء الزلزال في المصنع، ما أول ما تفعله؟",options:[{text:"الركض فورًا إلى الخارج من أقرب باب",correct:!1},{text:"الانخفاض إلى الأرض والدخول تحت طاولة متينة",correct:!0},{text:"إطفاء جميع الآلات قبل أي شيء آخر",correct:!1},{text:"الاقتراب من النوافذ",correct:!1}],explanation:"انخفض، احتمِ، تمسّك (Drop, Cover, Hold On) — هذا هو الإجراء الأول داخل المباني، بعيدًا عن الآلات والرفوف والزجاج."},{question:"بعد الزلزال في مصنع للمواد الكيميائية، ما أول ما يجب فحصه؟",options:[{text:"عدّادات الكهرباء ولوحاتها",correct:!1},{text:"انسكاب المواد الكيميائية",correct:!0},{text:"أنابيب المياه",correct:!1},{text:"خطوط الهاتف",correct:!1}],explanation:"انسكاب المواد الكيميائية خطر كبير بعد الزلزال، ويجب فحصه بسرعة."},{question:"بعد توقف الاهتزاز، شممت رائحة غاز في المصنع. ماذا تفعل؟",options:[{text:"أذهب إلى صمام الغاز وأغلقه بنفسي",correct:!1},{text:"أشغّل مراوح الشفط ليخرج الغاز",correct:!1},{text:"أخرج بسرعة وأتصل بالرقم 115 من الخارج",correct:!0},{text:"أتصل بالرقم 115 من هاتفي أولًا ثم أخرج",correct:!1}],explanation:"إذا شممت رائحة غاز، فاخرج بسرعة، وأخلِ المصنع، واتصل بالرقم 115 من الخارج؛ ولا يقطع الغازَ إلا الموظفون المدرَّبون والمكلَّفون، وفقط إذا أمكن الوصول إلى الصمام بأمان، دون دخول المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة."}]},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"السيول والفيضانات",subtitle:"Flood Emergency in Industrial Areas",summary:"حماية المصانع والعمال في أثناء السيول",blocks:[{body:"يمكن للسيول أن تدمّر المصانع تدميرًا كاملًا: فهي تُتلف الآلات، وتنشر المواد الكيميائية، وتجعل الكهرباء مصدر خطر. والمصانع القريبة من الأنهار والوديان أكثر عرضة للخطر."},{heading:"1. قبل السيل",body:"الاستعداد:",points:["تابع تحذيرات الأرصاد الجوية (Meteorology).","انقل المعدات المهمة والمواد الكيميائية إلى مكان مرتفع.","جهّز نظام الكهرباء للفصل التلقائي (Auto-shutoff).","ضع أكياس الرمل (Sandbags) أمام الأبواب وعند أساسات المصنع."]},{heading:"2. في أثناء السيل",body:"الإجراءات العاجلة:",points:["إذا استطعت ذلك بأمان ولم تصل المياه إلى اللوحات الكهربائية، فاقطع الكهرباء والغاز؛ ولا تلمس الكهرباء وأنت في الماء!","لا تدخل مياه السيل — فـ 15 سم من الماء المتدفق بسرعة يمكن أن تُسقط الإنسان، و30 سم يمكن أن تجرف السيارة.","انتقل إلى مكان مرتفع — الطابق الثاني أو السطح.","اتصل بالرقم 115 وابقَ في مكانك حتى تصل فرق الإنقاذ."]},{heading:"3. بعد السيل",body:"العودة والتنظيف:",points:["لا تدخل المصنع حتى يتأكد مهندس من أن المبنى آمن.","لا تلمس المواد الكيميائية التي وصلت إليها المياه — اطلب فريق المواد الخطرة (HazMat) عبر الرقم 115.","لا تُعِد تشغيل الكهرباء حتى يفحص كهربائي مختص النظام.","التقط صورًا لجميع الأضرار من أجل التأمين والتقرير."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"السيول",description:"السيول في المصنع"}],quiz:[{question:"في أثناء السيل في المصنع، ما أول ما تفعله؟",options:[{text:"احمِ الآلات بتغطيتها بأغطية بلاستيكية كبيرة",correct:!1},{text:"اقطع الكهرباء والغاز إذا استطعت ذلك بأمان",correct:!0},{text:"اذهب إلى البيت",correct:!1},{text:"ابدأ بسحب الماء بالمضخة قبل أي شيء آخر",correct:!1}],explanation:"الكهرباء والغاز هما الخطران الأولان في أثناء السيل؛ لكن إذا وصلت المياه إلى اللوحات الكهربائية، فلا تقترب منها وانتقل إلى مكان مرتفع."},{question:"كم يكفي من الماء المتدفق بسرعة لإسقاط الإنسان؟",options:[{text:"50 سم",correct:!1},{text:"75 سم",correct:!1},{text:"15 سم",correct:!0},{text:"متر واحد",correct:!1}],explanation:"لا تدخل مياه السيل: فـ 15 سم من الماء المتدفق بسرعة يمكن أن تُسقط الإنسان، و30 سم يمكن أن تجرف السيارة. انتقل إلى مكان مرتفع واتصل بالرقم 115."},{question:"بعد السيل، وجدت براميل مواد كيميائية وصلت إليها المياه. ماذا تفعل؟",options:[{text:"أغسلها بماء نظيف وأعيدها إلى الرف",correct:!1},{text:"لا ألمسها، وأطلب فريق المواد الخطرة (HazMat) عبر الرقم 115",correct:!0},{text:"أنقلها بيدي إلى الخارج قبل أن ترتفع المياه مجددًا",correct:!1},{text:"أفتحها لأتحقق مما إذا دخلها الماء",correct:!1}],explanation:"لا تلمس المواد الكيميائية التي وصلت إليها المياه — اطلب فريق المواد الخطرة (HazMat) عبر الرقم 115."}]},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"استجابة الدفاع المدني في المصانع",subtitle:"Industrial CD Response & Multi-Agency Coordination",summary:"تشكيل فريق الاستجابة في المصنع عند وقوع الحوادث، والتنسيق مع الدفاع المدني (115)",blocks:[{body:"يجب أن تمتلك المصانع الكبيرة (النفط، والغاز، والكيمياويات، والصلب) فرقًا خاصة بها للاستجابة للطوارئ تعمل قبل وصول فرق الدفاع المدني (115). ويحدّد معيار NFPA 600 (Facility Fire Brigades) تنظيم فرق الإطفاء في المنشآت الصناعية وتدريبها ومعداتها. والدقائق الأولى من الحادث بالغة الأهمية، لذا يجب أن يكون فريق المصنع جاهزًا ومدرَّبًا."},{heading:"1. تشكيل فريق الاستجابة للطوارئ في المصنع (ERT)",body:"المبادئ الأساسية لفريق الاستجابة للطوارئ (Emergency Response Team):",points:["حجم الفريق: يُحدَّد بناءً على تقييم مخاطر المصنع ومهام الفريق؛ ولا يحدّد NFPA 600 نسبة ثابتة لعدد الأعضاء قياسًا بعدد الموظفين.","التدريب: بحسب مهام كل عضو، مع تدريب تنشيطي (Refresher) مرة واحدة في السنة على الأقل.","قائد الحادث (Incident Commander — IC): شخص واحد فقط يُصدر الأوامر، كي لا تتضارب الأوامر.","المهام الرئيسية: إطفاء الحريق، والإنقاذ، والإسعافات الأولية، وإخلاء المبنى.","الاتصال: أجهزة لاسلكي (Radio) على قناة مخصّصة، والهاتف المحمول وسيلةً احتياطية.","زمن الاستجابة: حدّده في الخطة، وقِسه بالتمارين، وحسّنه.","توصية: دورتا ICS-100 وICS-200 (FEMA) لتعلّم نظام قيادة الحوادث."]},{heading:"2. خطة الاستجابة للطوارئ (ERP)",body:"خطة الاستجابة للطوارئ (Emergency Response Plan) وفق المعايير:",points:["يجب أن تكون خطة الطوارئ مكتوبة ومتاحة في المصنع؛ ويجوز للمنشآت التي يعمل فيها 10 موظفين أو أقل إبلاغها شفهيًا (OSHA 29 CFR 1910.38).","الأقسام الرئيسية: المهام، والإجراءات، وطرق الإخلاء، والاتصالات، والموارد، والتمارين، والتقييم بعد الحادث.","نقاط التجمع (Assembly Points): نقطة رئيسية وأخرى احتياطية، في مكان آمن بعيد عن المبنى وعن طريق مركبات الطوارئ.","طرق الإخلاء: طريقان على الأقل من كل طابق بوجه عام (NFPA 101، مع بعض الاستثناءات).","إنذار الحريق (Alarm): يجب أن يُسمع أو يُرى في جميع أنحاء المبنى (NFPA 72).","فريق الإسعافات الأولية: يجب أن يوجد في كل وردية (Shift) موظفون تلقّوا تدريبًا على الإسعافات الأولية والإنعاش القلبي الرئوي (CPR).","التمارين (Drill): تُجرى بانتظام، وتُسجَّل نتائج كل تمرين.","التقييم بعد الحادث (Post-Response Critique): في أقرب وقت ممكن بعد كل حادث."]},{heading:"3. التنسيق مع الدفاع المدني (115)",body:"عند وقوع الحادث ووصول فرق الدفاع المدني (115)، يجب على فريق ERT اتباع الخطوات الآتية:",points:["1. اتصل فورًا بالرقم 115، وبالرقم 122 إذا كان هناك مصابون.","2. قدّم المعلومات الأساسية: الموقع، ونوع الحادث، وعدد المصابين، والمواد الخطرة، وطريق الوصول.","3. جهّز خريطة المصنع (Site Map) عند البوابة، مع مواقع الخطر وأماكن قطع الكهرباء والغاز.","4. ضابط الاتصال (Liaison Officer): شخص واحد فقط يتواصل مع الدفاع المدني (115).","5. جهّز صحائف بيانات السلامة (SDS) لجميع المواد الكيميائية.","6. سجّل أسماء الشهود وإفاداتهم.","7. نقل القيادة: عند وصول الدفاع المدني (115)، تنتقل القيادة إلى قائد فرق الدفاع المدني ويتولّى فريق ERT المساندة.","8. التوثيق: الصور والفيديو وسجلّ الحادث (Incident Log) لأغراض التحقيق والتأمين."]},{heading:"4. العمل مع فريق المواد الخطرة (HazMat)",body:"في الحوادث الكيميائية، يلزم فريق HazMat:",points:["مستويات التدريب على المواد الخطرة (OSHA 1910.120 وNFPA 470، الذي دُمج فيه NFPA 472):","• مستوى التوعية (Awareness): التعرّف على الخطر، والابتعاد، والإبلاغ — لجميع الموظفين.","• مستوى العمليات (Operations): حماية الناس والمحيط بأساليب دفاعية (Defensive) من مسافة بعيدة.","• مستوى الفني (Technician): إيقاف التسرّب من مسافة قريبة (Offensive) بمعدات وقاية شخصية خاصة.","• مستوى الأخصائي (Specialist): معرفة متعمّقة بمواد محدّدة ودعم الفنيين.","ثلاث مناطق: المنطقة الساخنة (Hot Zone)، والمنطقة الدافئة (Warm Zone)، والمنطقة الباردة (Cold Zone).","مستويات معدات الوقاية الشخصية في HazMat: A، B، C، D (المستوى A أعلى درجات الحماية).","تُجرى إزالة التلوث (Decontamination) في المنطقة الدافئة، قبل الانتقال إلى المنطقة الباردة.","لا يدخل الموظفون غير المدرَّبين المنطقة الساخنة؛ بل ينتظرون فرق الدفاع المدني (115).","يجب أن تحدّد خطة المصنع كيفية طلب الفرق المتخصّصة بالمواد الخطرة عبر الرقم 115."]},{heading:"5. الاستجابة المشتركة لعدة جهات (Multi-Agency Response)",body:"تتطلب الحوادث الكبيرة مشاركة عدة جهات:",points:["115 الدفاع المدني: إطفاء الحريق، والإنقاذ، والمواد الخطرة.","122 الإسعاف: العلاج الطبي ونقل المصابين.","104 الشرطة: تطويق المنطقة، وتنظيم المرور، والتحقيق القانوني.","الأجهزة الأمنية: عند الاشتباه بوجود متفجرات أو عمل إرهابي — ويجري إبلاغها عبر الرقم 104.","وزارة الصحة: تجهيز المستشفيات القريبة.","مديرية الكهرباء: قطع الكهرباء عن المنطقة المحيطة.","دوائر الماء والغاز: قطع خطوط الماء والغاز.","هيئة البيئة: إذا انتشرت المواد الكيميائية في البيئة.","مركز عمليات الطوارئ (EOC): للحوادث الكبيرة التي تشارك فيها جهات عديدة."]},{heading:"6. مراحل الاستجابة (5 مراحل)",body:"يمرّ كل حادث بالمراحل الخمس الآتية:",points:["1. الاكتشاف (Detection): الحساسات، أو إنذار الحريق، أو الشهود.","2. الإبلاغ (Notification): الاتصال بالرقم 115، وإبلاغ فريق ERT وضابط الاتصال.","3. الاستجابة (Response): يعمل فريق ERT حتى تصل فرق الدفاع المدني (115).","4. تخفيف الخطر (Mitigation): إطفاء الحريق، والإنقاذ، وإزالة التلوث.","5. التعافي (Recovery): التنظيف، والتحليل، والتقييم بعد الحادث.","يجب توثيق كل مرحلة (خطة عمل الحادث Incident Action Plan — IAP).","الساعة الذهبية (Golden Hour): العلاج السريع بعد الإصابة البالغة يزيد فرص النجاة — لذا فإن الاتصال السريع بالرقم 122 أمر مهم."]},{heading:"7. التمارين والتدريب (Drills & Training)",body:"التمارين أساس الاستعداد (الجدول المقترح):",points:["تمرين المحاكاة المكتبية (Tabletop Exercise): مرة كل 3 أشهر — سيناريو يُناقش حول الطاولة.","التمرين الوظيفي (Functional Drill): مرة كل 6 أشهر — لفريق ERT فقط، لا للمبنى كله.","التمرين الشامل (Full-Scale Drill): مرة في السنة — للمصنع كله بالاشتراك مع الدفاع المدني (115).","التقييم: تقرير ما بعد التمرين (After-Action Report) في أقرب وقت ممكن.","تدريب فريق ERT: بصورة مستمرة وبحسب المهام، ومرة واحدة في السنة على الأقل.","معايير الكفاءة: NFPA 1081 (Facility Fire Brigade Member)، وOSHA 1910 Subpart L، وICS-100/200.","تمرين مشترك مع الدفاع المدني (115): مرة في السنة لأغراض التنسيق."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"تمرين الاستجابة لفريق ERT",description:"تمرين شامل في مصنع نفط"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"هيكل نظام قيادة الحوادث (ICS)",description:"هيكل نظام قيادة الحوادث (ICS)"}],quiz:[{question:"كيف يُحدَّد حجم فريق الاستجابة للطوارئ (ERT) في المصنع؟",options:[{text:"بنسبة ثابتة: عضو (1) مدرَّب لكل 100 موظف في كل مناوبة",correct:!1},{text:"بناءً على تقييم مخاطر المصنع ومهام الفريق",correct:!0},{text:"بنسبة ثابتة: 1 لكل 200 موظف",correct:!1},{text:"بنسبة ثابتة: 1 لكل 25 موظفًا",correct:!1}],explanation:"لا يحدّد NFPA 600 نسبة ثابتة لعدد الأعضاء قياسًا بعدد الموظفين؛ بل يحدّد كل مصنع حجم فريقه بحسب مخاطره ومهامه."},{question:"ما معنى الساعة الذهبية (Golden Hour)؟",options:[{text:"الساعة الأولى من كل مناوبة عمل، حين يجب إجراء جميع فحوص السلامة",correct:!1},{text:"الوقت الأول بعد الإصابة البالغة، الذي يكون فيه العلاج السريع بالغ الأهمية",correct:!0},{text:"وقت الظهيرة",correct:!1},{text:"حرارة النهار",correct:!1}],explanation:"الساعة الذهبية (Golden Hour) هي الفترة التي تلي الإصابة البالغة، والتي يزيد فيها الإيصال السريع للمصاب إلى العلاج من فرص نجاته؛ لذا اتصل فورًا بالرقم 122."},{question:"في نظام ICS، ما عمل ضابط الاتصال (Liaison Officer)؟",options:[{text:"يُطفئ الحريق",correct:!1},{text:"يتواصل مع الجهات الخارجية",correct:!0},{text:"يُجري CPR",correct:!1},{text:"يحرس البوابة ويراقب الدخول",correct:!1}],explanation:"يتواصل ضابط الاتصال مع الدفاع المدني (115)، والشرطة (104)، والإسعاف (122)، والجهات الأخرى."},{question:"ما عمل مستوى العمليات (Operations) في HazMat؟",options:[{text:"الإبلاغ فقط",correct:!1},{text:"دفاعي (Defensive) — منع الانتشار من مسافة بعيدة",correct:!0},{text:"هجومي (Offensive) — دخول المنطقة الساخنة لإيقاف التسرّب من مسافة قريبة",correct:!1},{text:"التخصّص (Specialist)",correct:!1}],explanation:"مستوى العمليات (Operations) دفاعي (Defensive): منع انتشار المادة من مسافة بعيدة، وليس العمل عن قرب (Offensive)."},{question:"ما المنطقة الساخنة (Hot Zone) في HazMat؟",options:[{text:"مكان بارد وآمن يبقى فيه مركز القيادة وفرق الدعم",correct:!1},{text:"المنطقة التي يُزال فيها التلوث عن الأشخاص والمعدات قبل خروجهم منها",correct:!1},{text:"المنطقة الأشد خطرًا — لا يدخلها إلا فنيو HazMat بمعدات الوقاية الشخصية المناسبة",correct:!0},{text:"منطقة التجمع",correct:!1}],explanation:"المنطقة الساخنة هي موقع المادة الخطرة؛ ولا يدخلها إلا فنيو HazMat بمعدات وقاية شخصية من المستوى A أو B."},{question:"عندما تصل فرق الدفاع المدني (115) إلى موقع الحادث، إلى من تنتقل القيادة؟",options:[{text:"يستمر فريق ERT في القيادة",correct:!1},{text:"قائد فرق الدفاع المدني (115)",correct:!0},{text:"مدير المصنع",correct:!1},{text:"الشرطة",correct:!1}],explanation:"نقل القيادة (ICS Transfer): عند وصول الدفاع المدني (115)، تنتقل القيادة إلى قائد فرق الدفاع المدني ويتولّى فريق ERT المساندة."}]},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"تصنيف الحرائق في المصانع",subtitle:"Industrial Fire Classes — NFPA 30/484/654",summary:"تصنيف خاص بالمصانع: السوائل، والغازات، والمعادن، والغبار القابل للاشتعال",blocks:[{body:"تستخدم هذه الوحدة نظام NFPA: A المواد الصلبة، B السوائل والغازات القابلة للاشتعال، C المعدات الكهربائية، D المعادن، K زيت الطهي. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. والمعايير الخاصة بالمصانع هي: السوائل القابلة للاشتعال (NFPA 30)، والمعادن القابلة للاشتعال (NFPA 484)، والغبار القابل للاشتعال (NFPA 654). ومنذ إصدار 2025، دُمج NFPA 484 وNFPA 654 في المعيار NFPA 660."},{heading:"1. الفئة A — المواد الصلبة القابلة للاشتعال في المصنع",body:"المواد الصلبة الشائعة في المصانع:",points:["الوقود: الورق، والكرتون، والقماش، والخشب، والمطاط، والبلاستيك، والمنصّات النقالة (Pallets).","تخلّف هذه المواد جمرًا ونارًا كامنة؛ لذا برّد المكان بالماء بعد الإطفاء وراقبه.","في المصانع: تنشر مخازن الورق والكرتون والمنصّات الخشبية النار بسرعة.","المطفأة: الماء، الرغوة، مسحوق ABC.","المنصّات الفارغة المكدّسة خطر كبير: لا تكدّسها عاليًا، وخزّنها في الخارج أو في مكان مزوّد بالمرشّات (Sprinklers).","المعيار: NFPA 13 (أنظمة المرشّات)، الذي يشمل حماية المخازن أيضًا.","أمثلة في المصانع: المخازن وخطوط التعبئة والتغليف (Packaging Lines)."]},{heading:"2. الفئة B — السوائل القابلة للاشتعال في المصنع",body:"إحدى أخطر الفئات في المصانع:",points:["الوقود: البنزين، والنفط الأبيض (الكيروسين)، والديزل، والأسيتون (Acetone)، والتولوين (Toluene)، والزايلين (Xylene).","نقطة الوميض (Flash Point): البنزين نحو -43°C، والأسيتون -20°C، والديزل 52°C أو أكثر.","حدود الانفجار (LEL/UEL): أدنى تركيز وأعلى تركيز للبخار في الهواء يمكن أن يشتعل:","• البنزين: 1.4-7.6%.","• الأسيتون: 2.5-12.8%.","• الميثانول (Methanol): 6-36%.","المطفأة: الرغوة (AFFF أو الرغوة الخالية من الفلور)، CO₂، مسحوق ABC. وللأسيتون والميثانول والكحولات والمذيبات القطبية الأخرى: CO₂ أو المسحوق الجاف أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها.","لا ترشّ نفثة ماء مباشرة على السائل — فهي تنشر النار. ويحدث BLEVE (Boiling Liquid Expanding Vapor Explosion) عندما يسخن خزان مضغوط بفعل النار.","فئات السوائل وفق NFPA 30 (Flash Point = نقطة الوميض، Boiling Point = نقطة الغليان):","• الفئة I (سوائل قابلة للاشتعال – Flammable): نقطة الوميض أقل من 37.8°C — IA (الوميض < 22.8°C والغليان < 37.8°C)، IB (الوميض < 22.8°C والغليان 37.8°C أو أكثر)، IC (الوميض من 22.8 إلى < 37.8°C).","• الفئة II (سوائل قابلة للاحتراق – Combustible): نقطة الوميض من 37.8 إلى < 60°C.","• الفئة III (سوائل قابلة للاحتراق – Combustible): IIIA من 60 إلى < 93°C، وIIIB 93°C أو أكثر.","جدران الاحتواء (Diking): وفق NFPA 30، يجب ألّا تقل سعة منطقة الاحتواء عن كمية السائل التي يمكن أن تنسكب من أكبر خزان ممتلئ (100%)؛ أما نسبة 110% فتشترطها بعض القوانين والإرشادات الأخرى (لاستيعاب مياه الأمطار أيضًا).","كثافة البخار (Vapor Density): بخار البنزين أثقل من الهواء (نحو 3-4 مرات) ويتجمّع في الأماكن المنخفضة."]},{heading:"3. الغازات القابلة للاشتعال — NFPA: الفئة B، EN 2: الفئة C",body:"غازات المصانع: الأسيتيلين، والبروبان، والهيدروجين:",points:["المصادر: الأسيتيلين (Acetylene) للحام، والبروبان (Propane) لبعض الرافعات الشوكية، والهيدروجين (Hydrogen) الناتج عن شحن بطاريات الرصاص الحمضية (Lead-acid).","هذه المواد غازية في درجات الحرارة العادية وتشتعل بسهولة. حدود الانفجار في الهواء: الهيدروجين 4-75%، والبروبان 2.1-9.5%، والأسيتيلين من 2.5% فأكثر. (-253°C هي نقطة غليان الهيدروجين، وليست نقطة وميضه.)","تتجاوز حرارة لهب الأكسي-أسيتيلين (Oxy-Acetylene) 3000°C.","يُكوّن الأسيتيلين مع النحاس (Copper) مادة متفجرة (Copper Acetylide)؛ لا تستخدم أنابيب ومعدات نحاسية غير مناسبة.","الإطفاء: أولًا، أغلق صمام الغاز إذا كان ذلك آمنًا. ولا تُطفئ نار الغاز إذا لم تستطع إيقاف تدفقه — فالغاز المتسرّب قد يُحدث انفجارًا.","تستخدم فرق الدفاع المدني (115) رذاذ الماء (Water Spray) من بعيد لتبريد الأسطوانات والخزانات، لا لإطفاء لهب الغاز.","أجهزة كشف الغاز (Gas Detectors) في مخازن الغاز: يجب أن يعمل الإنذار قبل بلوغ LEL بفارق كبير (عادةً عند 10-20% من LEL).","في المصانع: أماكن اللحام، وأماكن شحن الرافعات الشوكية، وغرف البطاريات."]},{heading:"4. الفئة D — المعادن القابلة للاشتعال (NFPA 484)",body:"المعادن القابلة للاشتعال — من أخطر الأنواع:",points:["الوقود: المغنيسيوم، والتيتانيوم، ومسحوق الألمنيوم، والصوديوم، والليثيوم المعدني (Lithium Metal).","تحترق هذه المعادن بحرارة عالية جدًا وتُصدر ضوءًا شديدًا جدًا؛ لا تنظر مباشرة إلى اللهب.","الماء ممنوع! Mg + H₂O → MgO + H₂ (يتكوّن الهيدروجين وقد ينفجر).","CO₂ ممنوع! 2Mg + CO₂ → 2MgO + C (المغنيسيوم يحترق حتى في CO₂).","مطافئ الفئة D فقط، وفقط التي يذكر ملصقها هذا المعدن: فالمادة تختلف من معدن لآخر (مثل مسحوق قائم على كلوريد الصوديوم (NaCl) أو الغرافيت؛ ومسحوق النحاس لليثيوم). ولا تستخدم الماء أو المسحوق العادي أو الرغوة أبدًا. ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة SDS للمعدن وكان جافًا تمامًا.","أمثلة في المصانع: صهر الألمنيوم، وخراطة المغنيسيوم، وبطاريات الليثيوم المعدني.","NFPA 484: تخزين المعادن القابلة للاشتعال ومناولتها وحمايتها (أصبح الآن جزءًا من NFPA 660).","مسحوق الألمنيوم: ينطوي أيضًا على خطر انفجار الغبار (NFPA 654 / 660).","الاستجابة: اتصل فورًا بالرقم 115 ولا تستخدم إلا مطفأة الفئة D التي يذكر ملصقها هذا المعدن. أما بطاريات الليثيوم أيون (Li-ion) فلا تحتوي على ليثيوم معدني، وتُبرَّد بالماء."]},{heading:"5. الغبار القابل للاشتعال — انفجار الغبار (NFPA 654)",body:"خطر قاتل في المصانع:",points:["خماسي الغبار (Dust Pentagon): الوقود (الغبار) + الأكسجين + الحرارة + الانتشار في الهواء + الحيّز المغلق.","المصادر: الطحين، والسكر، والخشب، والفحم، وغبار المعادن، والبلاستيك.","تختلف أدنى درجة حرارة للاشتعال (MIT) باختلاف نوع الغبار؛ راجع صحيفة SDS أو نتائج اختبار الغبار.","ويختلف كذلك أدنى تركيز للانفجار (MEC) باختلاف نوع الغبار؛ والغبار المنتشر في الهواء خطِر دائمًا.","الانفجار الأولي (Primary): داخل جهاز ما (مثل المرشّح أو المطحنة).","الانفجار الثانوي (Secondary): يُثير الانفجار الأولي الغبار المتراكم على الأرض والرفوف والأنابيب، فيحدث انفجار أكبر وأشد فتكًا.","تقليل الخطر: أنظمة تجميع الغبار، وفتحات تنفيس الانفجار (Explosion Vents)، وأنظمة الإخماد.","النظافة: قد تُشكّل طبقة من الغبار بسماكة 0.8 مم (1/32 inch) على أكثر من 5% من مساحة الأرضية خطرًا (NFPA 654 / OSHA).","مثال: في عام 2008، في مصنع السكر Imperial Sugar (الولايات المتحدة)، أودى انفجار غبار السكر بحياة 14 عاملًا (CSB).","المعايير: NFPA 654 (الآن NFPA 660) وOSHA 29 CFR 1910.272 (لمخازن الحبوب)."]},{heading:"6. مراحل تطوّر الحريق في المصنع",body:"4 مراحل قياسية — وقد تكون النار في المصانع أسرع:",points:["البداية (Incipient): نار صغيرة — يمكن لشخص مدرَّب إطفاؤها بالمطفأة اليدوية المناسبة بعد إطلاق الإنذار والاتصال بالرقم 115، وطريق الخروج خلفه؛ وإذا لم تنطفئ فورًا، فاخرج.","النمو (Growth): تزداد النار والدخان بسرعة وتعمل المرشّات — اخرج واتصل بالرقم 115.","الاشتعال الكامل (Fully Developed): بعد الاشتعال الوميضي (Flashover) — لفرق الدفاع المدني (115) فقط.","الخمود (Decay): يقلّ الوقود، لكن خطر الارتداد اللهبي (Backdraft) والانهيار يبقى قائمًا.","في المصانع، يمكن للمخازن المرتفعة والمنصّات النقالة والسوائل أن توصل النار إلى مرحلة الاشتعال الكامل أسرع مما يحدث في المنازل.","خزانات الغاز والسوائل المضغوطة إذا سخنت بفعل النار قد تنفجر بظاهرة BLEVE — أخلِ المنطقة المحيطة بسرعة.","يجب أن تُبقي خطة المصنع طريق وصول فرق الدفاع المدني (115) ومآخذ مياه الإطفاء (Hydrants) جاهزة ومفتوحة.","مراقب الحريق بعد العمل الساخن (Hot Work): في أثناء العمل ولمدة ساعة واحدة على الأقل بعد انتهائه، ثم المراقبة مدة تصل إلى 3 ساعات إضافية بحسب قرار المسؤول عن التصريح (NFPA 51B)."]},{heading:"7. الحمل الحريقي (Fire Load) وتقييم المخاطر",body:"فحص المخاطر في المصنع:",points:["كثافة الحمل الحريقي (Fire Load Density — MJ/m²): كمية الطاقة التي يمكن أن تطلقها المواد القابلة للاشتعال في كل متر مربع. المتوسطات وفق EN 1991-1-2 (Eurocode 1):","• المساكن (Dwelling): نحو 780 MJ/m².","• المكاتب (Office): نحو 420 MJ/m².","• المكتبات (Library): نحو 1500 MJ/m².","• المخازن والمصانع: يُحسب بحسب المواد المخزّنة، وكثيرًا ما يكون أعلى من هذه القيم.","تقييم المخاطر (Risk Assessment): الخطر = احتمال الحدوث (Likelihood) × شدّة العواقب (Severity).","• منخفض (Low): يُسيطر عليه بالإجراءات المعتادة.","• متوسط (Medium): يحتاج إلى ضوابط إضافية ومراقبة.","• مرتفع (High): يتطلب إجراءً عاجلًا قبل مواصلة العمل.","• مرتفع جدًا (Extreme): يتوقف العمل حتى ينخفض الخطر.","تُحدَّد مقاومة الجدران والأسقف للحريق (Fire Resistance Rating) بحسب نوع المبنى واستخدامه وفق أكواد البناء (مثل NFPA 101 وNFPA 5000).","حدّث تقييم مخاطر المصنع (مثل HVA) مرة واحدة في السنة على الأقل، وبعد كل تغيير كبير."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"انفجار الغبار",description:"عرض توضيحي لانفجار الغبار"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"جدول فئات الحريق",description:"تصنيف الحرائق في المصانع"}],quiz:[{question:"لحريق من الفئة D، أيّ مطفأة تكون مناسبة؟",options:[{text:"أقرب مطفأة مسحوق جاف من نوع ABC",correct:!1},{text:"الماء",correct:!1},{text:"مطفأة الفئة D التي يذكر ملصقها هذا المعدن",correct:!0},{text:"مطفأة ثاني أكسيد الكربون CO₂ موجّهة إلى قاعدة النار",correct:!1}],explanation:"لا تصلح إلا مطفأة من الفئة D أو مادة يذكر ملصقها المعدن المشتعل؛ فالمادة تختلف من معدن لآخر. لا تستخدم الماء أو CO₂ أو مسحوق ABC."},{question:"ما معنى BLEVE؟",options:[{text:"معدات طوارئ لتنفيس بخار السائل المشتعل (Burning Liquid Emergency Venting Equipment)",correct:!1},{text:"انفجار البخار المتمدّد للسائل المغلي (Boiling Liquid Expanding Vapor Explosion)",correct:!0},{text:"نظام المرشّات",correct:!1},{text:"فئة الغاز",correct:!1}],explanation:"BLEVE هو انفجار خزان سائل مضغوط عندما يسخن بفعل النار فيتمدّد البخار بسرعة."},{question:"كم عنصرًا في خماسي الغبار (Dust Pentagon)؟",options:[{text:"3",correct:!1},{text:"4",correct:!1},{text:"5",correct:!0},{text:"6",correct:!1}],explanation:"خمسة عناصر: الوقود + الأكسجين + الحرارة + الانتشار + الحيّز المغلق."},{question:"ماذا يُكوّن الأسيتيلين مع النحاس (Copper)؟",options:[{text:"لا يحدث شيء — النحاس آمن تمامًا مع الأسيتيلين",correct:!1},{text:"أسيتيليد النحاس (Copper Acetylide) — مادة متفجرة",correct:!0},{text:"التنظيف",correct:!1},{text:"طبقة خضراء واقية تتكوّن على أنبوب النحاس",correct:!1}],explanation:"يُكوّن الأسيتيلين مع النحاس مادة متفجرة حساسة (Copper Acetylide) تنفجر بالصدم أو بالحرارة."},{question:"ما الخطر الذي ينطوي عليه مسحوق الألمنيوم (Aluminum Powder)؟",options:[{text:"الفئة A، مثل الخشب والورق",correct:!1},{text:"الفئة D وانفجار الغبار",correct:!0},{text:"الغاز فقط",correct:!1},{text:"لا خطر فيه",correct:!1}],explanation:"مسحوق الألمنيوم معدن قابل للاشتعال (الفئة D) وغبار قابل للاشتعال في آن واحد (NFPA 484 / 654، الآن NFPA 660)."},{question:"وفقًا لـ EN 1991-1-2، كم يبلغ متوسط الحمل الحريقي في المساكن (Dwelling) تقريبًا؟",options:[{text:"100 MJ/m²",correct:!1},{text:"230 MJ/m²",correct:!1},{text:"420 MJ/m²",correct:!1},{text:"780 MJ/m²",correct:!0}],explanation:"يبلغ متوسط الحمل الحريقي في المساكن نحو 780 MJ/m²، وفي المكاتب نحو 420 MJ/m² (EN 1991-1-2، الجدول E.4)."}]},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"أنظمة إطفاء الحريق في المصانع",subtitle:"Portable Extinguishers + Fixed Systems (Sprinkler/Foam/CO₂)",summary:"المطافئ اليدوية وأنظمة إطفاء الحريق الثابتة في المصانع",blocks:[{body:"تحتاج المصانع إلى مستويين من إطفاء الحريق: 1) المطافئ اليدوية (Portable Extinguishers) للحرائق الصغيرة في مرحلتها الأولى، 2) أنظمة الإطفاء الثابتة (Fixed Suppression Systems) للحماية المستمرة. وبحسب نوع الخطر: المرشّات (NFPA 13)، والرغوة (NFPA 11 / 16)، وCO₂ (NFPA 12)، والمسحوق الجاف (NFPA 17)، والعامل النظيف (Clean Agent — NFPA 2001). وتشرح هذه الوحدة هذه الأنظمة وجدول الفحص."},{heading:"1. المطافئ اليدوية — الاختيار في المصنع",body:"7 أنواع رئيسية وجدول الاختيار:",points:["مسحوق ABC (Multi-purpose): النوع الأكثر انتشارًا للممرات والأماكن العامة — A، B، C (وليس D وK).","CO₂: للوحات الكهربائية وغرف الخوادم — B، C.","الرغوة (AFFF / Foam): لمخازن السوائل ومناطق جدران الاحتواء — A، B.","المادة الكيميائية الرطبة (Wet Chemical): لمطبخ المصنع ومقصفه — K.","العامل النظيف (Clean Agent): لغرف الخوادم وغرف التحكم.","الفئة D (مادة يذكر ملصقها المعدن المستخدم في المكان): لخراطة المعادن وصهر الألمنيوم.","الرذاذ المائي Water Mist (قطيرات دقيقة من ماء منزوع المعادن): للفئة A، وبعض الطرازات للفئة C — بحسب اعتماد الجهاز (Listing).","مستويات الخطر وفق NFPA 10 (الحد الأدنى لتصنيف مطفأة الفئة A):","• خطر منخفض (Light Hazard — المكاتب): 2-A.","• خطر عادي (Ordinary Hazard — المصنع العادي): 2-A.","• خطر مرتفع (Extra Hazard — مصنع فيه كميات كبيرة من المواد القابلة للاشتعال): 4-A.","مسافة الوصول (Travel Distance) إلى المطفأة:","• الفئة A: حتى 23 مترًا (75 قدمًا) في جميع المستويات.","• الفئة B: 9 أو 15 مترًا (30 / 50 قدمًا) بحسب تصنيف المطفأة ومستوى الخطر."]},{heading:"2. أنظمة المرشّات — NFPA 13",body:"أهم نظام ثابت في كثير من المصانع:",points:["4 أنواع من أنظمة المرشّات:","• الأنابيب الرطبة (Wet Pipe): الأنابيب مملوءة بالماء دائمًا — أسرع استجابة والنوع الأكثر انتشارًا.","• الأنابيب الجافة (Dry Pipe): الأنابيب مملوءة بالهواء أو النيتروجين المضغوط — للأماكن التي تنخفض فيها الحرارة إلى ما دون 4°C.","• التفعيل المسبق (Pre-action): لا يُفتح الصمام إلا بعد اكتشاف الحريق بالكواشف، ثم يُفتح رأس المرشّ بالحرارة — للأماكن التي تحتوي على معدات حساسة.","• الغمر (Deluge): رؤوس مفتوحة ترشّ جميعها الماء معًا — للأماكن عالية الخطورة.","درجة حرارة التشغيل (Activation Temperature) ولون الأمبولة الزجاجية:","• 57°C (برتقالي): الدرجة العادية (Ordinary) — الأماكن ذات الحرارة المنخفضة.","• 68°C (أحمر): الدرجة العادية (Ordinary) — الأكثر انتشارًا في المكاتب والمصانع.","• 79°C (أصفر) و93°C (أخضر): الدرجة المتوسطة (Intermediate) — الأماكن الأكثر حرارة.","• 141°C (أزرق): الدرجة العالية (High) — غرف المراجل وقرب المعدات الساخنة.","مساحة الحماية لكل رأس عادي (Standard Spray): حتى نحو 21 m² (Light)، و12 m² (Ordinary)، و9 m² (Extra Hazard).","كثافة التصريف (Density): 0.10-0.40 gpm/ft² (نحو 4-16 mm/min) بحسب مستوى الخطر.","NFPA 25: الفحص والاختبار وفق جداول أسبوعية وشهرية وسنوية وكل 5 سنوات.","لا تُفتح المرشّات إلا في موضع الحريق؛ ولا تُفتح جميع الرؤوس معًا (باستثناء نظام الغمر Deluge)."]},{heading:"3. أنظمة الرغوة — NFPA 11 / 16",body:"لمخازن السوائل الكبيرة:",points:["3 أنواع من الرغوة بحسب نسبة التمدّد (Expansion):","• منخفضة (Low-Expansion، حتى 20:1): حرائق الخزانات وانسكاب السوائل.","• متوسطة (Medium-Expansion، من 20:1 إلى 200:1): مناطق جدران الاحتواء.","• عالية (High-Expansion، من 200:1 إلى 1000:1): حظائر الطائرات والأماكن المغلقة الكبيرة.","أنواع مركّز الرغوة (Concentrate):","• AFFF: للهيدروكربونات (البنزين، الديزل).","• AR-AFFF (Alcohol-Resistant): للمذيبات القطبية (الكحول، الأسيتون).","• Fluoroprotein: لخزانات التخزين.","• الرغوة الخالية من الفلور (Fluorine-Free Foam — F3): بديل رغوات PFAS.","معدّل التطبيق (Application Rate):","• انسكاب الهيدروكربونات: لا يقل عن نحو 4.1 L/min/m² (0.10 gpm/ft²).","• المذيبات القطبية: بحسب اعتماد الشركة المصنّعة، وهو أعلى عمومًا.","خطر PFAS: تحتوي AFFF على مواد فلورية (PFAS) تتراكم في الجسم والبيئة؛ وتتجه دول كثيرة نحو الرغوة الخالية من الفلور (F3).","في المصانع: مجمّعات الخزانات، وأماكن تحميل الصهاريج، ومصافي النفط."]},{heading:"4. أنظمة CO₂ والعامل النظيف (Clean Agent) — NFPA 12 / 2001",body:"لغرف المعدات والغمر الكلي (Total Flooding):",points:["الغمر الكلي بـ CO₂:","• تركيز التصميم: 34% على الأقل (NFPA 12)، وأكثر لبعض المواد.","• الخطر: تركيز الإطفاء قاتل للبشر — يجب ألّا يبقى أحد في الغرفة.","• إنذار ما قبل التصريف وزمن التأخير (Time Delay): يجب أن يكون كافيًا لإخلاء الغرفة قبل إطلاق الغاز (NFPA 12).","• الاستخدام: غرف المولّدات، وأماكن اختبار المحركات، ومعدات الطباعة.","العامل النظيف (Clean Agent) — FK-5-1-12 / HFC-227ea:","• NOAEL: في الأماكن المشغولة بالأشخاص، لا يتجاوز تركيز التصميم مستوى عدم ظهور أي أثر ضار (NOAEL) (NFPA 2001)؛ ومع ذلك أخلِ الغرفة.","• تركيز التصميم: عادةً نحو 4-9% بحسب نوع المادة.","• التصريف (Discharge): خلال 10 ثوانٍ للمواد الهالوكربونية (NFPA 2001).","• الاستخدام: غرف الخوادم، وغرف التحكم، وغرف لوحات التوزيع الكهربائية.","• تكلفتها أعلى بكثير من أنظمة الماء.","الهالون Halon 1301: أُوقف إنتاجه في الدول المتقدمة منذ 1994 بموجب بروتوكول مونتريال، لأنه يدمّر طبقة الأوزون؛ ولا تُركَّب به أنظمة جديدة.","الاختبار الهيدروستاتيكي للمطافئ اليدوية (NFPA 10): CO₂ كل 5 سنوات، والعامل النظيف كل 12 سنة؛ أما أسطوانات الأنظمة الثابتة فتخضع لـ NFPA 12 / 2001 ولأنظمة الأسطوانات."]},{heading:"5. أنظمة المسحوق الجاف — NFPA 17",body:"للمخاطر الخاصة:",points:["الأنظمة مسبقة التصميم (Pre-Engineered Systems):","• المطابخ التجارية: تُستخدم فيها الآن عمومًا أنظمة المادة الكيميائية الرطبة (Wet Chemical) وفق NFPA 17A، لا المسحوق الجاف.","• غرف الطلاء بالرش (Spray Booths).","• حماية المعدات والمركبات الثقيلة.","• خزانات الغمس (Dip Tanks).","المواد (Agents):","• بيكربونات الصوديوم (Sodium Bicarbonate): B، C.","• بيكربونات البوتاسيوم (Purple-K): B، C — أقوى من بيكربونات الصوديوم على حرائق الفئة B.","• فوسفات أحادي الأمونيوم (Monoammonium Phosphate): A، B، C.","• كلوريد البوتاسيوم (Potassium Chloride): B، C.","التشغيل (Activation): كاشف حرارة أو مقبض تشغيل يدوي (Manual Pull).","بعد التصريف: ينتشر المسحوق في كل مكان وقد يُتلف الأجهزة الإلكترونية؛ والتنظيف صعب.","تُحدَّد مساحة الحماية لكل فوهة (Nozzle) بحسب اعتماد النظام (Listing)."]},{heading:"6. كشف الحريق — NFPA 72",body:"نظام الكشف — خط الإنذار الأول:",points:["أنواع الكواشف:","• الدخان: الكهروضوئي (Photoelectric) للحرائق البطيئة المكتومة (Smoldering)، والتأيّني (Ionization) للحرائق ذات اللهب (Flaming).","• الحرارة: درجة ثابتة (Fixed Temperature، مثل 57°C) أو الارتفاع السريع (Rate-of-Rise).","• اللهب (Flame): UV/IR — تكشف اللهب بسرعة.","• الغاز: كواشف LEL وحساسات CO.","• سحب عينات الهواء (Air-Sampling): لغرف الخوادم — النوع الأكثر حساسية.","المسافات والمساحات:","• الدخان: المسافة بين الكواشف نحو 9 أمتار (30 ft) على السقف المستوي (NFPA 72).","• الحرارة: بحسب المسافة المعتمدة للكاشف (Listed Spacing).","• اللهب: بحسب زاوية الرؤية والمسافة المعتمدة للجهاز.","الإنذار (Alarm Notification):","• الصوتي (Audible): أعلى عمومًا بـ 15 dB على الأقل من متوسط الضجيج في المكان (NFPA 72).","• الضوئي (Strobe): للأماكن الصاخبة ولذوي الإعاقة السمعية.","• الإنذار الصوتي الناطق (Voice / Mass Notification): للمباني والمصانع الكبيرة.","الفحص والاختبار: وفق جداول NFPA 72 (تُختبر أجهزة كثيرة مرة في السنة)."]},{heading:"7. جدول الفحص والصيانة",body:"وفق معايير NFPA:",points:["يوميًا / أسبوعيًا:","• الفحص البصري (قراءة مقاييس الضغط، والأضرار).","• التأكّد من عدم وجود عوائق أمام المرشّات.","• تشغيل مضخة الحريق دون تدفق الماء (No-flow Test): مضخة الديزل كل أسبوع، والكهربائية عمومًا كل شهر (NFPA 25).","شهريًا:","• الفحص البصري للمطافئ اليدوية (NFPA 10).","• فحص لوحة إنذار الحريق وإشارات الأعطال (Trouble).","• فحص أزرار الإنذار اليدوية (Manual Pull Stations) — ظاهرة وغير محجوبة.","سنويًا:","• الصيانة السنوية للمطافئ اليدوية على يد شخص مختص (وهي ليست الاختبار الهيدروستاتيكي).","• فحص المرشّات من مستوى الأرض (NFPA 25).","• أخذ عينة من مركّز الرغوة لاختبارها.","• اختبار الكواشف وأجهزة الإنذار (NFPA 72).","كل بضع سنوات:","• الاختبار الهيدروستاتيكي للمطافئ (اختبار ضغط جسم المطفأة، NFPA 10): كل 5 سنوات للماء والرغوة والمادة الكيميائية الرطبة (Wet Chemical) وCO₂ والمسحوق الجاف ذي الجسم من الفولاذ المقاوم للصدأ؛ وكل 12 سنة للمسحوق الجاف ذي الضغط المخزَّن (stored-pressure) الذي جسمه من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم، وللعامل النظيف (Clean Agent). وبشكل منفصل، كل 6 سنوات تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن التي تحتاج إلى اختبار كل 12 سنة ويُفحص داخلها على يد شخص مختص. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك.","• الفحص الداخلي لأنابيب المرشّات: كل 5 سنوات (NFPA 25).","• استبدال رؤوس المرشّات أو اختبار عينات منها بعد 50 سنة (الرؤوس العادية — NFPA 25).","التسجيل: دوّن جميع عمليات الفحص والاختبار، واحفظ السجلات وفق المعايير ومتطلبات الجهات المختصة."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"تشغيل المرشّ",description:"عرض توضيحي لعمل المرشّ"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"جدول أنظمة الإطفاء",description:"الأنظمة الثابتة"}],quiz:[{question:"ما أهم نظام ثابت في معظم المصانع؟",options:[{text:"المطافئ اليدوية",correct:!1},{text:"المرشّات (NFPA 13)",correct:!0},{text:"CO₂ فقط",correct:!1},{text:"لا شيء مما سبق",correct:!1,fixed:!0}],explanation:"تعمل المرشّات تلقائيًا وتسيطر على الحريق في مرحلته الأولى، حتى عند عدم وجود أحد في المكان؛ أما المطافئ اليدوية فهي للحرائق الصغيرة فقط."},{question:"لأيّ مكان لا يصلح نظام الأنابيب الرطبة (Wet Pipe)؟",options:[{text:"غرف المعدات (ICT)",correct:!1},{text:"المكاتب ذات درجة الحرارة العادية",correct:!1},{text:"الأماكن التي تنخفض فيها الحرارة إلى ما دون 4°C",correct:!0},{text:"المخازن المدفّأة التي تبقى حرارتها فوق 10°C طوال العام",correct:!1}],explanation:"في الأماكن الباردة يتجمّد الماء في الأنابيب؛ ونظام الأنابيب الجافة (Dry Pipe) هو المناسب."},{question:"هل تُركَّب أنظمة جديدة تعمل بالهالون Halon 1301؟",options:[{text:"نعم",correct:!1},{text:"لا — أُوقف إنتاجه بموجب بروتوكول مونتريال",correct:!0},{text:"نعم — ما زال المادة المعتمدة لغرف ICT الجديدة",correct:!1},{text:"نعم، ولكن فقط في غرف الخوادم الجديدة التي لا يصلح فيها العامل النظيف",correct:!1}],explanation:"يدمّر Halon 1301 طبقة الأوزون؛ وقد أُوقف إنتاجه في الدول المتقدمة منذ 1994."},{question:"لماذا يجب أن يخرج الجميع من الغرفة قبل تصريف نظام الغمر الكلي بـ CO₂؟",options:[{text:"لا داعي لذلك، فـ CO₂ غير ضار بأي تركيز داخل الغرفة",correct:!1},{text:"لأن تركيز الإطفاء (34% فأكثر) قاتل للبشر",correct:!0},{text:"لأن CO₂ يرشّ الماء",correct:!1},{text:"لأن صوت تفريغ CO₂ عالٍ لدرجة أنه قد يُتلف سمع الأشخاص بشكل دائم",correct:!1}],explanation:"يبلغ تركيز تصميم CO₂ في أنظمة الغمر الكلي 34% على الأقل (NFPA 12)، وهذا التركيز يُفقد الإنسان وعيه ويقتله خلال وقت قصير؛ ولهذا يوجد إنذار ما قبل التصريف وزمن التأخير."},{question:"كم تبلغ مساحة الحماية لكل رأس مرشّ (Standard Spray) تقريبًا؟",options:[{text:"2-5 m²",correct:!1},{text:"12-21 m²",correct:!0},{text:"30-40 m²",correct:!1},{text:"80-100 m²",correct:!1}],explanation:"وفق NFPA 13: نحو 21 m² للخطر المنخفض، و12 m² للخطر العادي؛ وأقل من ذلك للخطر المرتفع (نحو 9 m²)."},{question:"ما الاختبار الأسبوعي لمضخة الحريق الديزل؟",options:[{text:"الفحص البصري فقط، دون تشغيل المضخة",correct:!1},{text:"تشغيل المضخة دون تدفق الماء (Start / No-flow Test)",correct:!0},{text:"الاختبار الهيدروستاتيكي",correct:!1},{text:"تشغيل المضخة بتدفق الماء الكامل طوال يوم كامل",correct:!1}],explanation:"وفق NFPA 25: تُشغَّل مضخة الديزل كل أسبوع، والمضخة الكهربائية عمومًا كل شهر، وتُختبر دون تدفق الماء."}]},{id:22,code:"BUS-122",icon:"Building2",accent:"#0f766e",title:"السلامة من الحريق في المحلات والأسواق والمراكز التجارية",subtitle:"المخارج والتخزين والكهرباء والغاز المسال وأدوار الموظفين في الطوارئ",summary:"تمتلئ المحلات والأسواق والمراكز التجارية بزبائن لا يعرفون المبنى، وببضائع سريعة الاشتعال وأجهزة كهربائية، وكثيرًا ما توجد فيها أسطوانات الغاز المسال (LPG). هذا الدرس موجّه إلى أصحاب المحلات ومديريها وموظفيها: كيف تبقى المخارج ومعدات الحريق ظاهرة وخالية من العوائق، وكيف تُمنع حرائق الكهرباء والغاز، وما الذي يفعله كل موظف عندما يدوّي إنذار الحريق. أما قواعد الترخيص والتفتيش المحلية فيحددها الدفاع المدني والجهة المانحة للترخيص؛ فالتزموا بمتطلباتهما.",blocks:[{heading:"1. المخارج ومسارات الهروب والتخزين",body:"يحاول الزبائن عادةً الخروج من الطريق الذي دخلوا منه، لذا يجب أن تكون كل طرق الخروج جاهزة في كل وقت:",points:["أبقِ المخارج والممرات والسلالم خالية تمامًا: لا بضائع ولا صناديق ولا عربات ولا بسطات في الطريق، ولو لوقت قصير.","يجب أن تُفتح أبواب الخروج من الداخل فورًا ومن دون مفتاح أو رمز ما دام في المكان أشخاص؛ وأزل السلاسل والقضبان والأقفال الإضافية قبل فتح المحل.","أبقِ لافتات الخروج ظاهرة: لا يجوز أن تحجب البضائع أو الملصقات الإعلانية أو الزينة باب الخروج أو لافتته.","ضع البضائع الزائدة في المخزن، لا في الممرات ولا تحت السلالم ولا في الأماكن التي يمشي فيها الزبائن.","لا تكدّس البضائع أو الكرتون أو مواد التغليف بجانب اللوحات الكهربائية أو المصابيح أو المدافئ أو معدات الطبخ.","في السوق أو المركز التجاري، اتفق مع الإدارة على المخارج المشتركة وجرس الإنذار ونقطة التجمع، وشارك في التمارين المشتركة."]},{heading:"2. الكهرباء: الحمل الزائد ووصلات التمديد",body:"المقابس المحمّلة فوق طاقتها والأسلاك التي ترتفع حرارتها من الأسباب الشائعة للحرائق في المحلات:",points:["لا تحمّل المقابس ولا المشتركات الكهربائية (Power strip) فوق طاقتها، واستعمل مشتركات مزوّدة بحماية داخلية من الحمل الزائد.","وصلة التمديد (Extension lead) للاستعمال المؤقت فقط، ولا تحلّ أبدًا محل التمديدات الكهربائية الثابتة للمبنى؛ وإذا احتجت إلى مقابس أكثر فاطلب من كهربائي مؤهل تركيبها.","صِل الثلاجات والمجمّدات والمدافئ والأفران وغيرها من الأجهزة الكبيرة بمقبس الجدار مباشرةً، ولا تصلها أبدًا بوصلة تمديد.","لا تمدّ الأسلاك تحت السجاد أو الحُصر، ولا عبر الأبواب أو الممرات، حيث يمكن أن تُسحق أو يتعثّر بها الناس.","استبدل فورًا الأسلاك والقوابس التالفة. فرائحة الاحتراق أو القابس الساخن أو الشرر أو القاطع الكهربائي (Breaker) الذي ينفصل مرارًا تعني: افصل الكهرباء واستدعِ كهربائيًا مؤهلًا."]},{heading:"3. أسطوانات الغاز المسال في المحلات والأسواق",body:"الغاز المسال (LPG) أثقل من الهواء: فالغاز المتسرّب يتجمّع قرب الأرض وفي الأماكن المنخفضة مثل المجاري والسراديب.",points:["لا تُبقِ في المحل إلا أقل عدد من الأسطوانات يحتاجه العمل، وضع الباقي في مخزن منفصل جيد التهوية، ويُفضَّل أن يكون في الهواء الطلق.","لا تضع الأسطوانات أبدًا تحت مستوى الأرض أو في سرداب أو قرب فتحات المجاري.","أبقِ الأسطوانات قائمة وصمّاماتها محمية، في مكان لا يصل إليه الزبائن، بعيدًا عن الحرارة واللهب والمواد القابلة للاشتعال.","لا تضع الأسطوانات أبدًا على السلالم أو بجانب أبواب الخروج أو في أي مكان تسدّ فيه طريق الخروج.","لا يركّب المنظّمات والخراطيم والأجهزة إلا فنيّ مؤهل. ولا تبحث أبدًا عن التسرّب بلهب.","عدد الأسطوانات المسموح للمحل بالاحتفاظ بها ومكانها يحددهما الدفاع المدني والجهة المانحة للترخيص."]},{heading:"4. إذا شممت رائحة الغاز",body:`1. لا تُشعل أي لهب، ولا تُشغّل المصابيح أو الأجهزة أو الآلات ولا تُطفئها. ولا تستعمل الهاتف في الداخل.
2. أوقف البيع، وأخرج الزبائن والموظفين بهدوء من أقرب مخرج.
3. لا تُغلق صمّام الغاز إلا إذا كان قريبًا منك وتستطيع الوصول إليه دون الدخول إلى المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة؛ وإلا فلا تقترب منه.
4. أبعد الناس عن المدخل ونبّه المحلات المجاورة.
5. اتصل بالرقم 115 من الخارج، ولا تسمح لأحد بالعودة إلى الداخل حتى يؤكّد المختصون أن المكان آمن.`,critical:!0},{heading:"5. أدوار الموظفين عندما يدوّي إنذار الحريق",body:"يعرف كل موظف دوره قبل وقوع الطوارئ، وتحدّد خطة الطوارئ شخصًا لكل مهمة في كل مناوبة:",points:["الإنذار: اصرخ «حريق!»، واضغط أقرب نقطة نداء لإنذار الحريق (Call point) إن وُجدت، وتأكّد أن أحدًا يتصل بالرقم 115 من مكان آمن.","توجيه الزبائن: أوقف البيع، واطلب من الزبائن بهدوء أن يغادروا، ودُلّهم على أقرب مخرج، لا على المدخل الرئيسي وحده.","التفقّد: تفقّد دورات المياه وغرف القياس والمخازن والمكاتب في طريقك إلى الخارج، فقط إذا كان ذلك آمنًا، وأغلق الأبواب خلفك.","المساعدة: ساعد من يحتاج إلى المساعدة، مثل كبار السن والأطفال الذين بلا مرافق والأشخاص ذوي الإعاقة. ولا تستعمل المصاعد أبدًا.","عند نقطة التجمع: عُدّ الموظفين، وأبلغ عن أي مفقود، وأخبر رجال الإطفاء بالأماكن التي قد يكون فيها أشخاص وبوجود أسطوانات الغاز وأي مخاطر أخرى.","لا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن."]},{heading:"6. إخلاء الحشود بأمان",body:"في المحل أو المركز التجاري المزدحم، تحدّد طريقة توجيه الموظفين للناس سرعة خروج الجميع:",points:["تكلّم بهدوء وأعطِ تعليمات قصيرة وواضحة، مثل: «اخرجوا من هذا المخرج. امشوا ولا تركضوا.»","استعمل كل المخارج المتاحة، ووجّه الناس إلى مخرج آخر إذا ازدحم أحد المخارج أو سدّه الدخان.","لا تسمح للناس بالتوقف للدفع أو لجمع البضائع أو للعودة إلى الداخل.","أبقِ عدد الموجودين في الداخل ضمن الحد المقرّر للمبنى، ولا سيما في الأعياد وأيام التخفيضات.","في المركز التجاري، اتبع تعليمات فريق الطوارئ في المركز والإعلانات الصوتية، وابتعد مسافة كافية عن المبنى نحو نقطة التجمع."]},{heading:"7. معدات الحريق وحقيبة الإسعافات الأولية وجهاز AED",body:"لا تنقذ المعدات الأرواح إلا إذا استطاع الناس رؤيتها والوصول إليها واستعمالها:",points:["أبقِ مطفآت الحريق ونقاط نداء الإنذار وبطانيات الحريق ظاهرة وفي أماكنها وخالية من العوائق، وتأكّد كل يوم أن لا شيء يحجبها.","لا تستعمل مطفأة الحريق إلا إذا كنت مدرّبًا، وكانت النار صغيرة وفي بدايتها، وكان الملصق يبيّن أنها مناسبة لهذه النار، ونُبِّه الآخرون، واتُّصل بالرقم 115، وكان طريق خروجك خلفك. وإلا فاخرج وأغلق الباب.","تحتاج كل مطفأة إلى فحص نظري كل شهر (في مكانها، ومسمار الأمان والختم سليمان، ومؤشر مقياس الضغط في المنطقة الخضراء، ولا ضرر ظاهرًا) وإلى صيانة على يد شخص مؤهل؛ أما الجدول المحلي فيحدده الدفاع المدني.","ضع حقيبة إسعافات أولية مكتملة في مكان يصل إليه الموظفون بسرعة، واعرف من المدرَّب على الإسعافات الأولية في كل مناوبة.","إذا كان في المحل أو المركز التجاري جهاز إزالة الرجفان الخارجي الآلي (AED)، فإن كل الموظفين يعرفون مكانه. وإذا سقط شخص ولا يتنفس بشكل طبيعي: اتصل بالرقم 122، وابدأ الإنعاش القلبي الرئوي (CPR)، وأرسل أحدًا فورًا لإحضار الجهاز."]}],media:[{kind:"image",src:"media/images/w8_shop_evacuation.webp",title:"إخلاء محل تجاري",description:"موظف يوجّه الزبائن نحو أقرب مخرج وزميله يتفقّد المخزن"}],quiz:[{question:"المخزن ممتلئ ووصلت شحنة جديدة. أين يمكن وضع الصناديق الزائدة؟",options:[{text:"في ممر مخرج الحريق، حتى نهاية يوم العمل",correct:!1},{text:"تحت السلالم، ما دام الزبائن لا يرونها",correct:!1},{text:"في مخزن آخر أو مكان بعيد عن المخارج والممرات",correct:!0},{text:"أمام مطفأة الحريق، حيث توجد مساحة فارغة على الأرض",correct:!1}],explanation:"يجب أن تبقى المخارج والممرات والسلالم خالية في كل وقت، ولو لمدة قصيرة، ولا يجوز أن يحجب شيء معدات الحريق. فالبضائع الزائدة توضع في مخزن بعيد عن المخارج والممرات."},{question:"ثلاجة عرض جديدة تحتاج إلى الكهرباء. ما الطريقة الآمنة لتوصيلها؟",options:[{text:"صِلها بالمشترك الذي تعمل عليه المصابيح وصندوق الدفع منذ مدة",correct:!1},{text:"صِلها بمقبس الجدار مباشرةً، ويضيف الكهربائي مقابس عند الحاجة",correct:!0},{text:"مدّ وصلة تمديد إليها تحت سجادة الأرض حتى لا يتعثر بها أحد",correct:!1},{text:"اربط وصلتي تمديد معًا للوصول إلى المقبس الذي بجانب الباب",correct:!1}],explanation:"تُوصَل الأجهزة الكبيرة بمقبس الجدار مباشرةً. فوصلة التمديد مؤقتة وتُحمَّل فوق طاقتها بسهولة، والسلك الممدود تحت السجادة قد يُسحق ويسخن."},{question:"يشمّ الموظفون رائحة غاز قوية قرب أسطوانات المحل، والصمّام في وسط مكان الرائحة. ما التصرف الصحيح؟",options:[{text:"اذهب إلى الصمّام وأغلقه، ثم شغّل المروحة لطرد الغاز من المحل",correct:!1},{text:"أشعل المصابيح لترى التسرّب، واختبر الخرطوم بالقدّاحة",correct:!1},{text:"اتصل بشركة الغاز من داخل المحل وأنت تبحث عن التسرّب",correct:!1},{text:"ابتعد عن الصمّام، وأخرج الجميع، واتصل بالرقم 115 من الخارج",correct:!0}],explanation:"لا يُغلق الصمّام إلا إذا أمكن الوصول إليه دون دخول منطقة الغاز ودون أي شرارة. وهنا لا يمكن ذلك، فلا يقترب منه أحد: لا مفاتيح كهربائية، ولا هاتف في الداخل، ويخرج الجميع، ويُتّصل بالرقم 115 من الخارج."},{question:"يدوّي إنذار الحريق في محل مزدحم. ماذا يفعل الموظف المسؤول عن دورات المياه والمخازن؟",options:[{text:"يتفقّدها في طريقه إن كان ذلك آمنًا، ثم يبلّغ عند نقطة التجمع",correct:!0},{text:"يبقى عند صندوق الدفع لإكمال كل عمليات البيع قبل أن يغادر المبنى",correct:!1},{text:"يقفل المخازن حتى لا يأخذ أحد أي بضائع منها في أثناء الحريق",correct:!1},{text:"يعود وحده إلى داخل المبنى بعد العدّ ليبحث عن أي شخص مفقود",correct:!1}],explanation:"تفقّد دورات المياه والمخازن في طريق الخروج، فقط إذا كان ذلك آمنًا، يضمن ألّا يبقى أحد في الداخل. وتُبلَّغ النتيجة عند نقطة التجمع؛ ولا يعود أحد إلى الداخل."},{question:"في أثناء الإخلاء، يزدحم الزبائن عند المدخل الرئيسي بينما مخرج آخر خالٍ. ماذا يفعل الموظفون؟",options:[{text:"يطلبون من الجميع الانتظار داخل المحل حتى يخلو المدخل الرئيسي",correct:!1},{text:"يوجّهون الناس بهدوء وبتعليمات قصيرة وواضحة إلى المخرج الخالي",correct:!0},{text:"يشغّلون المصاعد ليتمكّن عدد أكبر من الناس من مغادرة الطابق معًا",correct:!1},{text:"يطلبون من الزبائن الدفع بسرعة حتى يتحرك الطابور أسرع",correct:!1}],explanation:"يميل الناس إلى الخروج من الطريق الذي دخلوا منه. فيستعمل الموظفون كل المخارج المتاحة ويوجّهون الناس بهدوء إلى مخرج خالٍ؛ ولا تُستعمل المصاعد أبدًا في الحريق."}]},{id:23,code:"BUS-123",icon:"CookingPot",accent:"#c2410c",title:"السلامة من الحريق في المطاعم والمطابخ التجارية",subtitle:"حرائق الزيت والدهون وأنظمة غطاء الشفط والغاز وتدريب الموظفين",summary:"يجمع المطبخ التجاري الحرارة والزيت والدهون والغاز في مكان ضيق، ويمكن أن تمتد النار من مقلاة أو قلّاية إلى غطاء الشفط (Hood) ومجراه خلال لحظات. هذا الدرس موجّه إلى أصحاب المطاعم ومديريها والطهاة وموظفي الخدمة: كيف يتعاملون مع حريق الزيت، وما الذي يفعله نظام إطفاء الحريق في غطاء الشفط، وكيف يستعملون الغاز بأمان، ولماذا يجب تنظيف الدهون، وكيف يُخرجون الزبائن. التزموا بمتطلبات الدفاع المدني والجهة المانحة للترخيص.",blocks:[{heading:"1. حرائق الزيت والدهون: لا ماء أبدًا",body:"يحتاج الزيت والدهن المشتعلان إلى تعامل خاص:",points:["لا تصبّ الماء أبدًا على الزيت أو الدهن المشتعل: فالماء يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل في كرة نار.","لا تحمل المقلاة أو القلّاية المشتعلة ولا تحرّكها.","حريق صغير في مقلاة: أطفئ الحرارة أو الغاز عند الجهاز فقط إذا استطعت الوصول إليه بأمان، ثم مرّر غطاءً معدنيًا فوق المقلاة أو غطّها ببطانية الحريق، واتركها مغطاة حتى تبرد.","مطفأة مسحوق ABC أو مطفأة الرغوة غير مناسبة للقلّاية العميقة (Deep fryer): فالزيت يبقى ساخنًا وقد يشتعل من جديد.","إذا لم تكن النار صغيرة، أو وصلت إلى غطاء الشفط، أو لم تنطفئ فورًا: اخرج وأغلق الباب واتصل بالرقم 115."],critical:!0},{heading:"2. مطفأة المادة الكيميائية الرطبة (الفئة K / الفئة F)",body:"تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. لذا فالفئة K (NFPA) والفئة F (EN 2) فئة واحدة: زيوت الطبخ ودهونه.",points:["صُنعت مطفأة المادة الكيميائية الرطبة (Wet Chemical) لزيوت الطبخ ودهونه: فهي تكوّن طبقة شبيهة بالصابون على سطح الزيت تعزل الهواء وتبرّد الزيت.","إذا كان في المطبخ نظام إطفاء في غطاء الشفط، فشغّل النظام أولًا (تلقائيًا أو بمقبض التشغيل اليدوي)، ثم استعمل المطفأة بعد ذلك. وتوضّح ذلك لافتةٌ بجانب المطفأة.","اقرأ الملصق قبل وقوع الطوارئ: الفئة ومدى التشغيل وطريقة الاستعمال. فبعض مطافئ المادة الكيميائية الرطبة تُشغَّل بطريقة تختلف عن PASS؛ اتبع الملصق وتعليمات الشركة المصنّعة.","لا تستعملها إلا إذا كنت مدرّبًا، وكانت النار صغيرة، وقد أُطلق الإنذار، وكان طريق خروجك خلفك.","لون المطفأة ليس فئتها: اقرأ الملصق دائمًا."]},{heading:"3. نظام إطفاء الحريق في غطاء الشفط",body:"في كثير من المطابخ التجارية نظام إطفاء ثابت داخل غطاء الشفط فوق القلّايات والشوّايات والطبّاخات. لا يتولّى الموظفون صيانته، لكن يجب أن يعرف الجميع كيف يعمل:",points:["عندما تسخّن نارٌ تحت غطاء الشفط النظامَ، يعمل تلقائيًا ويرشّ مادة إطفاء من فوهات الرش (Nozzles) على أسطح الطبخ وداخل غطاء الشفط ومجراه.","وعندما يعمل يقطع أيضًا الغاز أو الكهرباء عن أجهزة الطبخ الموجودة تحت غطاء الشفط، ولا يعيد تشغيلها بعد ذلك إلا شخص مؤهل.","إذا لم يعمل تلقائيًا، فاستعمل مقبض التشغيل اليدوي (Pull station). وهو على طريق الخروج من المطبخ، ويجب أن يعرف كل طاهٍ مكانه، ولا يجوز أن يحجبه شيء.","أبقِ مرشّحات غطاء الشفط نظيفة وفي أماكنها. وأبقِ فوهات الرش نظيفة، ولا تغطّها ولا تثنِها ولا تحرّكها أبدًا.","لا تنقل أجهزة الطبخ التي تحت غطاء الشفط ولا تُضف إليها ولا تستبدلها من دون أن يفحص مركّب النظام ذلك: ففوهات الرش موجّهة إلى أجهزة محددة.","تفحص شركة مؤهلة النظام وتصونه بانتظام وتعلّق عليه بطاقة الصيانة؛ أما المدة بين الفحوص فيحددها الدفاع المدني والجهة المانحة للترخيص."]},{heading:"4. أسطوانات الغاز ومشعب الغاز والأنابيب",body:"لا يكون الغاز في المطبخ آمنًا إلا إذا رُكّب واستُعمل بطريقة صحيحة:",points:["أبقِ أسطوانات الغاز ومشعبها (Manifold، وهو الأنبوب الذي يربط عدة أسطوانات معًا) خارج المطبخ، في مكان جيد التهوية، قائمةً ومحميةً من الحرارة ومن العبث؛ ولا تضعها أبدًا في سرداب أو تحت مستوى الأرض.","لا يركّب أنابيب الغاز والمنظّمات والأجهزة ولا يوصلها ولا يصلحها ولا يصونها إلا فنيّ غاز مؤهل. ولا يغيّر الموظفون الأسطوانات إلا إذا تدرّبوا على ذلك.","درّب الموظفين على البحث كل يوم عن الأعطال الظاهرة، مثل خرطوم أو وصلة تالفة، أو لهب ينطفئ ولا يبقى مشتعلًا، أو رائحة غاز، وعلى الإبلاغ عنها والتوقف عن استعمال الجهاز.","إذا كان الغاز مربوطًا بمروحة الشفط (Interlock)، فإن الغاز ينقطع عندما تتوقف المروحة. ولا تتجاوز هذا الربط أبدًا ولا تعطّله.","يعرف كل طاهٍ مكان صمّام غاز المطبخ، ولا يستعمله إلا بالطريقة التي تسمح بها قاعدة رائحة الغاز أدناه.","لا تبحث أبدًا عن تسرّب الغاز بلهب."]},{heading:"5. إذا شممت رائحة الغاز في المطبخ",body:`1. لا تُشعل أي لهب، ولا تُشغّل المصابيح أو المراوح أو الأجهزة ولا تُطفئها. ولا تستعمل الهاتف في الداخل.
2. لا تُغلق صمّام الغاز إلا إذا كان قريبًا منك وتستطيع الوصول إليه دون الدخول إلى المكان الذي تجمّع فيه الغاز ودون إحداث أي شرارة؛ وإلا فلا تقترب منه.
3. أخرج الموظفين والزبائن بهدوء ونبّه الجيران.
4. اتصل بالرقم 115 من الخارج، ولا تعد إلى الداخل حتى يؤكّد المختصون أن المكان آمن.`,critical:!0},{heading:"6. الدهون: تنظيف غطاء الشفط والمرشّحات والمجرى",body:"الدهون التي تتراكم في غطاء الشفط والمرشّحات ومجرى العادم وقودٌ ينتظر لهبًا:",points:["قد يُشعل لهبُ القلي أو الشوي أو الفلمبيه (Flambé) الدهونَ المتراكمة، ويمكن أن ينتشر الحريق في المجرى عبر المبنى.","نظّف المرشّحات وأسطح غطاء الشفط والجدران والأرضيات والأجهزة وفق جدول محدد، حتى لا تتراكم الدهون.","اطلب من شركة مؤهلة تنظيف مجرى العادم بانتظام، واحتفظ بالسجل. ويعتمد عدد مرات التنظيف على نوع الطبخ وكميته؛ أما المتطلب فيحدده الدفاع المدني والجهة المانحة للترخيص.","لا تُفرغ القلّاية ولا تنظّفها إلا بعد أن يبرد الزيت، ولا تحرّك القلّاية أبدًا والزيت ساخن.","أبقِ الكرتون والقماش والورق وعبوات الزيت بعيدًا عن أجهزة الطبخ والحرارة."]},{heading:"7. تدريب الموظفين وإخراج الزبائن",body:"يعرف الجميع في المطعم الخطة منذ اليوم الأول للعمل:",points:["تحدّد خطة الطوارئ من يُطلق الإنذار، ومن يتصل بالرقم 115، ومن يقطع الغاز إذا كان ذلك آمنًا، ومن يوجّه الزبائن، ومن يعدّ الموظفين عند نقطة التجمع.","يطلب موظفو الخدمة من الزبائن بهدوء الخروج من أقرب مخرج، ولا يسمحون لهم بالتوقف للدفع أو لجمع أغراضهم.","تفقّد دورات المياه وقاعات الطعام والمخازن في طريق الخروج، فقط إذا كان ذلك آمنًا، وأغلق الأبواب خلفك.","أبقِ الباب الخلفي ومخرج المطبخ خاليين، ولا تقفل أبواب الخروج أبدًا ما دام في الداخل موظفون أو زبائن.","في اليوم الأول، أرِ كل موظف جديد المخارج ومقبض التشغيل اليدوي والمطفأة وبطانية الحريق وصمّام الغاز، واختبروا الخطة بالتمارين.","عند نقطة التجمع، أخبر رجال الإطفاء هل عمل نظام غطاء الشفط، وهل قُطع الغاز، وهل هناك أحد مفقود."]}],media:[{kind:"image",src:"media/images/w8_kitchen_grease_fire.webp",title:"حريق زيت في مطبخ تجاري",description:"طاهٍ يمرّر غطاءً معدنيًا فوق مقلاة مشتعلة، ويظهر مقبض التشغيل اليدوي ومطفأة المادة الكيميائية الرطبة قرب المخرج"}],quiz:[{question:"يشتعل حريق صغير في مقلاة على الطبّاخ. ما التصرف الصحيح؟",options:[{text:"اسكب كوب ماء على المقلاة ليبرد الزيت بسرعة وتنطفئ النار",correct:!1},{text:"احمل المقلاة بسرعة إلى الخارج لتُخرج النار من المطبخ",correct:!1},{text:"إن كان آمنًا أطفئ الحرارة وغطِّ المقلاة بغطاء معدني",correct:!0},{text:"أحضر مطفأة مسحوق ABC من المكتب ورشّها على المقلاة",correct:!1}],explanation:"تغطية المقلاة تعزل الهواء، وإطفاء الحرارة يمنع ازدياد سخونة الزيت. أما الماء فيقذف الزيت المشتعل في كرة نار، وتحريك المقلاة ينشر النار، ومسحوق ABC غير مصنوع لزيت الطبخ."},{question:"حريق تحت غطاء الشفط لا ينطفئ، وفي المطبخ نظام إطفاء في غطاء الشفط ومطفأة مادة كيميائية رطبة. ما الذي يأتي أولًا؟",options:[{text:"شغّل نظام غطاء الشفط بالمقبض اليدوي، ثم استعمل المطفأة",correct:!0},{text:"استعمل المطفأة أولًا واترك النظام لحريق أكبر منه",correct:!1},{text:"أوقف مروحة الشفط وانزع المرشّحات ليخرج الدخان من المطبخ",correct:!1},{text:"انتظر حتى يعمل النظام وحده قبل أن تفعل أي شيء آخر",correct:!1}],explanation:"يقطع نظام غطاء الشفط الغاز أو الكهرباء ويغطي أسطح الطبخ وغطاء الشفط والمجرى بمادة الإطفاء. وقد صُنعت مطفأة المادة الكيميائية الرطبة لتُستعمل بعد تشغيل النظام، كما تقول اللافتة التي بجانبها."},{question:"لماذا لا يجوز نقل أجهزة الطبخ التي تحت غطاء الشفط أو استبدالها من دون مركّب النظام؟",options:[{text:"لأن الأجهزة الأثقل قد تكسر بلاط الأرض الموجود تحت غطاء الشفط",correct:!1},{text:"لأن فوهات الرش موجّهة إلى أجهزة محددة وقد لا تغطي جهازًا جديدًا",correct:!0},{text:"لأن نقلها يزيد ضجيج المطبخ كثيرًا ويزعج الطهاة والزبائن في المطعم",correct:!1},{text:"لأن الأجهزة الجديدة تأتي دائمًا مع نظام إطفاء خاص بها مدمج فيها",correct:!1}],explanation:"يحمي النظام الأجهزة التي صُمّم لها. فإذا نُقل جهاز أو استُبدل، يجب أن يتحقق المركّب من أن فوهات الرش ما زالت تغطيه."},{question:"أين يجب أن تكون أسطوانات الغاز المسال ومشعب الغاز في المطعم؟",options:[{text:"في السرداب، حيث تبقى باردة وبعيدة عن طريق الموظفين",correct:!1},{text:"داخل المطبخ تحت الطبّاخ، قرب الشعلات التي تغذيها",correct:!1},{text:"في مخزن قاعة الطعام، خلف الكراسي المكدّسة هناك",correct:!1},{text:"في الخارج في مكان جيد التهوية، قائمة ومحمية من الحرارة",correct:!0}],explanation:"الغاز المسال أثقل من الهواء ويتجمّع في الأماكن المنخفضة مثل السراديب. لذا توضع الأسطوانات في الخارج في مكان جيد التهوية، قائمة وبعيدة عن الحرارة، ويركّب فنيّ مؤهل الوصلات."},{question:"لماذا يُعدّ تنظيف الدهون من غطاء الشفط والمرشّحات والمجرى مهمة من مهام السلامة من الحريق؟",options:[{text:"لأن الدهون المتراكمة قد تشتعل من لهب الطبخ وتنتشر في المجرى",correct:!0},{text:"لأن الدهون تغيّر رائحة الطعام فقط ولا تزيد خطر الحريق أبدًا",correct:!1},{text:"لأن المجاري النظيفة تجعل نظام غطاء الشفط يعمل خطأً أكثر",correct:!1},{text:"لأن طبقة الدهون تحمي معدن المجرى من حرارة الطبخ العالية",correct:!1}],explanation:"قد يُشعل لهب القلي أو الشوي أو الفلمبيه الدهونَ في غطاء الشفط والمجرى، ويمكن أن ينتشر الحريق في المجرى عبر المبنى. والتنظيف المنتظم يزيل هذا الوقود."}]},{id:24,code:"BUS-124",icon:"Building",accent:"#6d28d9",title:"السلامة من الحريق في الفنادق وأماكن إقامة النزلاء",subtitle:"إنذارات الليل ومعلومات النزلاء وأدوار الموظفين والنزلاء الذين يحتاجون إلى مساعدة",summary:"في الفندق ينام النزلاء في مبنى لا يعرفونه، وبعضهم لا يستطيع الخروج من دون مساعدة؛ لذلك يكون الحريق ليلًا أكبر خطر. هذا الدرس موجّه إلى أصحاب الفنادق ومديريها وموظفي الاستقبال وموظفي المناوبة الليلية: ما الذي يجب إبلاغ النزلاء به، وقاعدة باب الغرفة، وما الذي يفعله كل موظف ليلًا، وكيف يُساعَد النزلاء ذوو الإعاقة، وكيف تحمي أجهزة إنذار الدخان وأبواب الحريق الجميع. التزموا بمتطلبات الدفاع المدني والجهة المانحة للترخيص.",blocks:[{heading:"1. لماذا يكون الليل أكبر خطر",body:"يجب أن تنجح خطة الحريق في الفندق في أسوأ الأوقات أيضًا:",points:["يستيقظ النزلاء النائمون ببطء وقد يكونون مرتبكين، ولا يعرفون المبنى ولا مخارجه.","بعد أن يدوّي الإنذار، قد لا تتوفر إلا دقائق قليلة للخروج بأمان.","ينتشر الدخان في الممرات ويصعد عبر السلالم؛ والأبواب المغلقة تبطئ انتشار الدخان والحرارة والنار.","يكون عدد الموظفين ليلًا في أدنى حدوده، لذا يجب أن تنجح الخطة بفريق المناوبة الليلية وحده، وأن يكون عدد الموظفين كافيًا لمساعدة النزلاء الذين لا يستطيعون الخروج وحدهم."]},{heading:"2. الإنذار وكواشف الدخان وأبواب الحريق",body:"تحمي هذه الوسائل النزلاء وهم نائمون، ما دامت تعمل:",points:["في كل غرفة نزلاء كاشف دخان وجهاز إنذار صوته عالٍ بما يكفي لإيقاظ نزيل نائم.","اعرض على النزلاء الصمّ أو ضعاف السمع غرفة فيها إنذار بضوء وامض أو بوسادة اهتزاز (Vibrating pad)، إن وُجدت.","تُغلق أبواب الحريق (Fire door) في الممرات والسلالم من تلقاء نفسها. فلا تُبقِها مفتوحة أبدًا بإسفين أو بربطها، وأبلغ فورًا عن أي باب لا يُغلق تمامًا.","يوفّر نظام الرشاشات (Sprinkler) في كل غرفة نزلاء حماية إضافية حيث يكون مركّبًا.","تأكّد كل يوم أن طرق الخروج خالية، وأن أبواب الخروج تُفتح، وأن إنارة الطوارئ تعمل؛ أما مواعيد الاختبار والصيانة فيحددها الدفاع المدني."]},{heading:"3. ما يجب أن يعرفه كل نزيل",body:"أعطِ كل نزيل معلومات الحريق عند تسجيل وصوله:",points:["تُبيّن خطة الإخلاء المثبّتة على الوجه الداخلي لباب الغرفة موقعَ الغرفة والطرقَ المؤدية إلى أقرب المخارج.","أخبر النزلاء كيف يبدو صوت إنذار الحريق وأين أقرب مخرجين، واقترح عليهم أن يعدّوا الأبواب بين غرفتهم والمخرج؛ فهذا يساعد في الظلام أو في الدخان.","أبقِ مفتاح الغرفة بجانب السرير وخذه معك عند الخروج.","عندما يدوّي الإنذار: اخرج فورًا، وأغلق الأبواب خلفك، واستعمل الدرج، ولا تستعمل المصعد أبدًا.","تُفتح أبواب الخروج على طرق الإخلاء من الداخل دون مفتاح في كل الأوقات."]},{heading:"4. قاعدة باب الغرفة",body:"علّمها للموظفين واكتبها على إرشادات الحريق في كل غرفة:",points:["قبل فتح باب الغرفة، تحسّس الباب ومقبضه بظاهر يدك. فإن كان ساخنًا، أو كان الدخان يتسرّب من حوله، فأبقِه مغلقًا.","إذا كان الباب باردًا، فافتحه ببطء وكن مستعدًا لإغلاقه فورًا إذا كان في الخارج دخان أو نار.","إذا كان الممر خاليًا، فاخرج وأغلق الباب خلفك واتجه إلى أقرب مخرج؛ وإذا كان هناك دخان فانخفض.","إذا كانت كل طرق الخروج مسدودة: ابقَ في الغرفة والباب مغلق، وسدّ الفتحات حول الباب وفتحات التهوية بالمناشف أو أغطية السرير، وأطفئ المراوح والمكيّف، واتصل بالرقم 115 واذكر رقم الغرفة، ولوّح من النافذة.","لا تقفز من الطوابق العالية؛ انتظر رجال الإطفاء."]},{heading:"5. أدوار الموظفين ليلًا",body:"تحدّد الخطة الليلية من يفعل ماذا، حتى لو لم يكن في المناوبة إلا موظف أو اثنان:",points:["يتحقق موظف الاستقبال من الإنذار، ويتصل فورًا بالرقم 115، ويذكر العنوان ومكان الحريق وعدد النزلاء في الفندق.","يأخذ موظف الاستقبال قائمة الغرف المشغولة وقائمة النزلاء الذين يحتاجون إلى مساعدة إلى نقطة التجمع.","ينبّه الموظفون النزلاء ويوجّهونهم إلى المخارج في طريقهم إلى الخارج، ولا يتفقّدون الغرف ودورات المياه والممرات إلا حيث يكون ذلك آمنًا؛ ولا يدخلون الدخان أبدًا ولا يفتحون بابًا ساخنًا.","عند نقطة التجمع، قارن قائمة الغرف المشغولة بالأشخاص الحاضرين.","استقبل رجال الإطفاء عند وصولهم وأخبرهم بالغرف التي قد يكون فيها نزلاء بعدُ، وبمكان انتظار النزلاء الذين يحتاجون إلى مساعدة، وبأي مخاطر خاصة مثل الغاز.","لا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن."]},{heading:"6. النزلاء ذوو الإعاقة",body:"خطّط لهم قبل الليلة التي يحتاجون فيها إلى المساعدة:",points:["عند تسجيل الوصول، اسأل النزلاء بلطف وعلى انفراد هل سيحتاجون إلى مساعدة للخروج في حالة الطوارئ، واحتفظ في الاستقبال بقائمة بأسمائهم وأرقام غرفهم.","امنح هؤلاء النزلاء إن أمكن غرفة في طابق منخفض وقريبة من مخرج.","لا تستعمل أبدًا المصعد العادي في الحريق. فالنزيل الذي لا يستطيع استعمال الدرج يُبعَد عن النار عبر أبواب الحريق في الطابق نفسه، أو ينتظر مع أحد الموظفين في منطقة اللجوء المجاورة لدرج محمي، كما تنص خطة الفندق.","لا تترك نزيلًا وحده أبدًا في منطقة اللجوء، وأخبر رجال الإطفاء فورًا وبدقة بمكان انتظاره.","لا يجوز أن تعتمد الخطة على رجال الإطفاء لإنقاذ النزلاء المنتظرين: يجب أن يكون هناك عدد كافٍ من الموظفين المدرّبين لمساعدتهم."]},{heading:"7. التدريب والتمارين",body:"لا يستطيع الموظفون أن يفعلوا ليلًا إلا ما تدرّبوا عليه:",points:["درّب كل موظف جديد قبل أول مناوبة ليلية له: الإنذار، والمخارج، وأبواب الحريق، وقوائم الغرف، ودوره الخاص.","نفّذ التمارين، ومنها تمارين في الأوقات التي يكون فيها عدد الموظفين في أدنى حدوده، وتدرّبوا على افتراض أن أحد المخارج أو السلالم مسدود.","أبقِ خطة الطوارئ وقوائم الغرف في متناول اليد في الاستقبال، وحدّث القوائم عند كل تسجيل وصول ومغادرة.","يحدد الدفاع المدني والجهة المانحة للترخيص عدد مرات التمارين والتدريب المطلوب."]}],media:[{kind:"image",src:"media/images/w8_hotel_night_evacuation.webp",title:"إخلاء النزلاء ليلًا في فندق",description:"موظف المناوبة الليلية يوجّه النزلاء بمصباح يدوي عبر الممر نحو درج الخروج، وباب حريق مغلق خلفهم"}],quiz:[{question:"ماذا يجب أن تُبيّن خطة الإخلاء المثبّتة على الوجه الداخلي لباب غرفة النزيل؟",options:[{text:"موقع الغرفة والطرق المؤدية إلى أقرب مخرجين",correct:!0},{text:"رقم هاتف الفندق وموعد المغادرة فقط",correct:!1},{text:"الطريق إلى المصعد والطريق إلى المدخل الرئيسي وحدهما",correct:!1},{text:"مكان مطعم الفندق ومكان موقف السيارات",correct:!1}],explanation:"تبيّن الخطة على الباب موقع الغرفة والطرق إلى المخارج، ليجد النزيل طريقه بسرعة حتى في الظلام. ولا يُستعمل المصعد في الحريق."},{question:"يدوّي الإنذار ليلًا، ويشعر نزيل بأن مقبض باب غرفته ساخن. ماذا يجب أن يفعل؟",options:[{text:"يفتح الباب بسرعة ويركض عبر الممر نحو أقرب درج للخروج",correct:!1},{text:"يفتح الباب قليلًا لينظر إلى الممر ثم يقرّر ما يفعل",correct:!1},{text:"يُبقي الباب مغلقًا ويسدّ الفتحات ويتصل بالرقم 115 ويلوّح",correct:!0},{text:"ينزل بالمصعد لأن الممر قد يكون مليئًا بالدخان الكثيف",correct:!1}],explanation:"المقبض الساخن يعني وجود نار أو دخان ساخن خلف الباب. والباب المغلق يحمي النزيل: سُدّ الفتحات وفتحات التهوية، واتصل بالرقم 115، واذكر رقم الغرفة، ولوّح من النافذة."},{question:"في أثناء الإخلاء الليلي، أي مهمة تخصّ موظف الاستقبال؟",options:[{text:"البقاء عند المكتب للرد على اتصالات النزلاء حتى تنطفئ النار",correct:!1},{text:"الاتصال بالرقم 115 وأخذ قائمة الغرف المشغولة إلى نقطة التجمع",correct:!0},{text:"دخول كل الغرف، ومنها الغرف المليئة بالدخان، للبحث فيها",correct:!1},{text:"جمع حقائب النزلاء قبل الخروج من المبنى",correct:!1}],explanation:"يتصل موظف الاستقبال بالرقم 115 فورًا ويأخذ قوائم الغرف، حتى يجري العدّ عند نقطة التجمع ويعرف رجال الإطفاء الغرف التي قد يكون فيها نزلاء بعدُ. ولا يدخل أحد الدخان."},{question:"نزيل يستعمل كرسيًا متحركًا في الطابق الثالث عندما يدوّي الإنذار. ما التصرف الصحيح؟",options:[{text:"ينزل به موظف في المصعد العادي لأنه أسرع من الدرج",correct:!1},{text:"يتركه الموظفون وحده في منطقة اللجوء وينتظرون رجال الإطفاء في الخارج",correct:!1},{text:"يطلب منه الموظفون البقاء في غرفته حتى يتوقف الإنذار وحده",correct:!1},{text:"يأخذه موظف إلى منطقة اللجوء، ويبقى معه، ويُبلغ رجال الإطفاء بمكانه",correct:!0}],explanation:"لا يُستعمل المصعد العادي في الحريق. يُبعَد النزيل عن النار أو ينتظر مع موظف في منطقة اللجوء، ولا يُترك وحده أبدًا، ويعرف رجال الإطفاء مكانه فورًا."},{question:"لماذا لا يجوز إبقاء أبواب الحريق في ممرات الفندق مفتوحة بإسفين؟",options:[{text:"لأن الأبواب المفتوحة تُدخل هواء الدرج البارد إلى ممرات النزلاء في ساعات الليل المتأخرة",correct:!1},{text:"لأن باب الحريق المغلق يبطئ الدخان والحرارة والنار ويحمي طريق الخروج",correct:!0},{text:"لأن الأبواب المفتوحة تجعل النزلاء يسمعون الإنذار عاليًا جدًا في غرفهم",correct:!1},{text:"لأن أبواب الحريق ثقيلة والإسفين يُتلف مفصّلاتها مع مرور الوقت",correct:!1}],explanation:"لا يحمي باب الحريق إلا وهو مغلق: فهو يبطئ انتشار الدخان والحرارة والنار ويُبقي طريق الخروج آمنًا للنزلاء. أما الباب المفتوح بإسفين فلا يوفّر هذه الحماية."}]},{id:25,code:"BUS-125",icon:"Fuel",accent:"#b45309",title:"السلامة في محطات الوقود",subtitle:"Ignition Control, Static, Spills, Emergency Stop & LPG",summary:"تخزّن محطات الوقود كميات كبيرة من السوائل والغازات القابلة للاشتعال وتوزّعها. تبيّن هذه الوحدة للعاملين والمشرفين والمديرين كيف يسيطرون على مصادر الاشتعال والكهرباء الساكنة، ويتعاملون مع انسكاب الوقود، ويستخدمون زر الإيقاف الطارئ، ويعبّئون غاز البترول المسال (LPG) بأمان، وماذا يفعلون إذا نشب حريق عند المضخة.",blocks:[{body:"يطلق البنزين أبخرة قابلة للاشتعال حتى في الطقس البارد (نقطة وميضه نحو -43°C)، وأبخرته أثقل من الهواء: تنتشر على الأرض وتتجمع في الأماكن المنخفضة مثل مجاري الصرف والحفر والأقبية. ويمكن أن تشعلها شرارة أو لهب أو سيجارة أو محرك يعمل. ويضع الدفاع المدني والجهة المانحة للترخيص قواعد ترخيص محطات الوقود وتصميمها وتجهيزاتها: التزم بمتطلباتهما. وتوضح هذه الوحدة ما يجب على كل عامل ومشرف ومدير أن يفعله."},{heading:"1. السيطرة على مصادر الاشتعال عند المضخات",body:"قبل التعبئة وفي أثنائها، يتأكد العامل من أن:",points:["محرك المركبة مطفأ عند المضخة.","لا أحد يدخّن أو يستخدم ولّاعة أو لهبًا مكشوفًا قرب المضخات، وأن لافتتَي «ممنوع التدخين» و«أطفئ المحرك» مثبتتان قرب المضخات.","المراقبة مستمرة: ترى كل مركبة وكل شخص عند المضخات، ولا تشغّل المضخة إلا حين لا يوجد أي خطر.","لا تعبّئ إذا كان المحرك يعمل، أو كان أحد يدخّن بالقرب، أو كانت العبوة غير معتمدة؛ واستدعِ المشرف إذا رفض الزبون.","الهواتف: طبّق قاعدة محطتك (تطلب بعض الإرشادات عدم استخدام الهواتف وأجهزة اللاسلكي عند المضخات)، وأبقِ انتباهك على مصادر الاشتعال الرئيسية: التدخين واللهب والمحركات العاملة والكهرباء الساكنة.","ساحة المضخات نظيفة، من دون خِرَق أو كرتون أو مواد أخرى قابلة للاشتعال قرب المضخات."]},{heading:"2. الكهرباء الساكنة وعبوات الوقود",body:"يمكن لشرارة كهرباء ساكنة عند فوهة المضخة (nozzle) أن تشعل أبخرة الوقود:",points:["يُفضَّل أن يبقى الزبائن خارج المركبة في أثناء التعبئة: فالانزلاق على المقعد يولّد كهرباء ساكنة. وإذا اضطروا إلى العودة إلى المركبة، يلمسون جزءًا معدنيًا من السيارة بعيدًا عن فتحة التعبئة قبل أن يلمسوا الفوهة مرة أخرى.","لا تملأ عبوة الوقود إلا وهي على الأرض، ولا تملأها أبدًا داخل صندوق السيارة أو على مقعد أو في حوض شاحنة صغيرة (بيك أب).","المس العبوة بفوهة المضخة قبل فتحها، وأبقِ الفوهة ملامسة لفتحة العبوة طوال التعبئة.","لا تملأ إلا عبوات وقود مناسبة ومعتمدة، ولا تملأ أبدًا القناني أو الدلاء أو أوعية الطعام؛ وتحدد الجهة المانحة للترخيص العبوات والأحجام المسموح بها.","أغلق العبوة بإحكام؛ ولا تُنقل عبوات الوقود وأسطوانات الغاز أبدًا في مقصورة الركاب."]},{heading:"3. انسكاب الوقود",body:"يستطيع العاملون المدرَّبون التعامل مع انسكاب صغير، كالذي يحدث عند الإفراط في التعبئة؛ أما الانسكاب الكبير فحالة طوارئ:",points:["1. أوقف التدفق: اترك مقبض الفوهة أو أوقف المضخة؛ وإن لم يتوقف، فاضغط زر الإيقاف الطارئ.","2. أبعِد الناس والمركبات؛ ولا يشغّل أحد بالقرب محركًا أو يدخّن أو يشغّل أي جهاز كهربائي.","3. مع ارتداء القفازات، غطِّ الانسكاب بالرمل أو بمادة ماصّة (absorbent) من عُدّة الانسكاب؛ ولا تمشِ في الوقود.","4. لا تغسل الوقود بالماء: فالماء يحمله إلى مجاري الصرف، حيث تتجمع الأبخرة ويمكن أن تنفجر.","5. اجمع المادة المشبعة بالوقود في وعاء معدني مغلق: فهي ما زالت قابلة للاشتعال.","اتصل بالرقم 115 فورًا إذا وصل الوقود إلى مجرى صرف أو إلى الشارع، أو شُمّت رائحة الوقود داخل مبنى، أو كان الانسكاب كبيرًا، أو اشتعل."]},{heading:"4. زر الإيقاف الطارئ",body:"يقطع زر الإيقاف الطارئ (Emergency Stop) الكهرباء عن جميع المضخات دفعة واحدة. ويحدد الدفاع المدني والجهة المانحة للترخيص مكان تركيبه ومواعيد اختباره:",points:["يعرف كل عامل مكان كل زر إيقاف طارئ، في الداخل عند صندوق الدفع وفي الخارج في ساحة المضخات، وقد تدرّب على الضغط عليه.","اضغطه عند أي انسكاب لا تستطيع إيقافه، وأي حريق، وأي تسرّب عند نقطة تعبئة الغاز المسال، وأي مركبة تصطدم بمضخة.","أبقِه ظاهرًا وموسومًا بوضوح، ولا تحجبه أبدًا بالبضائع أو رفوف العرض أو السيارات المتوقفة.","تتضمن خطة الطوارئ في المحطة مخططًا للموقع يبيّن الخزانات والمضخات وأزرار الإيقاف الطارئ والمطافئ وعُدّة الانسكاب ونقطة التجمع.","يعرف كل عامل العنوان الدقيق للمحطة وكيف يصف موقعها عند الاتصال بالرقم 115."]},{heading:"5. تعبئة غاز البترول المسال للسيارات (LPG)",body:"يُخزَّن غاز البترول المسال سائلًا تحت الضغط. وعند تسرّبه يكوّن سحابة غاز أثقل من الهواء يمكن أن تشتعل بعيدًا عن مكان التسرّب. وفي الملف المرجعي للمشروع تُصنَّف حرائق هذا الغاز ضمن الفئة B في نظام NFPA (الغازات)، وضمن الفئة C في نظام EN 2.",points:["لا يعبّئ الغاز المسال إلا عاملون مدرَّبون؛ ولا يعبّئه الزبائن بأنفسهم ما لم تسمح الجهة المانحة للترخيص بذلك.","يبقى العامل عند المركبة طوال التعبئة، حتى يُطفأ الجهاز وتُغلق الصمامات.","المحركات مطفأة، ولا أحد يدخّن أو يستخدم لهبًا قرب نقطة التعبئة.","ارتدِ القفازات وواقي العينين: فالغاز المسال السائل يسبّب حروقًا باردة في الجلد.","افحص صمام التعبئة في المركبة قبل التوصيل؛ وإذا تسرّب الغاز من الوصلة فأوقف التعبئة.","إذا استمر تسرّب الغاز أو اشتعل: اضغط زر الإيقاف الطارئ، وأبعِد الناس، واتصل بالرقم 115. لا تغلق مصدر الغاز إلا إذا أمكن الوصول إليه بأمان؛ ولا تطفئ أبدًا لهب غاز لا يمكن إيقاف مصدره."]},{heading:"6. حريق عند المضخة",body:"إذا اشتعلت مركبة أو مضخة:",points:["اضغط زر الإيقاف الطارئ فورًا وأطلق إنذار الحريق.","اطلب من السائق أن يترك الفوهة في السيارة ويبتعد؛ وأخرِج الجميع من المركبات وأبعِدهم عن المضخات.","اتصل بالرقم 115 (وبالرقم 122 إذا أصيب أحد)، واذكر اسم المحطة وعنوانها أولًا.","أبقِ الجميع على بُعد 30 مترًا (100 قدم) على الأقل من المركبة المشتعلة، وامنع دخول مركبات أخرى إلى المحطة.","لا تفتح غطاء المحرك أو صندوق السيارة المشتعلة: فالهواء النقي يزيد الحريق.","يجوز لعامل مدرَّب استخدام المطفأة على حريق صغير بدأ للتو فقط، بمطفأة يغطي ملصقها الوقود المشتعل (الفئة B؛ NFPA B للسوائل = EN B)، وطريق الخروج خلفه، وبعد إطلاق الإنذار. ابدأ من المسافة المكتوبة على الملصق؛ وإذا لم ينطفئ الحريق فورًا، فابتعد.","تدرّبوا على هذه الخطوات في تمارين منتظمة مع جميع العاملين، وسجّلوا كل تمرين."],critical:!0}],media:[{kind:"image",src:"media/images/w8_fuel_station_safety.webp",title:"التعبئة الآمنة عند المضخة",description:"المحرك مطفأ، والعبوة على الأرض، وزر الإيقاف الطارئ والمطفأة جاهزان"}],quiz:[{question:"عاد زبون إلى سيارته في أثناء التعبئة، وهو الآن يعود إلى المضخة. ماذا يفعل قبل أن يلمس الفوهة؟",options:[{text:"يلمس معدن السيارة بيده، بعيدًا عن فتحة التعبئة",correct:!0},{text:"يمسح مقبض الفوهة بقطعة قماش جافة أولًا",correct:!1},{text:"يسحب الفوهة بسرعة ثم يعيد تشغيل المضخة",correct:!1},{text:"يبقى داخل السيارة حتى تتوقف المضخة وحدها",correct:!1}],explanation:"الانزلاق على المقعد يولّد كهرباء ساكنة، ولمس المعدن بعيدًا عن فتحة التعبئة يفرّغها قبل أن تصل اليد إلى الفوهة، حيث قد تشعل الشرارة الأبخرة."},{question:"يتدفق الوقود على أرض المحطة من فوهة لا تُغلق. ما أول إجراء؟",options:[{text:"اغسل الوقود بالماء نحو مجاري الصرف",correct:!1},{text:"أوقف التدفق من المضخة أو بزر الإيقاف الطارئ",correct:!0},{text:"شغّل السيارة وأبعِدها عن الانسكاب",correct:!1},{text:"انثر مادة ماصّة حوله واترك المضخة تعمل",correct:!1}],explanation:"أوقف المصدر أولًا، ثم أبعِد مصادر الاشتعال والناس، وسيطر على الانسكاب بمادة ماصّة. فالماء يحمل الوقود إلى المجاري حيث تتجمع الأبخرة، وتشغيل محرك قد يشعلها."},{question:"أين يجب أن تكون عبوة الوقود في أثناء تعبئتها؟",options:[{text:"في حوض شاحنة بيك أب، جاهزة للانطلاق",correct:!1},{text:"على المقعد الخلفي، يمسكها أحد الركاب",correct:!1},{text:"على الأرض، والفوهة ملامسة للعبوة",correct:!0},{text:"في صندوق السيارة، وغطاؤه مفتوح بالكامل",correct:!1}],explanation:"داخل المركبة يعزل السجاد أو بطانة الحوض البلاستيكية العبوة عن الأرض، فلا تتسرب الكهرباء الساكنة الناتجة عن تدفق الوقود، وقد تحدث شرارة عند الفوهة (NIOSH). أما على الأرض ومع ملامسة الفوهة فتتسرب الشحنة إلى الأرض بأمان."},{question:"في أثناء تعبئة الغاز المسال بدأ الغاز يتسرب من الوصلة. ماذا يفعل العامل؟",options:[{text:"يوقف التعبئة ويغلق الصمامات ويُبعد الناس والمحركات",correct:!0},{text:"يُنهي التعبئة بسرعة ثم يشدّ الوصلة بعد ذلك",correct:!1},{text:"يرشّ التسرّب بمطفأة CO₂ لتبريد الوصلة",correct:!1},{text:"يطلب من السائق تشغيل المحرك والمغادرة فورًا",correct:!1}],explanation:"الغاز المسال المتسرّب يكوّن سحابة يمكن أن تشتعل. أوقف التعبئة، وأغلق الغاز إذا أمكن الوصول إليه بأمان، وأبعِد مصادر الاشتعال؛ وإذا لم يتوقف التسرّب فاضغط زر الإيقاف الطارئ واتصل بالرقم 115."},{question:"اشتعلت سيارة عند إحدى المضخات. أي إجراء صحيح؟",options:[{text:"اسحب الفوهة من السيارة قبل أي شيء آخر",correct:!1},{text:"افتح غطاء المحرك لترى الحريق وتصل إليه",correct:!1},{text:"رشّ الماء بالخرطوم على الوقود المشتعل",correct:!1},{text:"اضغط زر الطوارئ، وأخلِ المكان، واتصل بالرقم 115",correct:!0}],explanation:"يقطع زر الإيقاف الطارئ الوقود عن جميع المضخات. اترك الفوهة مكانها، وأبقِ غطاء المحرك مغلقًا، وأبعِد الجميع جيدًا؛ فالماء ينشر الوقود المشتعل."}]},{id:26,code:"IND-126",icon:"Package",accent:"#0f766e",title:"السلامة من الحريق في المستودعات والمخازن",subtitle:"Stacking, Clearances, Sprinklers, Battery Charging & Security",summary:"يمكن للحريق في المستودع أن يتسلق كومة البضائع حتى السقف في دقائق. تبيّن هذه الوحدة للعاملين والمشرفين والمديرين كيف يكدّسون البضائع ويخزّنونها بأمان، ويحافظون على عمل المرشّات، ويشحنون بطاريات الرافعات الشوكية، ويتعاملون مع بطاريات الليثيوم أيون والمواد الخطرة، ويحمون المبنى ليلًا.",blocks:[{body:"في البضائع المكدّسة والرفوف العالية ينتشر اللهب بسرعة إلى أعلى الكومة ثم جانبيًا إلى جميع المستويات؛ وفي اختبارات على صناديق مخزّنة على رفوف بارتفاع 10 أمتار، وصل الحريق مرارًا إلى قمة الرفوف خلال دقيقتين (دليل الحكومة البريطانية للسلامة من الحريق في المصانع والمستودعات). ويتوقف الحِمل الحراري (Fire Load) للمستودع على ما يُخزَّن فيه، وكثيرًا ما يكون أعلى منه في المنازل والمكاتب. والقواعد الآتية ممارسات جيدة عامة؛ وعلى كل مبنى أن يستوفي أولًا متطلبات الدفاع المدني والجهة المانحة للترخيص."},{heading:"1. التكديس والمسافات الخالية",body:"يجب أن تكون البضائع المخزّنة مستقرة، وألا تعيق الناس أو المرشّات أو رجال الإطفاء:",points:["كدّس البضائع بحيث تكون مستقرة: مسنودة ومتشابكة ومحدودة الارتفاع، فلا تنزلق ولا تنهار.","لا تفرط في التخزين: لكل موقع تخزين حد أقصى مكتوب.","اترك فراغًا لا يقل عن متر واحد بين أعلى البضائع والسقف أو جسوره أو وحدات الإنارة (إرشادات HSE البريطانية).","تحت رؤوس المرشّات، حافظ على الخلوص الذي يحدده تصميم نظام المرشّات؛ والحد الأدنى العام وفق OSHA هو 45 سنتيمترًا (18 بوصة)، وبعض أنواع المرشّات تحتاج إلى أكثر.","لا تسمح أبدًا للرفوف أو البضائع بأن تحجب رؤوس المرشّات.","لا تكدّس بضائع قابلة للاشتعال على الأجهزة الكهربائية أو وحدات الإنارة أو المدافئ، حتى وهي مطفأة.","احفظ المنصّات الخشبية الفارغة ومواد التغليف والنفايات في مكان مخصّص بعيدًا عن المبنى والمخارج والنوافذ، أو في منطقة محمية بالمرشّات."]},{heading:"2. الممرات والمخارج وأبواب الحريق",body:"الطرق المفتوحة تتيح للناس الخروج ولفرق 115 الوصول إلى الحريق:",points:["أبقِ الممرات خالية من العوائق وفي حالة جيدة؛ والممرات الدائمة معلَّمة على الأرض.","لا تضع البضائع أبدًا في طرق الإخلاء أو أمام المخارج وأبواب الحريق والستائر المعدنية المقاومة للحريق (fire shutters) والمطافئ ونقاط إطلاق الإنذار.","اترك فراغًا بين البضائع والجدران الداخلية ليصل رجال الإطفاء إلى الحريق (الإرشادات البريطانية: 0.5 متر).","يجب أن تُفتح مخارج الحريق من الداخل من دون مفتاح ما دام في المبنى أحد.","لا يقود الرافعات الشوكية إلا مشغّلون مدرَّبون ومرخَّصون، ويسير المشاة في الممرات المعلَّمة."]},{heading:"3. المرشّات: حافظ على جاهزيتها",body:"تسيطر المرشّات على الحريق تلقائيًا، حتى ليلًا حين لا يوجد أحد، ولكن فقط إذا لم يعقها شيء:",points:["لا تعلّق أبدًا أي شيء على رؤوس المرشّات أو أنابيبها، ولا تطلِها أو تغطِّها أو تصدمها؛ وأبلغ فورًا عن أي رأس تالف أو يسرّب الماء.","تبقى صمامات التحكم في المرشّات مفتوحة بالكامل. ولا يجوز إغلاق أي منها إلا لشخص مخوَّل، وفق إجراء الموقع لتعطيل الحماية من الحريق، مع مراقبة حريق إضافية حتى يُعاد فتحه.","إذا وجدت صمامًا مغلقًا أو رأسًا محجوبًا، فأبلغ المشرف فورًا: فقد تكون المنطقة بلا حماية.","لا تنفتح المرشّات إلا حيث تصلها حرارة الحريق، لذلك يمكن لحريق تحت رأس محجوب أن يكبر دون أن يُرى.","يُجرى الفحص والاختبار والصيانة وفق NFPA 25 ومتطلبات الدفاع المدني؛ واحتفظ بالسجلات.","بعض المنتجات لا يجوز تخزينها أصلًا في مناطق محمية بالمرشّات؛ وتذكر ذلك صحيفة بيانات السلامة (SDS)."]},{heading:"4. شحن بطاريات الرافعات الشوكية",body:"يطلق شحن بطاريات الرصاص الحمضية (lead-acid) غاز الهيدروجين، وهو غاز شديد الاشتعال؛ وإذا تجمّع ووصلته شرارة أو لهب، فقد ينفجر:",points:["اشحن في منطقة الشحن المخصّصة فقط: منطقة جيدة التهوية (مع تهوية عالية فوق البطاريات)، بعيدة عن البضائع المخزّنة ومصادر الاشتعال.","لا تدخين ولا لهب ولا أعمال ساخنة ولا هواتف في منطقة الشحن.","أطفئ الشاحن قبل توصيل البطارية أو فصلها، لتجنب الشرر.","أبعِد الأدوات والأجسام المعدنية الأخرى عن سطح البطاريات، وانزع الساعة والخاتم والقطع المعدنية الأخرى قبل العمل عليها.","افتح غطاء البطارية في أثناء الشحن، وارتدِ معدات الوقاية الشخصية المحددة لهذه المهمة (قفازات ومريلة وواقيًا للعينين من الحمض).","بدّل أسطوانات الغاز (LPG) للرافعات العاملة بالغاز في الخارج، بعيدًا عن مصادر الاشتعال.","لا يبدّل البطاريات أو يشحنها إلا عاملون مدرَّبون."]},{heading:"5. بطاريات الليثيوم أيون",body:"يمكن لبطاريات الليثيوم أيون التالفة أو المحمومة أو المشحونة بطريقة خاطئة أن تشتعل أو تنفجر، وقد تنتقل حرارة خلية متعطلة إلى الخلية المجاورة (الانفلات الحراري thermal runaway):",points:["اتبع تعليمات الشركة المصنّعة في التخزين والاستخدام والشحن، ولا تستخدم إلا الشاحن المصنوع لتلك البطارية.","خزّن البطاريات والأجهزة في أماكن جافة وباردة بعيدًا عن المدافئ ومصادر الحرارة الأخرى، وافصلها عن الشاحن عند امتلائها.","ابحث عن علامات الخطر: الانتفاخ أو التشقق، أو الهسهسة، أو التسرّب، أو ارتفاع الحرارة، أو الدخان. وتُسحب البطارية التي تظهر عليها أي علامة منها من الاستخدام فورًا.","إذا كان لمسها آمنًا، فانقلها إلى المكان المخصّص بعيدًا عن المواد القابلة للاشتعال، مثل وعاء معدني مقاوم للحريق فيه رمل، وأرسلها للتخلص منها بالطريقة المعتمدة.","إذا كانت البطارية تُطلق دخانًا أو تحترق، فلا تحملها: نبّه الآخرين، وأطلق الإنذار، واخرج، واتصل بالرقم 115. خلايا الليثيوم أيون لا تحتوي على ليثيوم معدني، وتُبرَّد بكمية كبيرة من الماء؛ أما الحريق في البطاريات المخزّنة فمن عمل فرق 115.","قد تشتعل حرائق البطاريات من جديد بعد أن تبدو منطفئة؛ فأخبر فرق 115 بأماكن تخزين البطاريات."],critical:!0},{heading:"6. النظافة والترتيب والمواد الخطرة",body:"قلة النفايات تعني وقودًا أقل للحريق، والتخزين الصحيح يُبقي الحادث الصغير صغيرًا:",points:["أبقِ مناطق التخزين خالية من مواد التغليف المتناثرة والنفايات؛ واجمع النفايات في حاويات مناسبة وأزِلها بانتظام.","التدخين ممنوع في مناطق التخزين.","اقرأ الملصق وصحيفة بيانات السلامة (SDS) لكل منتج خطر قبل تخزينه؛ ويبيّن القسم 7 من الصحيفة شروط التخزين والمواد غير المتوافقة.","افصل المواد غير المتوافقة بعضها عن بعض: فإذا خُزّنت معًا فقد تزيد سرعة نمو الحريق أو تطلق دخانًا سامًا.","لا تُدخل العبوات التالفة أو المسرّبة إلى المخزن؛ ضعها في صينية أو حوض احتواء (bund) واتبع تعليمات المورّد.","احتفظ بسجل محدَّث للمواد الخطرة وأماكن تخزينها، في مكان يمكن منه تسليمه لفرق 115 في حالة الطوارئ."]},{heading:"7. الحماية الليلية والإنذار",body:"الحريق الذي يبدأ والمبنى مغلق قد يكبر دون أن يراه أحد، والمباني الخالية هدف للحرق العمد (arson):",points:["أنِر محيط المبنى جيدًا وأبقِ حدود الموقع مؤمَّنة؛ وأغلق الأبواب والنوافذ وفتحات السقف دون أن تسد طرق الإخلاء.","لا تضع حاويات النفايات الكبيرة ملاصقة للمبنى؛ واحفظ صناديق النفايات في حظيرة مقفلة بعيدًا عنه.","أقفل على السوائل والغازات القابلة للاشتعال حتى لا يستخدمها المتسللون.","يخضع إنذار الحريق وإنذار السرقة للمراقبة، ويستجيب أحد فورًا لكل إنذار.","يعرف الحراس كيف يطلقون الإنذار، وكيف يتصلون بالرقم 115 ويذكرون العنوان الدقيق، وكيف يستقبلون فرق 115 عند البوابة ومعهم المفاتيح ومخطط الموقع.","أبلغ عن الأشخاص الذين يتصرفون بشكل مريب وعن أي حرائق صغيرة مجهولة السبب؛ فقد تكون إنذارًا بحرق عمد.","حدّث تقييم مخاطر الحريق مرة في السنة على الأقل وبعد كل تغيير كبير فيما تخزّنه أو في طريقة تخزينه."]}],media:[{kind:"image",src:"media/images/w8_warehouse_fire_safety.webp",title:"مستودع منظم وآمن من الحريق",description:"ممرات مفتوحة، وفراغ تحت المرشّات، ومنطقة شحن منفصلة"}],quiz:[{question:"وفق إرشادات HSE البريطانية، ما الفراغ الذي يجب تركه بين أعلى البضائع المخزّنة والسقف أو الجسور أو وحدات الإنارة؟",options:[{text:"متر واحد على الأقل",correct:!0},{text:"10 سنتيمترات على الأقل",correct:!1},{text:"25 سنتيمترًا على الأقل",correct:!1},{text:"لا شيء، إذا كانت الكومة مستقرة",correct:!1}],explanation:"تطلب إرشادات HSE للمستودعات مترًا واحدًا على الأقل بين أعلى البضائع والسقف أو جسوره أو وحدات الإنارة؛ وتحت المرشّات يُطبَّق الخلوص الذي يحدده تصميم النظام (والحد الأدنى العام وفق OSHA هو 45 سنتيمترًا)."},{question:"أي ممارسة صحيحة عند شحن بطاريات الرافعات الشوكية؟",options:[{text:"الشحن بين الرفوف لتكون الرافعة جاهزة للوردية التالية",correct:!1},{text:"فصل البطارية والشاحن ما زال يعمل",correct:!1},{text:"استخدام منطقة الشحن المهوّاة بلا تدخين ولا لهب",correct:!0},{text:"وضع الأدوات المعدنية على سطح البطارية لتكون في المتناول",correct:!1}],explanation:"يطلق الشحن غاز الهيدروجين. والمنطقة المخصّصة الجيدة التهوية الخالية من مصادر الاشتعال تمنع تجمّعه واشتعاله؛ وإطفاء الشاحن قبل الفصل وإبعاد الأدوات المعدنية عن البطارية يمنعان الشرر."},{question:"في أثناء جرد البضائع وجدت صمام تحكم في المرشّات مغلقًا. ماذا تفعل؟",options:[{text:"أبلّغ المشرف فورًا ليُعاد فتحه بأمان",correct:!0},{text:"أتركه مغلقًا، فإنذار الحريق سينبّه إلى أي حريق",correct:!1},{text:"أفتحه إلى المنتصف ليبقى ضغط الماء منخفضًا",correct:!1},{text:"أعلّق عليه ورقة وأفحصه في تفتيش الشهر القادم",correct:!1}],explanation:"صمام التحكم المغلق قد يترك منطقة كاملة بلا حماية بالمرشّات. يجب الإبلاغ عنه فورًا، ويعيد فتحه شخص مخوَّل وفق إجراء الموقع."},{question:"بطارية ليثيوم أيون مخزّنة منتفخة وتسخن. ما الإجراء الصحيح؟",options:[{text:"اسحبها من الاستخدام؛ وإن أطلقت دخانًا فأطلق الإنذار واتصل بالرقم 115",correct:!0},{text:"أعدها إلى الشحن لتتوازن خلاياها وتبرد",correct:!1},{text:"لفّها بالكرتون واتركها على الرف حتى تُنقل",correct:!1},{text:"رشّها مرة بثاني أكسيد الكربون CO₂ وأعدها إلى الرف",correct:!1}],explanation:"الانتفاخ والسخونة علامتا تعطّل البطارية. اسحبها من الاستخدام، وإذا كان لمسها آمنًا فاعزلها بعيدًا عن المواد القابلة للاشتعال؛ وإن أطلقت دخانًا أو احترقت فلا تلمسها: أطلق الإنذار، واخرج، واتصل بالرقم 115."},{question:"أي إجراء يحمي المستودع المغلق من الحرق العمد على أفضل وجه؟",options:[{text:"حاويات نفايات كبيرة ملاصقة للجدار ليراها الحارس",correct:!1},{text:"إطفاء الإنذار ليلًا لتجنب الإنذارات الكاذبة",correct:!1},{text:"النفايات بعيدة عن المبنى وإنذار خاضع للمراقبة",correct:!0},{text:"ترك السوائل القابلة للاشتعال قرب الباب لتسليمها صباحًا",correct:!1}],explanation:"كثيرًا ما يستخدم مرتكبو الحرق العمد النفايات والسوائل القابلة للاشتعال الموجودة في الموقع. وإبعاد حاويات النفايات عن المبنى، والإقفال على المواد القابلة للاشتعال، ووجود إنذارات مراقَبة يُستجاب لها، كلها تقلل الخطر (دليل الحكومة البريطانية)."}]},{id:27,code:"IND-127",icon:"HardHat",accent:"#ca8a04",title:"السلامة في مواقع البناء",subtitle:"Fire Plan, Hot Work, Temporary Electrics, Cylinders, Excavations & UXO",summary:"كثيرًا ما تفتقر المباني قيد الإنشاء إلى مرشّات أو إنذارات حريق عاملة، مع أنها مليئة بمصادر الاشتعال والمواد القابلة للاحتراق. تبيّن هذه الوحدة للعمال والمشرفين والمديرين كيف يخططون لمواجهة الحريق؛ ويسيطرون على الأعمال الساخنة والكهرباء المؤقتة وأسطوانات الوقود والغاز؛ ويتعرفون على الخطر عند السقالات والحفريات؛ ويقدّمون الإسعافات الأولية؛ وماذا يفعلون عند العثور على جسم مشبوه في أثناء الحفر.",blocks:[{body:"بحسب NFPA، فإن الأسباب الرئيسية للحرائق في المباني قيد الإنشاء هي معدات الطهي، ومعدات توزيع الكهرباء والإنارة، ومعدات التدفئة. وقد لا تكون المرشّات وكواشف الدخان وإنذارات الحريق عاملة بعد، كما تجذب المواقع المفتوحة المتسللين ومرتكبي الحرق العمد. ويضع الدفاع المدني والجهة المانحة للترخيص قواعد مواقع البناء وتصاريحها ورخصها: التزم بمتطلباتهما. وتقدّم هذه الوحدة القواعد الأساسية لكل من في الموقع."},{heading:"1. خطة الحريق في الموقع ونقطة التجمع",body:"قبل بدء العمل، يُعدّ المقاول الرئيسي المسيطر على الموقع خطة الحريق:",points:["تقييم لمخاطر الحريق وخطة طوارئ مكتوبة، جاهزان قبل بدء العمل ويُحدَّثان مع ارتفاع المبنى.","شخص مسمّى يدير الوقاية من الحريق في الموقع (في NFPA 241: مدير برنامج الوقاية من الحريق).","طرق إخلاء من كل منطقة عمل، مفتوحة وموسومة، ولا تُقفل أبدًا ما دام في الموقع أحد؛ ومساران في اتجاهين مختلفين حيثما أمكن.","إنذار حريق يسمعه الجميع فوق ضجيج الموقع، ولافتات تعليمات الحريق عند نقاط الحريق ومداخل الموقع وأماكن تناول الطعام.","نقاط حريق فيها مطافئ مناسبة، وأشخاص معيَّنون مدرَّبون على استخدامها.","نقطة تجمع يُحصى فيها الجميع، بالعدّ أو بتفقد المنطقة.","تمارين إخلاء لاختبار الخطة والتدريب؛ ويتعرّف كل عامل جديد وكل زائر على الخطة عند التعريف الأولي بالموقع."]},{heading:"2. الأعمال الساخنة: التصريح ومراقبة الحريق",body:"يتسبب اللحام والقطع والجلخ (grinding) والعمل باللهب في كثير من حرائق مواقع البناء. استخدم طريقة أخرى إن كانت تؤدي الغرض؛ وإلا:",points:["لا تعمل إلا بتصريح العمل الساخن (Hot Work Permit) الصادر عن الشخص المخوَّل بالموافقة عليه.","أزِل المواد القابلة للاحتراق ضمن 11 مترًا (35 قدمًا) من العمل، أو احمِها ببطانيات أو ستائر مقاومة للحريق، أو انقل العمل إلى مكان آمن.","جهّز مطفأة مناسبة في مكان العمل.","يبقى مراقب الحريق (Fire Watch) في أثناء العمل وفي فترات الاستراحة، ولمدة ساعة واحدة على الأقل بعد انتهاء العمل؛ ويجوز للمسؤول عن التصريح أن يطلب مراقبة أطول (NFPA 51B).","خطّط لإنهاء العمل الساخن قبل نهاية يوم العمل بوقت كافٍ لإجراء الفحوص قبل إغلاق الموقع (HSE البريطانية: قبل ساعتين)."]},{heading:"3. الكهرباء المؤقتة",body:"تسبب أسلاك الكهرباء المؤقتة في الموقع حرائق وصعقات كهربائية عندما تُحمَّل فوق طاقتها أو تتلف أو يعدّلها أشخاص غير مؤهلين:",points:["لا يصمّم التمديدات المؤقتة أو يركّبها أو يعدّلها أو يفحصها إلا كهربائي مؤهل؛ ولا يضيف إليها أحد غيره شيئًا أو يغيّرها.","تُحمى المقابس التي يستخدمها العمال بجهاز حماية من تيار التسرّب (RCD)، يقطع الكهرباء بسرعة عند تسرّب التيار إلى الأرض؛ اضغط زر اختباره بانتظام. ويقلل هذا الجهاز الخطر لكنه لا يغني عن تمديدات سليمة.","لا تُحمّل المقابس والمشتركات متعددة المخارج فوق طاقتها، ولا توصل أسلاك التمديد بعضها ببعض، وافرد بكرات الأسلاك بالكامل قبل الاستخدام.","استخدم كابلًا مرنًا مناسبًا لأسلاك التمديد، مرفوعًا عن الأرض؛ واسحب الأسلاك والأدوات التالفة من الاستخدام بدلًا من لفّها بالشريط العازل.","لا تمدّ الكابلات المؤقتة أو لوحات توزيع الكهرباء في طرق الإخلاء، وأبعِد النفايات عن لوحات التوزيع."]},{heading:"4. الوقود وأسطوانات الغاز في الموقع",body:"يُدخل الوقود والغاز المسال (LPG) والأسيتيلين والأكسجين كمية كبيرة من الطاقة المخزّنة إلى الموقع:",points:["لا تُبقِ في الموقع إلا أقل كمية لازمة، في مخزن مؤمَّن وجيد التهوية بعيدًا عن المواد القابلة للاحتراق ومناطق العمل، ولا تخزّنها أبدًا داخل المبنى قيد الإنشاء.","لا تستخدم للوقود إلا عبوات معتمدة، ولا تخزّن الوقود أبدًا في المخارج أو السلالم أو الممرات.","زوّد الآليات بالوقود في مكان مخصّص، والمحركات مطفأة، ومن دون تدخين، ومع مطفأة قريبة.","أبقِ أسطوانات الغاز قائمة ومثبتة حتى لا تسقط، مع أغطية الصمامات عندما لا تُستخدم، وبعيدة عن الشرر وخَبَث اللحام الساخن واللهب.","خزّن أسطوانات الأكسجين منفصلة عن أسطوانات الغاز القابل للاشتعال: بينهما 6 أمتار (20 قدمًا) على الأقل، أو خلف حاجز مقاوم للحريق (OSHA).","أقفل على الوقود والأسطوانات في نهاية اليوم حتى لا يستخدمها المتسللون.","إذا تسرّب الغاز من أسطوانة أو اشتعل: لا تغلق الصمام إلا إذا أمكن الوصول إليه بأمان؛ ولا تطفئ أبدًا لهب غاز لا يمكن إيقافه؛ وأبعِد الجميع واتصل بالرقم 115."]},{heading:"5. السقالات والحفريات: تعرّف على الخطر وتوقف",body:"يقتل السقوط من المرتفعات وانهيار الخنادق عمال البناء. وتصميم السقالات ودعامات الخنادق عمل المختصين الأكفاء؛ أما كل من في الموقع فعليه أن يتعرّف على الخطر ويتوقف:",points:["لا تستخدم السقالة إلا بعد أن يفحصها شخص كفء قبل الوردية؛ ولا تستخدم أبدًا سقالة تالفة أو ناقصة أو بلا حواجز حماية، ولا تعدّلها بنفسك أبدًا.","يحتاج العمل على ارتفاع 1.8 متر (6 أقدام) أو أكثر فوق مستوى أدنى، أو قرب حافة مفتوحة أو فتحة، إلى حماية من السقوط: حواجز حماية أو أغطية أو حزام أمان كامل مربوط بنقطة تثبيت متينة.","لا تدخل أبدًا خندقًا غير محمي. ووفق OSHA تحتاج الحفريات التي يبلغ عمقها 1.5 متر (5 أقدام) أو أكثر إلى نظام حماية مصمَّم للموقع، ما لم تكن محفورة في صخر ثابت.","أبعِد أكوام التراب والمواد والآليات 0.6 متر (قدمين) على الأقل عن الحافة.","يفحص شخص كفء الحفريات كل يوم وبعد المطر.","عند ظهور علامات الانهيار (تشققات في الأرض، أو انتفاخ الجدران، أو تسرّب الماء إلى الداخل، أو تساقط التراب): اخرج فورًا، وامنع الآخرين من الدخول، وأبلغ المشرف؛ ولا يُستأنف العمل إلا بعد السيطرة على الخطر."]},{heading:"6. وصول فرق 115 والإسعافات الأولية",body:"في الحريق أو الإصابة، كل دقيقة مهمة:",points:["أبقِ مدخل الموقع وبواباته وطرق الوصول إليه مفتوحة لسيارات الإطفاء التابعة للرقم 115 وسيارات الإسعاف؛ ولا تركن عليها ولا تضع فيها مواد.","أبقِ حنفيات الحريق ونقاط المياه ومعدات الإطفاء ظاهرة وسهلة الوصول.","تتواصل المواقع الكبيرة مع الدفاع المدني قبل بدء العمل وكلما تغيّرت طرق الوصول أو المخاطر، وتُبقي ملف معلومات (مخطط الموقع، والمخاطر، والوقود والغاز والبطاريات المخزّنة) جاهزًا لفرق 115.","يوجد في الموقع شخص مدرَّب على الإسعافات الأولية وحقيبة إسعافات أولية مجهّزة.","علّق عنوان الموقع وإرشادات الوصول إليه والرقمين 115 و122 قرب الهواتف وفي مكتب الموقع وعند المدخل.","بعد السقوط من مرتفع، لا تحرّك المصاب إلا إذا كان المكان غير آمن أو احتاج إلى الإنعاش القلبي الرئوي (CPR)؛ واتصل بالرقم 122."]},{heading:"7. جسم مشبوه في أثناء الحفر",body:"قد يُعثر على ذخائر قديمة غير منفجرة في أثناء الحفر، حتى في أماكن تُعدّ آمنة، وقد تنفجر إذا حُرّكت أو صُدمت. إذا كشفت آلة أو عامل أو أداة جسمًا مشبوهًا:",points:["أوقف الآلة والعمل فورًا.","لا تلمس الجسم أبدًا، ولا تحرّكه أو ترفعه أو تحفر حوله أو تسحبه، ولا تضعه أبدًا في دلو الآلة أو في مركبة.","أخلِ المنطقة من الجميع، وامنع الناس والآليات من دخولها.","ابتعد كثيرًا (50 مترًا على الأقل، وفق UNMAS) قبل استخدام الهاتف أو جهاز اللاسلكي، ثم اتصل بالرقم 115 واتبع تعليمات الدفاع المدني.","من مكان آمن، تذكّر موضع الجسم وأخبر به فرق 115؛ ولا يُستأنف العمل إلا عندما تعلن الجهات المختصة أن الموقع آمن."],critical:!0}],media:[{kind:"image",src:"media/images/w8_construction_site_fire_safety.webp",title:"موقع بناء مستعد لمواجهة الحريق",description:"تصريح عمل ساخن مع مراقب حريق، وأسطوانات مثبتة، وطريق وصول مفتوح"}],quiz:[{question:"وفق NFPA 51B، كم يجب أن يبقى مراقب الحريق بعد انتهاء العمل الساخن؟",options:[{text:"ساعة واحدة على الأقل، أو أكثر إذا طلب التصريح ذلك",correct:!0},{text:"حتى يجمع اللحّام أدواته ويغادر الموقع",correct:!1},{text:"نحو 10 دقائق، إذا لم يُرَ دخان حتى ذلك الوقت",correct:!1},{text:"لا حاجة إلى مراقبة ما دامت هناك مطفأة قريبة",correct:!1}],explanation:"قد يبقى الشرر في أماكن خفية ويُشعل حريقًا لاحقًا. ويشترط NFPA 51B بقاء مراقب الحريق ساعة واحدة على الأقل بعد العمل، ويجوز للمسؤول عن التصريح أن يطلب مراقبة أطول."},{question:"تلف العازل في سلك تمديد في الموقع. ماذا يجب أن يُفعل؟",options:[{text:"يُسحب من الاستخدام ويستبدله شخص مؤهل",correct:!0},{text:"يُلفّ الجزء التالف بالشريط العازل ويستمر العمل",correct:!1},{text:"يوصَل بسلك آخر ليحمل كل منهما تيارًا أقل",correct:!1},{text:"يُستخدم للأدوات اليدوية الصغيرة فقط حتى ينتهي العمل",correct:!1}],explanation:"الأسلاك التالفة تسبب الصعق والحرائق. تُسحب من الاستخدام ويستبدلها أو يصلحها شخص كفء إصلاحًا صحيحًا، ولا تُلفّ بالشريط أبدًا (HSE البريطانية)؛ وجهاز RCD يقلل الخطر لكنه لا يجعل السلك التالف آمنًا."},{question:"ظهرت تشققات في الأرض وبدأ التراب يتساقط في خندق يعمل فيه زميل. ما التصرف الصحيح؟",options:[{text:"أخرِج الجميع، وامنع الدخول، وأبلغ المشرف",correct:!0},{text:"أكمِل الجزء المتبقي بسرعة قبل أن يتحرك الجدار",correct:!1},{text:"انزل وادعم الجدار بألواح خشبية إضافية",correct:!1},{text:"أوقف الحفّارة على الحافة ليثبّت وزنها التراب",correct:!1}],explanation:"التشققات وتساقط التراب علامات انهيار. يخرج العمال فورًا ويبقون خارج الخندق حتى يجعله شخص كفء آمنًا؛ والآلة الثقيلة على الحافة تزيد احتمال الانهيار."},{question:"كشفت حفّارة جسمًا صدئًا يشبه قذيفة. ما الإجراء الصحيح؟",options:[{text:"ارفعه بلطف بدلو الحفّارة وضعه جانبًا",correct:!1},{text:"أزِل التراب عنه لتتأكد مما إذا كان حقيقيًا",correct:!1},{text:"أوقف العمل، وأخلِ المنطقة، واتصل بالرقم 115 من مكان بعيد",correct:!0},{text:"انقله إلى مكتب الموقع حتى تصل الشرطة",correct:!1}],explanation:"قد تنفجر الذخائر عند تحريكها أو صدمها. توقف فورًا، وأبعِد الجميع، ولا تحرّكها أبدًا، واتصل بالرقم 115 من مكان بعيد، وتجنّب استخدام الهاتف أو اللاسلكي قرب الجسم (UNMAS)."},{question:"أي ترتيب صحيح لأسطوانات الغاز في موقع البناء؟",options:[{text:"ممددة على جنبها حتى لا تسقط",correct:!1},{text:"على السلالم، لأنها أبرد مكان في الموقع",correct:!1},{text:"الأكسجين والأسيتيلين مربوطان معًا بسلسلة في مخزن واحد",correct:!1},{text:"قائمة ومثبتة، والأغطية عليها، وبعيدة عن الشرر والحرارة",correct:!0}],explanation:"تُحفظ الأسطوانات قائمة ومثبتة مع أغطية الصمامات، بعيدًا عن الشرر والحرارة، ويُفصل الأكسجين عن الغاز القابل للاشتعال (OSHA 1926.350). والسلالم طرق إخلاء يجب أن تبقى خالية من الوقود والأسطوانات."}]},{id:28,code:"BUS-128",icon:"FireExtinguisher",accent:"#b91c1c",title:"بطانية الحريق والمطافئ ذات العجلات ومطافئ المركبات",subtitle:"متى تُستخدم وكيف بأمان، ولماذا تحتاج حرائق بطاريات الليثيوم أيون إلى عناية خاصة",summary:"إلى جانب المطافئ اليدوية، تستخدم أماكن العمل بطانيات الحريق والمطافئ الكبيرة ذات العجلات ومطافئ المركبات، ولكلٍّ منها حدوده. يشرح هذا الدرس متى تُستخدم وكيف بأمان، وماذا تفعل عندما ترتفع حرارة بطارية ليثيوم أيون بشدة أو تشتعل.",blocks:[{body:`لكل معدة إطفاء وظيفة وحدود. ويُطبَّق فحص «نعم أو لا» نفسه عليها جميعًا: الحريق صغير وفي بدايته، والمعدة مناسبة له، والمخرج خلفك، وأُطلق الإنذار واتُّصل بالرقم 115، وأنت مدرَّب. وإذا كانت أي إجابة «لا» فاخرج. ولم يُؤكَّد بعدُ أيّ معيار للمطافئ يُطبَّق في دهوك (NFPA 10 أو EN 3)، ولا من يحق له صيانة المطافئ؛ فاتبع متطلبات الدفاع المدني والجهة المانحة للترخيص.

تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.`},{heading:"1. بطانية الحريق: حريق مقلاة صغير",body:"بطانية الحريق قطعة من قماش مقاوم للنار في عبوة سريعة الفتح، تُخمد الحريق الصغير في المقلاة أو القدر بقطع الهواء عنه:",points:["احفظها قرب باب المطبخ، لا بجوار الموقد، لتصل إليها وتبقى قادرًا على الخروج.","اسحب الشريطين (tabs) إلى الأسفل بقوة لتخرج البطانية.","أمسكها أمامك ولفّ حوافها على يديك لتحمي يديك ووجهك.","ضعها برفق فوق المقلاة ولا ترمِها، وتأكّد من أنها تغطي المقلاة كلها.","أطفئ مصدر الحرارة فقط إذا استطعت الوصول إلى مفتاحه بأمان.","اترك البطانية في مكانها ولا تحرّك المقلاة، ولا ترفع البطانية لترى إن انطفأت النار حتى يبرد كل شيء تمامًا.","اتصل بالرقم 115 حتى لو بدت النار منطفئة؛ وإذا لم تنطفئ فورًا فاخرج وأغلق الباب. ولا تصبّ الماء أبدًا على الزيت المشتعل."]},{heading:"2. بطانية الحريق: اشتعال الملابس",body:"إذا اشتعلت النار في ملابس شخص:",points:["يتوقّف الشخص، وينبطح على الأرض، ويغطّي وجهه بيديه، ويتدحرج حتى تنطفئ النار.","إذا كانت لديك بطانية حريق، فلفّها حول اللهب وحول الشخص، وساعده على الانبطاح والتدحرج.","احمِ يديك بحواف البطانية.","ثم برّد الحرق بالماء البارد الجاري لمدة 20 دقيقة، ولا تفقأ الفقاعات، واتصل بالرقم 122.","تُستخدم بطانية الحريق مرة واحدة ثم تُستبدل. اشترِ بطانية يبيّن ملصقها المعيار الذي تطابقه، مثل EN 1869؛ فالبطانية التي لا تحمل علامة معيار قد لا تعمل. ولم يُؤكَّد بعدُ المعيار المقبول محليًّا."]},{heading:"3. المطافئ ذات العجلات",body:"تحمل المطافئ ذات العجلات كمية من المادة أكبر بكثير من المطفأة اليدوية، على عربة بخرطوم طويل، وتحمي أماكن مثل مخازن الوقود وورش الصيانة ومناطق التحميل:",points:["لا يستخدمها إلا العاملون المدرَّبون على هذا الطراز تحديدًا: فأدوات التحكم وترتيب الخطوات والمدى تختلف من طراز لآخر، فاتبع الملصق.","اعملوا في ثنائي كلما أمكن: يتحكم أحدكما بالعربة والصمام كما يبيّن الملصق، ويمسك الآخر الخرطوم والفوهة. وبعض الطرازات مصمَّمة ليشغّلها شخص واحد مدرَّب.","انقل الوحدة إلى موضع ضمن المدى المذكور على الملصق والمخرج خلفك، واتبع خطوات الملصق بالترتيب.","فحص «نعم أو لا» هو نفسه: المطفأة ذات العجلات لا تجعل مكافحة حريق كبير أمرًا آمنًا.","بعد أي استخدام، يعيد فنّي مؤهَّل تعبئتها."]},{heading:"4. مطافئ المركبات",body:"كثيرًا ما تحمل الشاحنات والرافعات الشوكية والحافلات وسيارات الشركات مطفأة صغيرة، لكن معظم حرائق المركبات ليست مما يكافحه السائق:",points:["توقّف على جانب الطريق حالما يكون ذلك آمنًا، وأطفئ المحرّك، وأخرِج الجميع، وابتعدوا كثيرًا عن المركبة وعن حركة السير، 30 مترًا (100 قدم) على الأقل.","اتصل بالرقم 115 (وبالرقم 122 إن أُصيب أحد)، ونبّه حركة السير؛ ولا تعد أبدًا لأخذ أغراضك.","لا تفتح أبدًا غطاء المحرّك أو صندوق السيارة إن ظننت أن النار في داخلهما: فالهواء الجديد يزيد النار اشتعالًا.","لا تستخدم مطفأة المركبة إلا على حريق صغير في بدايته، وإذا كنت مدرَّبًا، وقد خرج الجميع، وطريق تراجعك مفتوح. وفي حريق حجرة المحرّك أبقِ الغطاء مغلقًا؛ وتنصح بعض أجهزة الإطفاء بالتصويب عبر الشبكة الأمامية (grille) أو الفتحة عند حافة الغطاء.","إذا ساورك الشك فلا تقترب من النار. ولا تصبّ الماء أبدًا على حريق المحرّك.","الرافعات الشوكية والمركبات الأخرى العاملة بالبطاريات: إذا كانت البطارية مشتعلة فتعامل معها كحريق بطارية (القسم 5)."]},{heading:"5. حرائق بطاريات الليثيوم أيون",body:"توجد بطاريات الليثيوم أيون في الهواتف والحواسيب المحمولة والعُدد الكهربائية والدراجات الكهربائية والرافعات الشوكية وأنظمة تخزين الطاقة. وعندما تتضرّر أو تُشحن أكثر من اللازم أو يكون فيها عيب، قد تسخن بشدة أو تطلق غازًا سامًّا أو تشتعل أو تنفجر:",points:["علامات الخطر: رائحة غريبة، أو سخونة، أو انتفاخ أو تغيّر في الشكل أو اللون، أو أصوات فرقعة، أو دخان. أوقف استخدامها أو شحنها فورًا.","إن كان ذلك آمنًا، افصلها عن الكهرباء وأبعدها عن كل ما يمكن أن يحترق.","إذا اشتعلت: أخرِج الجميع، وأغلق الباب، واتصل بالرقم 115 من الخارج، وقل إنه حريق بطارية.","لا تستنشق الدخان: فالبطارية المتضرّرة قد تطلق غازًا سامًّا لا يُرى.","التبريد بكمية كبيرة من الماء هو الطريقة الموصى بها، لكن لا يقوم به إلا المدرَّبون بالمعدات المناسبة؛ ومسحوق ABC العادي وCO₂ لا يوقفان النار تمامًا.","بطاريات الليثيوم أيون ليست من الفئة D: فمواد الفئة D مخصّصة لبطاريات الليثيوم المعدني وللمعادن المشتعلة فقط.","الوقاية: استخدم شاحن الشركة المصنّعة أو شاحنًا توافق عليه فقط، واشحن على سطح صلب بعيدًا عمّا يحترق وعن المخارج، وأخرِج البطاريات المتضرّرة من الاستخدام."],critical:!0},{heading:"6. الفحص والصيانة",body:"أبقِ كل هذه المعدات جاهزة:",points:["في الفحص البصري الدوري افحص بطانيات الحريق أيضًا: في مكانها، وسهلة الوصول، وعبوتها سليمة، وشريطاها متدلّيان بحرية.","تخضع المطافئ ذات العجلات ومطافئ المركبات للفحص البصري نفسه الذي تخضع له المطافئ الأخرى: في مكانها، والمسمار والختم سليمان، ومقياس الضغط في المنطقة الخضراء إن وُجد، ولا ضرر فيها.","إعادة التعبئة بعد أي استخدام؛ ويتولى فنّي مؤهَّل الصيانة السنوية واختبارات الضغط. ولم تُؤكَّد بعدُ قواعد الصيانة المحلية ولا من يحق له صيانة المطافئ.","استبدل بطانية الحريق المستعملة، وأبلغ فورًا عن أي مطفأة استُعملت."]}],media:[{kind:"image",src:"media/images/w8_fire_blanket_pan.webp",title:"استخدام بطانية الحريق على حريق مقلاة صغير",description:"عاملة في مطبخ الموظفين تمسك بطانية الحريق أمامها ويداها محميتان خلف القماش، وتضعها برفق فوق مقلاة مشتعلة؛ والباب خلفها مفتوح."}],quiz:[{question:"اشتعلت مقلاة زيت صغيرة على الموقد، ولديك بطانية حريق. ما الطريقة الصحيحة؟",options:[{text:"احمِ يديك بحوافها، وضعها برفق فوق المقلاة، واتركها هناك",correct:!0},{text:"ارمِ البطانية على المقلاة من الطرف الآخر للمطبخ لتبقى بعيدًا عن النار",correct:!1},{text:"غطِّ المقلاة، ثم ارفع البطانية بعد دقيقة لتتأكد من انطفاء النار",correct:!1},{text:"اسكب كوب ماء على المقلاة أولًا، ثم غطّها بالبطانية",correct:!1}],explanation:"ضع البطانية برفق فوق المقلاة ويداك محميتان خلفها، وأطفئ مصدر الحرارة إن استطعت بأمان، واتركها حتى يبرد كل شيء، واتصل بالرقم 115. ولا ماء أبدًا على الزيت المشتعل."},{question:"اشتعلت النار في ملابس زميل في العمل. ماذا تفعل؟",options:[{text:"أجعله يتوقف وينبطح ويتدحرج، وألفّ بطانية حريق حول اللهب إن وُجدت",correct:!0},{text:"أطلب منه أن يركض بسرعة إلى أقرب صنبور ماء ليطفئ الماء اللهب عن جسمه",correct:!1},{text:"أرشّه بمطفأة CO₂ موجّهة مباشرة ومن قرب إلى وجهه وصدره حتى ينطفئ اللهب",correct:!1},{text:"أنزع ملابسه المشتعلة عن جسمه بيديّ العاريتين وبأسرع ما يمكنني",correct:!1}],explanation:"التوقّف والانبطاح والتدحرج تُخمد اللهب، وتساعد بطانية الحريق الملفوفة حوله؛ واحمِ يديك بحوافها. ثم برّد الحرق بالماء البارد الجاري لمدة 20 دقيقة واتصل بالرقم 122."},{question:"من يجب أن يستخدم المطفأة ذات العجلات؟",options:[{text:"العاملون المدرَّبون على هذا الطراز، وفق الملصق، ويُفضَّل في ثنائي",correct:!0},{text:"أي موظف يكون الأقرب إلى النار عندما يرنّ الإنذار",correct:!1},{text:"حارس البوابة فقط، لأن هذه المطافئ تُحفظ قرب البوابة الرئيسية",correct:!1},{text:"أي شخص استخدم مطفأة يدوية صغيرة في البيت مرة واحدة على الأقل",correct:!1}],explanation:"تختلف المطافئ ذات العجلات من طراز لآخر. لا يستخدمها إلا العاملون المدرَّبون على هذا الطراز، وفق الملصق، ويُفضَّل في ثنائي، وبعد فحص «نعم أو لا» نفسه فقط."},{question:"يخرج دخان من تحت غطاء محرّك شاحنة الشركة. ما التصرّف الصحيح؟",options:[{text:"توقّف وأطفئ المحرّك وأخرِج الجميع وابتعد، واتصل بالرقم 115 ولا تفتح الغطاء",correct:!0},{text:"افتح الغطاء بالكامل لتتمكّن من توجيه المطفأة مباشرة إلى المحرّك",correct:!1},{text:"واصل القيادة إلى أقرب ورشة ليفحص الميكانيكي المحرّك",correct:!1},{text:"اسكب ماء زجاجة على المحرّك عبر الفتحة الموجودة تحت الغطاء",correct:!1}],explanation:"فتح الغطاء يدخل هواءً جديدًا فتشتعل النار أكثر. أخرِج الجميع وابتعدوا 30 مترًا (100 قدم) على الأقل، واتصل بالرقم 115، ولا تصبّ الماء أبدًا على حريق المحرّك."},{question:"بطارية عُدّة كهربائية على رفّ الشحن منتفخة ويخرج منها دخان. ماذا تفعل؟",options:[{text:"أفصلها وأبعدها إن كان ذلك آمنًا؛ وإن اشتعلت أخرج وأتصل بالرقم 115",correct:!0},{text:"أغطيها بمسحوق الفئة D، لأن بطاريات الليثيوم أيون حرائق معادن",correct:!1},{text:"أضعها في خزانة معدنية وأغلق بابها بإحكام كي يبقى الدخان في الداخل",correct:!1},{text:"أواصل شحنها، لأن الانتفاخ يزول عندما تمتلئ البطارية تمامًا",correct:!1}],explanation:"الانتفاخ والدخان علامتا خطر. إن كان ذلك آمنًا فافصلها وأبعدها عمّا يحترق؛ وإن اشتعلت فأخرِج الجميع وأغلق الباب واتصل بالرقم 115. وبطاريات الليثيوم أيون ليست من الفئة D."}]}],e={lessons:t};export{e as default,t as lessons};
